ll W, H;
ll p[100000], q[100000];

#define VALUE(x, y) ((x) * 1000000 + (y))

int main(void)
{
    cin >> W >> H;
    rep(i, W) {
        scanf("%lld", &p[i]);
    }
    rep(i, H) {
        scanf("%lld", &q[i]);
    }

    set<ll> cell;
    ll ans = 0;

    multimap<ll, pll> corridor;
    corridor.emplace(0, MP(0,0));

    const ll N = (W + 1) * (H + 1);
    while (cell.size() < N) {
        // コスト最小
        ll len = corridor.begin()->first;
        // 始点
        pll c = corridor.begin()->second;
        corridor.erase(corridor.begin());

        // すでに追加済みか
        if (!cell.insert(VALUE(c.first, c.second)).second) continue;
        ans += len;

        // center = (c.first, c.second)
        const ll x = c.first;
        const ll y = c.second;

        if (x - 1 >= 0 && cell.find(VALUE(x - 1, y)) == cell.end()) {
            corridor.emplace(p[x - 1], MP(x - 1, y));
        }
        if (x + 1 <= W && cell.find(VALUE(x + 1, y)) == cell.end()) {
            corridor.emplace(p[x], MP(x + 1, y));
        }
        if (y - 1 >= 0 && cell.find(VALUE(x, y - 1)) == cell.end()) {
            corridor.emplace(q[y - 1], MP(x, y - 1));
        }
        if (y + 1 <= H && cell.find(VALUE(x, y + 1)) == cell.end()) {
            corridor.emplace(q[y], MP(x, y + 1));
        }
    }
    debug(ans);
    return 0;
}

