    bool unite(int x, int y) {
        x = find(x), y = find(y);
        if(x == y)
            return (false);
        if(data[x] > data[y])
            swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return (true);
    }

    int find(int k) {
        if(data[k] < 0)
            return (k);
        return (data[k] = find(data[k]));
    }
    bool isSame(int x, int y) { return find(x) == find(y); }
    ll size(int k) { return (-data[find(k)]); }
};
ll Kruskal(int vertex_size, vector<pair<ll, pair<int, int>>> edge) {
    int n = vertex_size;
    priority_queue<pair<ll, pair<int, int>>> que;
    for(auto elem : edge) {
        que.push(elem);
    }
    UnionFind uf(n);
    ll w = 0;
    while(!que.empty()) {
        auto e = que.top();
        que.pop();
        if(!uf.isSame(e.second.first, e.second.second)) {
            uf.unite(e.second.first, e.second.second);
            w -= e.first;
        }
    }
    return w;
}
