// A C / C++ program for Prim's Minimum Spanning Tree (MST) algorithm.
// The program is for adjacency matrix representation of the graph

#include <stdio.h>
#include <limits.h>
//#   define ULLONG_MAX	18446744073709551615ULL

// Number of vertices in the graph
llong V = 0;

// A utility function to find the vertex with minimum key value, from
// the set of vertices not yet included in MST
llong minKey(vector<llong>& key, vector<bool>& mstSet)
{
    // Initialize min value
    llong min = LLONG_MAX, min_index;

    for (llong v = 0; v < V; v++)
        if (mstSet[v] == false && key[v] < min)
            min = key[v], min_index = v;

    return min_index;
}

// A utility function to print the constructed MST stored in parent[]
void printMST(vector<llong>& parent, llong n, llong** graph)
{
    //printf("Edge   Weight\n");
    llong sum = 0;
    for (llong i = 1; i < V; i++)
        //printf("%llu - %llu    %llu \n", parent[i], i, graph[i][parent[i]]);
        sum += graph[i][parent[i]];
    cout << sum << endl;
}

// Function to construct and print MST for a graph represented using adjacency
// matrix representation
void primMST(llong** graph)
{
    vector<llong> parent; // Array to store constructed MST
    vector<llong> key;   // Key values used to pick minimum weight edge in cut
    vector<bool> mstSet;  // To represent set of vertices not yet included in MST
    parent.resize(V);
    key.resize(V);
    mstSet.resize(V);

    // Initialize all keys as INFINITE
    for (llong i = 0; i < V; i++)
        key[i] = LLONG_MAX, mstSet[i] = false;
        //key[i] = ULLONG_MAX, mstSet[i] = false;


    // Always include first 1st vertex in MST.
    key[0] = 0;     // Make key 0 so that this vertex is picked as first vertex
    parent[0] = -1; // First node is always root of MST

    // The MST will have V vertices
    for (llong count = 0; count < V-1; count++)
    {
        // Pick the minimum key vertex from the set of vertices
        // not yet included in MST
        llong u = minKey(key, mstSet);

        // Add the picked vertex to the MST Set
        mstSet[u] = true;

        // Update key value and parent index of the adjacent vertices of
        // the picked vertex. Consider only those vertices which are not yet
        // included in MST
        for (llong v = 0; v < V; v++)

            // graph[u][v] is non zero only for adjacent vertices of m
            // mstSet[v] is false for vertices not yet included in MST
            // Update the key only if graph[u][v] is smaller than key[v]
            if (graph[u][v] && mstSet[v] == false && graph[u][v] <  key[v])
                parent[v]  = u, key[v] = graph[u][v];
    }

    // print the constructed MST
    printMST(parent, V, graph);
}


llong** CreateMatrix(llong  W, llong H) {
    llong** matrix = new llong*[W];
    for (llong i = 0; i < W; ++i)
        matrix[i] = new llong[H];
    return matrix;
}

void ZeroMatrix(llong** matrix, llong N) {
    for(llong i = 0; i < N; i++) {
        for(llong j = 0; j < N; j++) {
            matrix[i][j] = 0;
        }
    }
}

void DeleteMatrix(llong** matrix, llong W) {
    for (llong i = 0; i < W; ++i)
        delete [] matrix[i];
    delete [] matrix;
}

