        if(is_p){
            total_cost += horizontal_set_num * cur_cost;
            vertical_set_num --;
        } else {
            total_cost += vertical_set_num * cur_cost;
            horizontal_set_num --;
        }
    }
    cout << total_cost << endl;
}

