using namespace std;

int get(vector<int> &stu, int id){
	int out = stu[id];
	if (out != id) {
		out = get(stu, out);
		stu[id] = out;
	}
	return out;
}

bool myunion(vector<int> &stu, unordered_set<int> &cache, int id1, int id2){
	int a = get(stu, id1);
	int b = get(stu, id2);
	if (a == b){
		return false;
	}
	cache.erase(a);
	stu[a] = b;
	return true;
}

int main(){
	int w, h;
	cin >> w >> h;
	//vector<double> myw(w, 0), myh(h, 0);
	map<int,deque<int>> myw, myh;
	for (int i = 0; i < w; ++i){
		int tmp;
		cin >> tmp;
		myw[tmp].push_back(i);
	}
	for (int i = 0; i < h; ++i){
		int tmp;
		cin >> tmp;
		myh[tmp].push_back(i);
	}
	++w, ++h;
	vector<int> stu(w*h);
	unordered_set<int> cache;
	for (int i = 0; i < w*h; ++i){
		stu[i] = i;
		cache.insert(i);
	}
	int out = 0;
	while (cache.size()>1){
		int id = 0, cost = 0;
		bool tmp = true;
		if (!myh.empty() && !myw.empty()){
			auto a = myh.begin();
			auto b = myw.begin();
			auto c = a->first < b->first ? a : b;
			tmp = a->first < b->first ? true : false;
			id = c->second.front();
			cost = c->first;
		}
		else if (!myh.empty()){
			id = myh.begin()->second.front();
			cost = myh.begin()->first;
			tmp = true;
		}
		else if (!myw.empty()){
			id = myw.begin()->second.front();
			cost = myw.begin()->first;
			tmp = false;
		}

		if (tmp){
			for (int i = 0; i < w; ++i){
				int offset1 = id*w + i;
				int offset2 = (id + 1)*w + i;
				if (myunion(stu, cache, offset1, offset2)){
					out += cost;
				}
			//	cout << tmp << " " << offset1 << " " << offset2 <<" "<< out << endl;
			}
			myh[cost].pop_front();
			if (myh[cost].size() == 0){
				myh.erase(cost);
			}
		}
		else{
			for (int i = 0; i < h; ++i){
				int offset1 = i*w + id;
				int offset2 = offset1 + 1;
				if (myunion(stu, cache, offset1, offset2)){
					out += cost;
				}
				//cout << tmp << " " << offset1 << " " << offset2 <<" "<<out<<endl;
			}
			myw[cost].pop_front();
			if (myw[cost].size() == 0){
				myw.erase(cost);
			}
		}
	}
	cout << out << endl;
	return 0;
}

