int p[100005],q[100005];

P MAX(int x1,int x2,int y1,int y2){
	int X=0,Y=0,w,h;
	for(int i=x1; i<x2; i++){
		if(p[i]>X){
		X=p[i]; w=i;
		}
	}
	for(int i=y1; i<y2; i++){
		if(q[i]>Y){
		Y=q[i]; h=i;
		}
	}
	if(X>Y) return P(w,0);
	else return P(h,1);
}

ll MST(int x1,int x2,int y1,int y2){
	if(x1==x2&&y1==y2) return 0;
	int cut=MAX(x1,x2,y1,y2).first;
	bool xy=MAX(x1,x2,y1,y2).second;
	if(xy==0){
	  ll Z=MST(x1,cut,y1,y2)+MST(cut+1,x2,y1,y2)+p[cut];
	  return Z;
	}else{
	  ll Z=MST(x1,x2,y1,cut)+MST(x1,x2,cut+1,y2)+q[cut];
	  return Z;
	}
 }

