using ll = long long;

ll calc(int h, int w, vector <ll> &p, vector <ll> &q){
  ll column_cost = accumulate(ALL(p), 0LL);
  ll row_cost = accumulate(ALL(q), 0LL);
  ll base_cost = column_cost * (h+1) + row_cost;
  for (int i = 0; i < sz(p); i++) {
    if (q[0] < p[i]) {
      base_cost -= p[i] - q[0];
    }
  }
  if (h > 1) {
    for (int i = 0; i < sz(p); i++) {
      if (q.back() < p[i]) {
        base_cost -= p[i] - q.back();
      }
    }
  }
  return base_cost;
}

