typedef pair<int, int> P;

int main() {
    int W, H;

    cin >> W >> H;

    vector<lint> p(W);
    vector<lint> q(H);

    for(int i = 0; i < W ; ++i){
        cin >> p[i];
    }
    for(int i = 0; i < H; ++i){
        cin >> q[i];
    }

    set<P> uset;

    priority_queue<vector<lint>> que;

    uset.insert(make_pair(0, 0));

    que.push({-p[0], 1, 0});
    que.push({-q[0], 0, 1});

    lint cost = 0;

    while(!que.empty()){
        vector<lint> tmp = que.top(); que.pop();
        if(tmp[1] < 0 | tmp[1] > W | tmp[2] < 0 | tmp[2] > H){
            continue;
        }

        if(uset.find(make_pair(tmp[1], tmp[2])) == uset.end()){
            uset.insert(make_pair(tmp[1], tmp[2]));
            cost -= tmp[0];

            if(uset.find(make_pair(tmp[1] + 1, tmp[2])) == uset.end()){
                que.push({-p[tmp[1]], tmp[1] + 1, tmp[2]});
            }
            if(uset.find(make_pair(tmp[1], tmp[2] + 1)) == uset.end()){
                que.push({-q[tmp[2]], tmp[1], tmp[2] + 1});
            }
            if(uset.find(make_pair(tmp[1] - 1, tmp[2])) == uset.end()){
                que.push({-p[tmp[1] - 1], tmp[1] - 1, tmp[2]});
            }
            if(uset.find(make_pair(tmp[1], tmp[2] - 1)) == uset.end()){
                que.push({-q[tmp[2] - 1], tmp[1], tmp[2] - 1});
            }
        }
    }
    cout << cost << endl;
}

