int compare (const void * a, const void * b)
{
	unsigned int x = *(unsigned int *)a;
	unsigned int y = *(unsigned int *)b;
	if (x < y) {
		return -1;
	}
	else if (x == y) {
		return 0;
	}
	else {
		return 1;
	}
}

int main(int argc, char * argv[])
{
	unsigned int w = 0;
	unsigned int h = 0;

	while (cin >> w >> h) {
		unsigned int cost_w[w];
		unsigned int cost_h[h];

		for (unsigned int i = 0; i < w; ++i) {
			cin >> cost_w[i];
		}
		for (unsigned int i = 0; i < h; ++i) {
			cin >> cost_h[i];
		}

		qsort(cost_w, w, sizeof(unsigned int), compare);
		qsort(cost_h, h, sizeof(unsigned int), compare);

		unsigned int number_w = 0;
		unsigned int number_h = 0;
		unsigned long total = 0;
		for (unsigned int i = 0; i < w + h; ++i) {
			unsigned int count = 0;
			unsigned int cost = 0;

			if (number_w < w && number_h < h) {
				if (cost_w[number_w] <= cost_h[number_h]) {
					count = h + 1 - number_h;
					cost = cost_w[number_w];
					++number_w;
				}
				else {
					count = w + 1 - number_w;
					cost = cost_h[number_h];
					++number_h;
				}
			}
			else if (number_w < w) {
				count = h + 1 - number_h;
				cost = cost_w[number_w];
				++number_w;
			}
			else {
				count = w + 1 - number_w;
				cost = cost_h[number_h];
				++number_h;
			}
			total += count * cost;
		}
		cout << total << endl;
	}
	return 0;
}

