struct UnionFind {
    vector<int> p;
    UnionFind(ll n) : p(n, -1) {};
    bool unite(ll u, ll v) {
        if ((u = root(u)) == (v = root(v))) return false;
        if (p[u] > p[v]) swap(u, v);
        p[u] += p[v]; p[v] = u;
        return true;
    }
    bool find(ll u, ll v) { return root(u) == root(v); }
    int root(ll u) { return p[u] < 0 ? u : p[u] = root(p[u]); }
    int size(ll u) { return -p[root(u)]; }
};

struct Edge {
    int from, to, cost;
    bool b;
    Edge(int a, int b, int c, bool d) : from(a), to(b), cost(c), b(d) {};
    bool operator<(Edge& e) {
        return cost < e.cost;
    }
};

