			int t = (j*(W + 1)) + i + 1;
			es.emplace_back(p, s, t);
		}
	}
	REP(j, H) {
		int q;
		cin >> q;
		REP(i, W + 1) {
			int s = (j*(W + 1)) + i;
			int t = ((j + 1)*(W + 1)) + i;
			es.emplace_back(q, s, t);
		}
	}
	sort(ALL(es));

	ll ans = 0;
	for (const auto& e : es) {
		int cost, s, t;
		tie(cost, s, t) = e;
		if (uf.unionSet(s, t)) {
			ans += cost;
		}
	}
	cout << ans << endl;
	return 0;
}

