struct DSU {
    vi parent;
    vi sz;
    int cnt = 0;

    DSU(int n) {
        parent.resize(n, 0);
        sz.resize(n, 0);
    }

    void make_set(int v) {
        parent[v] = v;
        sz[v] = 1;
        cnt++;
    }

    int find_set(int v) {
        return parent[v] == v ? v : parent[v] = find_set(parent[v]);
    }

    void union_sets(int u, int v) {
        u = find_set(u);
        v = find_set(v);
        if (u == v)
            return;
        cnt--;
        if (sz[u] < sz[v])
            swap(u, v);
        parent[v] = u;
        sz[u] += sz[v];
    }
};

void smain() {

