        edges.push_back({p, {1, i}});
    }

    DSU wdsu(w + 1), hdsu(h + 1);
    fori (i, w + 1) {
        wdsu.make_set(i);
    }
    fori (i, h + 1) {
        hdsu.make_set(i);
    }

