        int cost = e.first;
        int i = e.second.second;
        if (e.second.first) {
            ans += (ll) cost * wdsu.cnt;
            hdsu.union_sets(i, i + 1);
        } else {
            ans += (ll) cost * hdsu.cnt;
            wdsu.union_sets(i, i + 1);
        }
//        watch(ans);
    }
    cout << ans;
}

