int cal(int w, int h, int* p, int *q)
{
    std::sort(p, p+w);
    std::sort(q, q+h);
    long long mulq = w +1;
    long long mulp = h+ 1;
    int pi = 0;
    int qi = 0;
    long long res = 0;
    while (pi < w || qi < h) {
        if (p[pi] < q[qi]) {
            res += p[pi] * mulp;
            mulq--;
            pi++;
        } else {
            res += q[qi] * mulq;
            mulp--;
            qi++;
        }
    }
    return res;
}


