vector<i64> Q;

void solve() {
    deque<tuple<i64,i64,bool>> v;
    REP(x, W) {
        v.emplace_back(P[x], x, false);
    }
    REP(y, H) {
        v.emplace_back(Q[y], y, true);
    }
    ALL(sort, v);

    i64 ans = 0;
    i64 cols = W+1;
    i64 rows = H+1;
    while(!(cols == 1 && rows == 1)) {
        i64 cost; i64 i; bool vert; tie(cost,i,vert) = POP_FRONT(v);
        if(vert) {
            assert(rows >= 2);
            ans += cost * cols;
            --rows;
        }
        else {
            assert(cols >= 2);
            ans += cost * rows;
            --cols;
        }
    }

    PRINTLN(ans);
}

