struct node{
	int x,y;
	ll val;
	bool operator <(const node & a) const{
		return val>a.val;
	}
	node(int xx,int yy,int vall):x(xx),y(yy),val(vall){}
};
int main(){
	int W,H;
	cin>>W>>H;
	vector<ll> p(W);
	vector<ll> q(H);
