				else if(x==pp.x-1) c=p[x];
				else if(y==pp.y+1) c=q[pp.y];
				else c=q[y];
				if(visit[x][y]>c){
					visit[x][y]=c;
					qu.push(node(x,y,c));
				}
			}
		}
