		if(i==0)ruiq[i]=qqsort[0];
		else ruiq[i]=ruiq[i-1]+qqsort[i];
	}
	rep(i,w)
	{
		long long tt=(long long)(upper_bound(all(qqsort),p[i])-qqsort.begin());
		if(tt!=0)
		{
			ans+=ruiq[tt-1]+p[i]*(h-tt);
		}
		else ans+=p[i]*h;
	}
	ans+=wa;
	ans+=ha;
	cout<<ans<<endl;
	return 0;
}

