using namespace std;

typedef long long ll;

#define DIR_W false
#define DIR_H true

struct Data {
  ll v;
  bool dir;
  bool operator < (const Data &data) const {
    if( v != data.v ) return v < data.v;
    return dir < data.dir;
  }
};

#define MAX 100010

int W,H;
ll p[MAX], q[MAX];

void compute() {
  vector<Data> vec;
  rep(i,W) vec.push_back((Data){p[i],DIR_W});
  rep(i,H) vec.push_back((Data){q[i],DIR_H});
  sort(vec.begin(),vec.end());
  int used_H = 0, used_W = 0;
  ll mini = 0;
  rep(i,(W+H)) {
    if( vec[i].dir == DIR_W ) {
      mini += ( (H+1) - used_H ) * vec[i].v;
      ++used_W;
    } else {
      mini += ( (W+1) - used_W ) * vec[i].v;
      ++used_H;
    }
  }
  cout << mini << endl;
}

int main() {
  cin >> W >> H;
  rep(i,W) cin >> p[i];
  rep(i,H) cin >> q[i];
  compute();
  return 0;
}

