class Main{
	public:

	void run(){
		int W,H;cin >> W >> H;

		vector<ll> ps(W),qs(H);cin >> ps >> qs;
		priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<pair<ll,int>>> que_p,que_q;

		for(ll p:ps) que_p.push(make_pair(p,0));
		for(ll q:qs) que_q.push(make_pair(q,0));

		ll res = 0;
		int pc = 0,qc = 0;
		while(!que_p.empty() || !que_q.empty()){
			ll v_p,v_q;bool t;

			bool is_p = false,is_q = false;
			if(!que_p.empty()){
				tie(v_p,t) = que_p.top();
				is_p=true;
			}
			if(!que_q.empty()){
				tie(v_q,t) = que_q.top();
				is_q=true;
			}
			if(!que_p.empty() && !que_q.empty()){
				if(v_p < v_q){
					is_p = true;is_q = false;
				}else{
					is_q = true;is_p=false;
				}
			}
			// cerr << (H+1-qc) <<" " << v_p << endl;
			// cerr << (W+1-pc) << " " <<  v_q << endl;

			if(is_p) que_p.pop();
			if(is_q) que_q.pop();
			if(is_p){
				// cerr << (H+1-qc) <<" " << v_p << endl;
				res += (H+1-qc)*v_p;
				pc++;
			}else{
				// cerr << (W+1-pc) <<" " << v_q << endl;
				res += (W+1-pc)*v_q;
				qc++;
			}
		}
		cout << res << endl;
	}
};

int main(){
	cout <<fixed<<setprecision(20);
	cin.tie(0);
	ios::sync_with_stdio(false);
	Main().run();
	return 0;
}

