vector<bool> used;
long long V;

int prim() {
  for (int i = 0; i < V; ++i) {
  mincost[i] = inf;
  used[i] = false;
  }
  mincost[0] = 0;
  int res = 0;
  while(true) {
  int v = -1;
  // X に属さない頂点のうち X からの辺のコストが最小になる頂点を探す
  for (int u = 0; u < V; u++) {
  if (!used[u] && (v == -1 || mincost[u] < mincost[v])) v = u;
  }
  if (v == -1) break;
  used[v] = true;
  // 頂点 v を X に追加
  res += mincost[v]; // 辺のコストを加える
  // for (int u = 0; u < V; u++) {
  // mincost[u] = min(mincost[u], cost[v][u]);
  // }
  mincost[v]=min(mincost[v], p[v%w]);
  mincost[v]=min(mincost[v], q[v/w]);
  mincost[v]=min(mincost[v], p[v%w-1]);
  mincost[v]=min(mincost[v], q[v/w-1]);
  }
  return res;
}

