typedef long long int LL;
struct edge { LL u, v, cost; };
bool comp(const edge& e1, const edge& e2)
{
	return e1.cost < e2.cost;
}

class Union_Find
{
	std::vector<LL>per;
	std::vector<LL>rank;
public:
	void init(LL size)
	{
		rep(i, size)
		{
			per.push_back(i);
			rank.push_back(0);
		}
	}
	LL get_per(LL x)
	{
		if (x == per[x]) return x;
		return per[x] = get_per(per[x]);
	}
	bool is_same_per(LL x, LL y)
	{
		return get_per(x) == get_per(y);
	}
	void togett(LL x, LL y)
	{
		int x_per = get_per(x), y_per = get_per(y);
		if (x_per == y_per) return;
		if (rank[x_per] < rank[y_per]) per[x_per] = y_per;
		else
		{
			per[y_per] = x_per;
			if (rank[x_per] == rank[y_per]) ++rank[x_per];
		}
	}
};

LL W, H;
Union_Find tree;
std::vector<edge>edges;

LL kruskal()
{
	std::sort(edges.begin(), edges.end(), comp);
	LL res = 0;
	for (auto e : edges)
	{
		if (!tree.is_same_per(e.u, e.v))
		{
			tree.togett(e.u, e.v);
			res += e.cost;
		}
	}
	return res;
}

