	{
		rep(j, W - 1)
		{
			edges.push_back({ i*W + j,i*W + j + 1,p[j] });
			edges.push_back({ i*W + j,(i + 1)*W + j,q[i] });
		}
	}
	rep(i, H - 1) edges.push_back({ i*W + (W - 1),(i + 1)*W + (W - 1),q[i] });
	rep(j, W - 1) edges.push_back({ (H - 1)*W + j,(H - 1)*W + j + 1,p[j] });
	out << kruskal() << std::endl;
	return 0;
}

