//コスト/場所
typedef pair<int,int>P;

#define int long long

class RMQ{
 private:
	static const int MAX_N = 100010;
	int n;
	P dat[2*MAX_N -1];

	//[a,b)の最小値を返す
	//kは節点の番号l,rはその節点が[l,r)を保持している
	P rec(int a,int b,int k,int l,int r){
		if(b <= l || r <= a){
			return P(-1,-1);
		}
		if(a<=l && r<=b){
			return dat[k];
		}
		else{
			P rl = rec(a,b,2*k+1,l,(l+r)/2);
			P rr = rec(a,b,2*k+2,(l+r)/2,r);
			return max(rl,rr);
		}
	}

public:
	void init(int n_){
		n=1;
		while(n < n_) n*=2;
		for(int i=0;i<2*n-1;i++){
			dat[i] = P(-1,-1);
		}
	}

	//kをaに変更
	void update(int k, P p){
		int reaf = k+n-1;
		dat[reaf]=p;
		while(reaf>0){
			reaf = (reaf-1)/2;
			dat[reaf]=max(dat[reaf*2+1],dat[2*reaf+2]);
		}
	}

	//query[a,b]の範囲内の最小値を返す
	P query(int a,int b){
		return rec(a,b+1,0,0,n);
	}
void out(int a, int b){
	P p = query(a,b);
	cout<<p.first<<" "<<p.second<<endl;
}
};

int w,h;
RMQ wr,hr;

int ruiw[100010];
int ruih[100010];


int solve(int mnw, int mnh, int mxw, int mxh){
	int sum=0;
	if(mnw>mxw || mnh>mxh);
	else if(mnw==mxw){
		sum= ruih[mxh-1]-ruih[mnh-1];
	}
	else if(mnh==mxh){
		sum= ruiw[mxw-1]-ruiw[mnw-1];
	}
	else{
		P wt = wr.query(mnw,mxw-1);
		P ht = hr.query(mnh,mxh-1);
		if(wt.first>ht.first){

			sum+=wt.first;
			sum+=solve(mnw,mnh,wt.second,mxh);
			sum+=solve(wt.second+1,mnh,mxw,mxh);
		}
		else{
			sum+=ht.first;
			sum+=solve(mnw,mnh,mxw,ht.second);
			sum+=solve(mnw,ht.second+1,mxw,mxh);
		}
	}
	return sum;
}

