long long solve (const int p[100001], const int q[100001], int sw, int sh, int w, int h) {
	if (w == 0 && h == 0) {
		return 0;
	}

#ifdef DEBUG
		cout << "start:" <<  sw << "," << sh << " w= " << w << ", h= " <<h << " ";
#endif

	int maxp = 0, maxq = 0;
	int iw = -1, ih = -1;
	REP(i, sw, w + sw)  if (p[i] > maxp) {maxp = p[i]; iw = i;};
	REP(i, sh, h + sh)  if (q[i] > maxq) {maxq = q[i]; ih = i;};

	if (maxp > maxq) {
#ifdef DEBUG
		cout << "cost+:" <<maxp << endl;
#endif
		int x = solve(p, q, iw + 1, sh, sw + w - iw - 1, h);
		int y = solve(p, q, sw, sh, iw - sw, h);
		return maxp + x + y;
	}
	else {
#ifdef DEBUG
		cout << "cost+:" <<maxq << endl;
#endif
		int x = solve(p, q, sw, ih + 1, w, sh + h - ih - 1);
		int y = solve(p, q, sw, sh, w, ih - sh);
		return maxq + x + y;
	}
}


