void solve()
{
	int w,h;
	cin>>w>>h;
	vector<int>pw;
	vector<int>qh;
	int result=0;
	vector<vector<bool>>used(w,vector<bool>(h,false));
	vector<vector<int>>cost(w,vector<int>(h,std::numeric_limits<int>::max()));

	for(int i=0;i<w;++i)
	{
		int t;
		cin>>t;
		pw.push_back(t);
	}
	for(int i=0;i<h;++i)
	{
		int t;
		cin>>t;
		qh.push_back(t);
	}

	cost[0][0]=0;
	used[0][0]=true;

	while(true)
	{
		int ii=-1;
		int jj=-1;
		for(int i=0;i<w;++i)
			for(int j=0;j<h;++j)
			{
				if(!used[i][j]&&(ii==-1||cost[i][j]<cost[ii][jj])){ii=i;jj=j;}
			}
		if(ii==-1)break;
		used[ii][jj]=true;
		result+=cost[ii][jj];
		if(ii>0)cost[ii-1][jj]=min(cost[ii-1][jj],pw[ii-1]);
		if(jj>0)cost[ii][jj-1]=min(cost[ii][jj-1],qh[jj-1]);
		if(ii<w-1)cost[ii+1][jj]=min(cost[ii+1][jj],pw[ii]);
		if(jj<h-1)cost[ii][jj+1]=min(cost[ii][jj+1],qh[jj]);
	}
	cout<<result<<endl;


}

int main()
{
	solve();
	return 0;
}

