struct Edge{
	int a,b;	//頂点.
	int cost;	//コスト.

	bool operator==(const Edge &another) const{return (a==another.a and b==another.b and cost==another.cost)?true:false;}
	bool operator!=(const Edge &another) const{return (a!=another.a or b!=another.b or cost!=another.cost)?true:false;}
	bool operator<(const Edge &another) const{return cost<another.cost;}
	bool operator>(const Edge &another) const{return cost>another.cost;}
};

struct UnionFind{
	std::vector<int> par;//xの親はpar[x]. もしx自身が親ならpar[x]<0で,-par[x]がその集合のサイズ.
	int num;			 //Number of group.

	UnionFind(int n):par(n,-1),num(n){}//Constructor.

	void reset(int n){par.assign(n,-1),num=n;}
	int root(int x){return (par[x]<0)?x:par[x]=root(par[x]);}//Recrusion.
	int size(int x){return -par[root(x)];}
	bool same(int x,int y){return root(x)==root(y);}
	bool unite(int x,int y){
		x=root(x), y=root(y);
		if(x==y) return false;//Do nothing.
		if(size(x)<size(y)) std::swap(x,y);//Merge technique.
		par[x]+=par[y];
		par[y]=x;
		num--;
		return true;
	}
};

