struct BinaryIndexTree{
    int N;
    vector<int> bit;
    BinaryIndexTree(int n): N(n),bit(n+1,0){}
    void add(int a,int w){
        for(int x=a+1;x<=N;x+=x&(-x)) bit[x]+=w;
