int Prim(vector<vector<int>>& v)
{
	int N = (W + 1) * (H + 1);
	vector<bool> vis(N);
	vector<int> dis(N);
	int i, j;
	for (i = 0; i < N; i++)
		dis[i] = v[0][i];
	vis[0] = 1;
	int ans = 0;
	for (i = 1; i < N; i++)
	{
		int t = INT_MAX, k = 0;
		for (j = 1; j < N; j++)
		{
			if (!vis[j] && dis[j] < t)
			{
				t = dis[j];
				k = j;
			}
		}
		vis[k] = 1;
		ans += t;
		for (j = 1; j < N; j++)
		{
			if (v[k][j] < dis[j])
				dis[j] = v[k][j];
		}
	}
	return ans;
}

