    cin >> W >> H;
    Ps.resize(W);
    Qs.resize(H);
    REP(w,W) cin >> Ps[w];
    REP(h,H) cin >> Qs[h];

    pseg.init(W);
    qseg.init(H);
    REP(w,W) {
        pseg.update(w, offset - Ps[w]);
    }
    REP(h,H) {
        qseg.update(h, offset - Qs[h]);
    }

    cout << func(0, W, 0, H) << endl;

    return 0;
}

