		{
			for (j = 0; j <= H; j++)
			{
				int x = getId(pr.second, j), y = getId(pr.second + 1, j);
				int px = getPar(p, x), py = getPar(p, y);
				if (px == py)
					continue;
				p[px] = py;
				ans += pr.first;
				k++;
			}
		}
		else
		{
			for (j = 0; j <= W; j++)
			{
				int x = getId(j, pr.second - M), y = getId(j, pr.second - M + 1);
				int px = getPar(p, x), py = getPar(p, y);
				if (px == py)
					continue;
				p[px] = py;
				ans += pr.first;
				k++;
			}
		}
	}
	cout << ans << endl;
	return 0;
}

