struct UF{
	vector<int> belong;
	vector<int> size;
	int S;
	void resize(int n){
		belong.assign(n + 1, -1);
		size.assign(n + 1, 1);
		S = 0;
	}
	inline int root(int b){
		if (belong[b] == -1){
			return b;
		}
		belong[b] = root(belong[b]);
		return belong[b];
	}
	void merge(int a, int b){
		a = root(a);
		b = root(b);
		if (a == b)return;
		S++;
		belong[a] = b;
		size[b] += size[a];
	}
};

UF u1;
UF u2;


int main(){
