using namespace std;
typedef long long ll;

// vector<ll> p, q;
ll p[100001], q[100001];

struct edge {
  bool isx;
  ll x;
  ll y;
};

bool operator<(const edge& e0, const edge& e1) {
  return (e0.isx?p[e0.x]:q[e0.y]) > (e1.isx?p[e1.x]:q[e1.y]);
}

int main() {
  ll w, h;
  cin >> w >> h;
  REP(i,0,w) {
    cin >> p[i];
  }
  REP(i,0,h) {
    cin >> q[i];
  }
  set<pair<ll,ll>> v;
  priority_queue<edge> e;
  v.insert({0LL, 0LL});
  e.push({true, 0LL, 0LL});
  e.push({false, 0LL, 0LL});
  ll cost = 0LL;
  while((ll)v.size() < (w+1LL)*(h+1LL)) {
    edge e0 = e.top();
    e.pop();
    pair<ll,ll> v0, v1;
    v0 = {e0.x, e0.y};
    if(e0.isx) {
      v1 = {e0.x+1, e0.y};
    } else {
      v1 = {e0.x, e0.y+1};
    }
    if(v0.first < 0 || v0.second < 0 ||
       v1.first > w || v1.second > h) {
      continue;
    }
    if(v.count(v0) && v.count(v1)) {
      continue;
    } else if(v.count(v0) && !v.count(v1)) {
      v.insert(v1);
      e.push({true, v1.first, v1.second});
      e.push({false, v1.first, v1.second});
      e.push({true, v1.first-1, v1.second});
      e.push({false, v1.first, v1.second-1});
    } else if(v.count(v1) && !v.count(v0)) {
      v.insert(v0);
      e.push({true, v0.first, v0.second});
      e.push({false, v0.first, v0.second});
      e.push({true, v0.first-1, v0.second});
      e.push({false, v0.first, v0.second-1});
    } else {
      continue;
    }
    cost += e0.isx ? p[e0.x] : q[e0.y];
  }
  cout << cost << endl;
  return 0;
}

