	std::sort(d,d+m,[](data &u,data &v){return u.s<v.s;});
	++w;
	++h;
	long long ans=0;
	for(int i=0;i<m;++i){
		if(d[i].t==0){
			ans+=(long long)d[i].s*(long long)h;
			--w;
		}
		else{
			ans+=(long long)d[i].s*(long long)w;
			--h;
		}
	}
	out<ans<'\n';
	out.print();
	in.close();
	out.close();
	return 0;
}

