void solve() {

    int n, m;
    scanf("%d%d", &n, &m);

    for (int i = 0; i < n; ++i) scanf("%d", a + i);
    for (int i = 0; i < m; ++i) scanf("%d", b + i);

    sort(a, a + n);
    sort(b, b + m);

    ll cost = 0;
    ll edges = 0;
    ll vs = (ll) (n + 1) * (m + 1);

    int ac = n + 1;
    int bc = m + 1;

    for (int i = 0, j = 0; edges < vs - 1;) {
        assert(i < n || j < m);
        if (j == m || (i < n && a[i] < b[j])) {
            edges += bc;
            cost += (ll)bc * a[i];
            ++i;
            --ac;
            //cerr << "a" << endl;
        } else {
            edges += ac;
            cost += (ll)ac * b[j];
            ++j;
            --bc;
            //cerr << "b" << endl;
        }
    }

    cout << cost << '\n';
}



