            siz[y]=siz[x]+siz[y];
        }
        else {
            par[y]=x;
            siz[x]=siz[x]+siz[y];
        }
    }

    bool same(ll x, ll y) {
        return find(x)==find(y);
    }

    ll size(ll x) {
        return siz[find(x)];
    }
