void unite(int x ,int y){
  x=find(x);
  y=find(y);
  if(x==y) return ;

  if((int)rank1[x]<(int)rank1[y]){
    par[x]=y;
  }else {
    par[y]=x;
    if(rank1[x]==rank1[y]) rank1[x]++;
  }
}
