vector<vector<bool>> visited(1000);

void init()
{
    for (int i = 0; i < 1000; ++i) {
        visited[i] = vector<bool>(1000);
        for (int j = 0; j < 1000; ++j) {
            visited[i][j] = false;
        }
    }
}

void visit(int i, int j)
{
    visited[i][j] = true;
}

bool exists(int i, int j, int W, int H)
{
    return 0 <= i && i <= W && 0 <= j && j <= H;
}

int buildFrom(int i, int j, vector<int> const &ps, vector<int> const &qs,  int cost)
{
    int const W = ps.size();
    int const H = qs.size();
    multimap<int, pair<int, int>> ways;
    if (exists(i, j + 1, W, H)) {
       ways.insert(make_pair(qs[j], pair<int, int>{ i, j + 1 }));
    }
    if (exists(i, j - 1, W, H)) {
        ways.insert(make_pair(qs[j - 1], pair<int, int>{ i, j - 1 }));
    }
    if (exists(i + 1, j, W, H)) {
        ways.insert(make_pair(ps[i], pair<int, int>{ i + 1, j }));
    }
    if (exists(i - 1, j, W, H)) {
        ways.insert(make_pair(ps[i - 1], pair<int, int>{ i - 1, j }));
    }
    for (auto itr = ways.begin(); itr != ways.end(); ++itr) {
        int ni = itr->second.first;
        int nj = itr->second.second;
        if (!visited[ni][nj]) {
            visit(ni, nj);
            cost = buildFrom(ni, nj, ps, qs, cost + itr->first);
        }
    }
    return cost;
}

