int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  int w, h;
  cin >> w >> h;
  ll res = 0;
  vector<ll> a(w), b(h);
  for (ll &x : a) {
    cin >> x;
  }
  for (ll &x : b) {
    cin >> x;
  }
  sort(a.begin(), a.end());
  vector<ll> pref(w);
  for (int i = 0; i < a.size(); i++) {
    pref[i] = a[i];
    if (i > 0) {
      pref[i] += pref[i - 1];
    }
  }
  for (int i = 0; i < h; i++) {
    int l = -1, r = w;
    while (r - l > 1) {
      int m = (l + r) / 2;
      if (a[m] <= b[i]) {
        l = m;
      } else {
        r = m;
      }
    }
    if (l >= 0) {
      res += pref[l];
    }
    res += b[i] * (w - l);
  }
  res += pref.back();
  cout << res;
  return 0;
}

