// union-find
struct union_find {
    vector<int> data;

    union_find(int size) {data.resize(size,-1);}

    int find(int x) {
        if (data[x] < 0) {return x;}
        return data[x] = find(data[x]);
    }

    bool unite(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) {return false;}
        if (data[x] > data[y]) swap(x,y);
        data[x] += data[y];
        data[y] = x;
        return true;
    }

    int size(int x) {return -data[find(x)];}
};

//kruskal(O(ElogE))
template<class T> 
struct kruskal {
    struct edge {
        int from, to;
        T cost;
    };
    vector<edge> edges;
    int V;
    kruskal(int v): V(v) {}
    void add_edge(int a, int b, T cost) {
        edges.push_back(edge{a,b,cost});
    }
    T run() {
        sort(edges.begin(),edges.end(),[](const edge &a, const edge &b) {
            return a.cost < b.cost;
        });
        union_find uf(V);
        T res = 0;
        for (edge &e : edges) {
            if (uf.unite(e.to,e.from)) {
                res += e.cost;
            }
        }
        return res;
    }
};

int main() {
    int w, h; cin >> w >> h;
    kruskal<ll> ks((w + 1) * (h + 1));
    rep(i,w) {
        int x; cin >> x;
        rep(j,h+1) {
            int l = j * (w + 1) + i;
            int r = l + 1;
            ks.add_edge(l, r, x);
        }
    }
    rep(i,h) {
        int x; cin >> x;
        rep(j,w+1) {
            int low = i * (w + 1) + j;
            int up = low + (w + 1);
            ks.add_edge(low, up, x);
        }
    }
    cout << ks.run() << endl;
}

