    cin >> k;
    if(i < w){
      p[i] = edge{i,i+1,k,0};
    }
    else
      p[i] = edge{i - w,i+1 - w,k,1};
  }
  sort(all(p),comp);
  a = w+1,b = h+1;
  k = 0;
  Union_Find W,H;
  W.init(a+5),H.init(b+5);
  rep(i,p.size()){
      if(p[i].i && !W.same(p[i].u,p[i].v)){
      k += p[i].cost * a;
      W.Unite(p[i].u,p[i].v);
      --b;
    }
    else if(!p[i].i && !H.same(p[i].u,p[i].v)){
      k += p[i].cost * b;
      H.Unite(p[i].u,p[i].v);
      --a;
    }
  }
  cout << k << endl;
  return 0;
}

