        res += r[i].first;
      }
    }else{
      int y = r[i].second - W;
      REP(x, W + 1) {
        if(uf.same(y * (W + 1) + x, (y + 1) * (W + 1) + x)) continue;
        uf.unite(y * (W + 1) + x, (y + 1) * (W + 1) + x);
        res += r[i].first;
      }
