  vector<ll> p(w),q(h);
  rep(i,w){
    cin >> p[i];
  }
  rep(j,h){
    cin >> q[j];
  }
  rep(i,w+1){
    dp[i][0] = 1;
    dp[i][1] = 1;
  }
  rep(j,h+1){
    dp[1][j] = 1;
    dp[0][j] = 1;
  }
  if(q[0] < p[0]){
    dp[1][1] = p[0] + 2 * q[0];
  }
  else{
    dp[1][1] = 2 * p[0] + q[0];
  }
