class UnionFind {
public:
    vector<int> par;
    int cnt;
    UnionFind(int n) {
        par.resize(n);
        REP(i, 0, n) {
            par[i] = i;
        }
        cnt = n;
    }
    int Find(int n) {
        return (n == par[n] ? n : par[n] = Find(par[n]));
    }
    bool Union(int a, int b) {
        a = Find(a);
        b = Find(b);
        if (a == b) return false;
        par[a] = b;
        cnt--;
        return true;
    }
    int getCnt() {
        return cnt;
    }
};

