  k=0;
  for(j=0;j<=H;j++){
    for(i=0;i<=W;i++) {
      if(i<W){
        es[k].u=j*(W+1)+i;      
        es[k].v=j*(W+1)+i+1;
        es[k].cost=p[i];
        k++;
      }
      if(j<H){
