				ans += p[i1] * (h - i2 + 1);
				i1++;
				continue;
			}

			if(p[i1] < q[i2]) {
				ans += p[i1] * (h - i2 + 1);
				i1++;
			} else {
				ans += q[i2] * (w - i1 + 1);
				i2++;
			}
		}

		cout << ans << endl;
	}
};

