        if(Q[i] < P[0]) ans += Q[i] * (W + 1);
        else{
            auto iter = upper_bound(P.begin(), P.end(), Q[i]);
            ll idx = iter - P.begin();
            idx--;
            ans += P_acc[idx];
            ans += Q[i] * (W - idx);
        }
    }
    cout << ans << endl;
}

