void uf_init(int n) {
  rep(i,n+1) { parent[i] = i; rank[i] = 0; }
}
int find(int x) {
  if (parent[x] == x) return x;
  else return parent[x] = find(parent[x]);
}
void unite(int x, int y) {
  x = find(x);
  y = find(y);
  if(x == y) return;
  if (rank[x] < rank[y]) parent[x] = y;
  else {
    parent[y] = x;
    if(rank[x] == rank[y]) rank[x]++;
  }
}
bool same(int x, int y) {
  return find(x) == find(y);
}


