    MinimumSpanningTree<ll> mst((w + 1) * (h + 1));
    rep(y, h + 1) {
        rep(x, w + 1) {
            ll idx = y * (w + 1) + x;
            // 上方向
            if (y < h) {
                mst.add_edge(idx, idx + (w + 1), q[y]);
            }
            // 下方向
            if (y > 0) {
                mst.add_edge(idx, idx - (w + 1), q[y - 1]);
            }
            // 右方向
            if (x < w) {
                mst.add_edge(idx, idx + 1, p[x]);
            }
            // 左方向
