      q.push(edge(e.to, idx(x - 1, y), cost_x[x - 1]));
    }
    if (x < W && !checked[idx(x + 1, y)]) {
      q.push(edge(e.to, idx(x + 1, y), cost_x[x]));
    }
    if (y > 0 && !checked[idx(x, y - 1)]) {
      q.push(edge(e.to, idx(x, y - 1), cost_y[y - 1]));
    }
    if (y < H && !checked[idx(x, y + 1)]) {
      q.push(edge(e.to, idx(x, y + 1), cost_y[y]));
    }
  }
  cout << ans << endl;
  return 0;
}

