{
  ll par[MAX_N];

  /*　初期化　*/
  void init(int n)
  {
    for (int i = 0; i < n; i++) par[i] = i;
  }

  /*　root(一番上)を返す　*/
  int root(int x)
  {
    return ((x == par[x]) ? (x) : (par[x] = root(par[x])));
  }

  /*　yの下にxをぶら下げる　*/
  void unite(int x, int y)
  {
    x = root(x);
    y = root(y);
    if (x == y) return;
    par[x] = y;
  }

  /*　xとyのrootが同じであればtrueを返す　*/
  bool same(int x, int y)
  {
    return root(x) == root(y);
  }
}uf;
