SegTree<PLL> xSeg(100100,{-1,-1},f); // {p_i,i}
SegTree<PLL> ySeg(100100,{-1,-1},f); // {q_i,i}

// X座標が(a,b)，Y座標が(c,d)の矩形における最小コスト
ll solve(ll a, ll b, ll c, ll d){
    if(a==b && c==d){
        return 0;
    }
    auto xMax = xSeg.query(a,b); // x方向の最大辺
    auto yMax = ySeg.query(c,d); // y方向の最大辺
    ll ans=-1;
    if(xMax > yMax){ // todo: xMax==yMaxの場合は？
        ll k = xMax.second;
        ans= solve(a,k,c,d) + solve(k+1,b,c,d) + xMax.first;
    } else {
        ll k = yMax.second;
        ans = solve(a,b,c,k) + solve(a,b,k+1,d) + yMax.first;
    }
    return ans;
}

