class UnionFind {
	std::vector<ll> m_root;
	std::vector<ll> m_depth;
	std::vector<ll> m_size;
public:
	UnionFind(ll size_) : m_root(size_), m_depth(size_, 0), m_size(size_, 1) {
		std::iota(m_root.begin(), m_root.end(), 0);
	}
	void unite(ll x, ll y) {
		x = root(x);
		y = root(y);
		if (x == y) return;
		ll t = size(x) + size(y);
		m_size[x] = m_size[y] = t;
		if (m_depth[x] < m_depth[y]) m_root[x] = y;
		else m_root[y] = x;
		if (m_depth[x] == m_depth[y]) ++m_depth[x];
	}
	bool isSame(ll x, ll y) {
		return root(x) == root(y);
	}
	ll root(ll x) {
		if (m_root[x] == x) return x;
		return m_root[x] = root(m_root[x]);
	}
	ll size(ll x) {
		if (m_root[x] == x) return m_size[x];
		return size(m_root[x] = root(m_root[x]));
	}
};

signed main() {
	ll h, w;
	cin >> w >> h;

	vector<PAIR> p(w), q(h);
	REP(i, w) { ll tmp; cin >> tmp; p[i] = {tmp,i}; }
	REP(i, h) { ll tmp; cin >> tmp; q[i] = {tmp,i}; }

	auto to = [&w](ll x, ll y) {
		return y * (w + 1) + x;
	};

	SORT(p); SORT(q);
	queue<PAIR> qx, qy;
	REPC(x, p) { qx.emplace(x); }
	REPC(x, q) { qy.emplace(x); }

	auto tree = UnionFind((w + 1) * (h + 1));
	ll ans = 0;
	while (!qx.empty() || !qy.empty()) {
		if (qy.empty() || !qx.empty() && qx.front() < qy.front()) {
			ll val = qx.front().first;
			ll it = qx.front().second;
			qx.pop();
			REP(y, h + 1) if (!tree.isSame(to(it, y), to(it + 1, y))) {
				ans += val;
				tree.unite(to(it, y), to(it + 1, y));
			}
		} else {
			ll val = qy.front().first;
			ll it = qy.front().second;
			qy.pop();
			REP(x, w + 1) if (!tree.isSame(to(x, it), to(x, it + 1))) {
				ans += val;
				tree.unite(to(x, it), to(x, it + 1));
			}
		}
	}

	cout << ans << endl;
}

