int par[2][100005], distinct[2];
vector<pair<int,int> > e;

inline int find(int offset, int x) { return par[offset][x] != x ? par[offset][x] = find(offset, par[offset][x]) : x; }
void merge(int offset, int x, int y) {
  x = find(offset, x);
  y = find(offset, y);
  if (x != y) {
    par[offset][x] = par[offset][y];
    distinct[offset]--;
  }
}

int main() {
  int w, h;
  scanf("%d%d", &w, &h);
  for (int i = 0; i <= w; ++i) par[0][i] = i;
  for (int j = 0; j <= h; ++j) par[1][j] = j;
  distinct[0] = w + 1;
  distinct[1] = h + 1;

  for (int i = 0; i < w; ++i)
  {
    int p; scanf("%d", &p);
    e.push_back(make_pair(p, -i-1));
  }
  for (int j = 0; j < h; ++j)
  {
    int q; scanf("%d", &q);
    e.push_back(make_pair(q, j+1));
  }

  sort(e.begin(), e.end());

  long long ans = 0;
  for (int i = 0; distinct[0] > 1 || distinct[1] > 1; ++i)
  {
    int cost = e[i].first;
    int rc = e[i].second;
    int offset = (rc >= 0);
    rc = abs(rc);

    ans += (long long)cost * distinct[1 ^ offset];

    merge(offset, rc, rc-1);
  }

  printf("%lld\n", ans);
  return 0;
}

