const unsigned int MAX = 100000001;

unsigned int min_index(const unsigned int cost[], const unsigned int size)
{
	unsigned int min = *min_element(cost, cost+size);
	for (unsigned int i = 0; i < size; ++i) {
		if (cost[i] == min) {
			return i;
		}
	}
}

int main(int argc, char * argv[])
{
	unsigned int w = 0;
	unsigned int h = 0;

	while (cin >> w >> h) {
		unsigned int cost[w + h];

		for (unsigned int i = 0; i < w + h; ++i) {
			cin >> cost[i];
		}

		unsigned int number_w = 0;
		unsigned int number_h = 0;
		unsigned int total = 0;
		for (unsigned int i = 0; i < w + h; ++i) {
			unsigned int index = min_index(cost, w + h);
			if (index < w) {
				total += (h  + 1 - number_h) * cost[index];
				++number_w;
			}
			else {
				total += (w + 1 - number_w) * cost[index];
				++number_h;
			}
			cost[index] = MAX;
		}
		cout << total << endl;
	}
	return 0;
}

