class UF
{
private:
    long         num;
    vector<long> par;
    vector<long> siz;
public:
    UF(long n): num(n) {
        par.resize(n);
        siz.resize(n);
        long i;
        for(i=0; i<n; i++) {
            par[i]=i; siz[i]=1;
        }
    }

    long find(long x) {
        if(x==par[x]) return x;
        return par[x] = find(par[x]);
    }

    void unite(long x, long y) {
        x=find(x);
        y=find(y);
        if(x==y) return;
        if(siz[x]<siz[y]) {
            par[x]=y;
            siz[y]=siz[x]+siz[y];
        }
        else {
            par[y]=x;
            siz[x]=siz[x]+siz[y];
        }
    }

    bool same(long x, long y) {
        return find(x)==find(y);
    }

    long size(long x) {
        return siz[find(x)];
    }
    long ngroup() {
        long count=0;
        long i;
        for(i=0; i<num; i++) {
            if(par[i]==i) count++;
        }
        return count;
    }
};


