	cin.tie(0);
	ios_base::sync_with_stdio(false);

	cin >> H >> W;
	vector<PLL> a;
	FOR(i, 0, W) {
		int v; cin >> v;
		a.push_back(PLL(v, 0));
	}
	FOR(i, 0, H) {
		int v; cin >> v;
		a.push_back(PLL(v, 1));
	}

	SORT(a);
	H++, W++;

	FOR(i, 0, SZ(a)) {
		if (a[i].second == 0) {
			ans += H*a[i].first;
			W--;
		}
		else {
			ans += W*a[i].first;
			H--;
		}
	}

	cout << ans << "\n";

	return 0;
}

