template<typename Pred>
i64 bin_search(i64 lo, i64 hi, Pred pred) {
    assert(lo < hi);

    while(lo+1 < hi) {
        i64 mid = MID(lo, hi);
        if(pred(mid))
            lo = mid;
        else
            hi = mid;
    }
    return lo;
}

template<typename Pred>
double bin_search_real(double lo, double hi, Pred pred, int iter=100) {
    assert(lo < hi);

    for(int i = 0; i < iter; ++i) {
        double mid = (lo+hi) / 2.0;
        if(pred(mid))
            lo = mid;
        else
            hi = mid;
    }
    return lo;
}

