typedef struct{
   int cost;
   int node[2];
} Edge;


typedef struct{
   int x,y;
} Node;


typedef struct unode{
   int rank;
   struct unode *p;
} UNode;


int makeEdge(Edge *edge,Node *node,int *p,int *q,int n){
   int i,j,k;

   k=0;
   for(i=0;i<n;++i){
      for(j=0;j<n;++j){
         if((node[i].y==node[j].y)&&(node[j].x-node[i].x==1)){
            edge[k].cost=p[node[i].x];
            edge[k].node[0]=i;
            edge[k].node[1]=j;
            ++k;
         }else if((node[i].x==node[j].x)&&(node[j].y-node[i].y==1)){
            edge[k].cost=q[node[i].x];
            edge[k].node[0]=i;
            edge[k].node[1]=j;
            ++k;
         }
      }
   }

   return k;
}


int cmp(const void *a,const void *b){
   Edge *A=(Edge*)a;
   Edge *B=(Edge*)b;
   return ((A->cost)>(B->cost))?1:-1;
}


void set(UNode *un){
   un->p=un;
   un->rank=0;

   return;
}


UNode *find(UNode *un){
   if(un!=(un->p)){
      un->p=find(un->p);
   }

   return un->p;
}


int same(UNode *x,UNode *y){
   return find(x)==find(y);
}


void link(UNode *x,UNode *y){
   if((x->rank)>(y->rank)){
      y->p=x;
   }else{
      x->p=y;
      if((x->rank)==(y->rank)){
         ++(y->rank);
      }
   }

   return;
}


void unite(UNode *x,UNode *y){
   link(find(x),find(y));

   return;
}


int kruskal(Edge *edge,int *used,int n,int m){
   int i,j;
   int r;
   UNode un[MAXNODE];

   for(i=0;i<n;++i){
      set(un+i);
   }

   r=-1;
   j=0;
   for(i=0;i<m;++i){
      if(same(un+edge[i].node[0],un+edge[i].node[1])){
         continue;
      }

      unite(un+edge[i].node[0],un+edge[i].node[1]);
      used[j++]=i;
      if((((un+edge[i].node[0])->p)->rank)==n-1){
         r=0;
         break;
      }
   }

   return r;
}


