#define int long long
struct UnionFind {
  vector<int> data;
  int all;
  UnionFind(int size) : data(size, -1) { all = size; }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
      all--;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};


void solve(long long W, long long H, vector<long long> p, vector<long long> q){
	UnionFind ufw(W+1),ufh(H+1);
	vector< array<int,3> > X;

	for(int i = 0 ; i < p.size() ; i++)
		X.push_back({p[i],i,0});
	for(int i = 0 ; i < q.size() ; i++)
		X.push_back({q[i],i,1});
	sort(X.begin(),X.end());
	int ans = 0;
	for( auto e : X ){
		if( e[2] == 0 ){
			ans += e[0] * ufh.all;
			ufw.unionSet(e[1],e[1]+1);
		}else{
			ans += e[0] * ufw.all;
			ufh.unionSet(e[1],e[1]+1);
		}
	}
	cout << ans << endl;



}



