ll solve(vll vw, vll vh) {
  int vwlen = vw.size();
  int vhlen = vh.size();
  if (vwlen == 0) {
    ll sum = 0;
    rep (i, vhlen) {
      sum += vh[i];
    }
    return sum;
  }
  if (vhlen == 0) {
    ll sum = 0;
    rep (i, vwlen) {
      sum += vw[i];
    }
    return sum;
  }
  ll ma = 0;
  ll vwma = 0;
  int vwmaindex;
  ll vhma = 0;
  int vhmaindex;
  rep (i, vwlen) {
    if (vwma < vw[i]) {
      vwma = vw[i];
      vwmaindex = i;
    }
  }
  rep (i, vhlen) {
    if (vhma < vh[i]) {
      vhma = vh[i];
      vhmaindex = i;
    }
  }
  vll left;
  left.reserve(max(vwlen, vhlen));
  vll right;
  right.reserve(max(vwlen, vhlen));
  if (vwma > vhma) {
    copy(begin(vw), begin(vw) + vwmaindex, back_inserter(left));
    copy(begin(vw) + vwmaindex + 1, end(vw), back_inserter(right));

//    return vwma + solve(vll((vwma).begin(), (vwma).begin() + vwmaindex), vh)
//        + solve(vll(begin(vwma) + vwmaindex + 1, end(vwma)), vh);
    return vwma + solve(left, vh) + solve(right, vh);
  } else {
    return vhma + solve(vw, vll(begin(vh), begin(vh) + vhmaindex))
        + solve(vw, vll(begin(vh) + vhmaindex + 1, end(vh)));
  }
}

