using IntType = long long int;
const int MAX_SIZE = 100005;
const int X = 0;
const int Y = 1;
int sizes[2];
IntType costs[2][MAX_SIZE];

IntType greedy() {
	sort(costs[X], costs[X] + sizes[X]);
	sort(costs[Y], costs[Y] + sizes[Y]);
	int ixs[2] = { 0,0 };
	IntType cost = 0;
	while (ixs[X] < sizes[X] || ixs[Y] < sizes[Y]) {
		if (costs[X][ixs[X]] < costs[Y][ixs[Y]]) {
			cost += costs[X][ixs[X]] * (sizes[Y] + 1 - ixs[Y]);
			ixs[X]++;
		}
		else {
			cost += costs[Y][ixs[Y]] * (sizes[X] + 1 - ixs[X]);
			ixs[Y]++;
		}
	}
	return cost;
}
int main() {
	cin >> sizes[X] >> sizes[Y];

	fill(begin(costs[X]), end(costs[X]), 1000000000);
	fill(begin(costs[Y]), end(costs[Y]), 1000000000);
	REP(i, sizes[X]) {
		cin >> costs[X][i];
	}
	REP(j, sizes[Y]) {
		cin >> costs[Y][j];
	}
	IntType minCost = greedy();

	cout << minCost << endl;

	return 0;
}

