const int INF = (1 << 30);
using namespace std;
typedef long long int ll;

int p[100005], q[100005];

int hoge(int x1, int y1, int x2, int y2){
    cout << x1 << y1 << x2 << y2 << endl;
    int xdiff = x2 - x1, ydiff = y2 - y1;
    if(!xdiff){
        int sum = 0;
        FOR(i, y1, y2){
            sum += q[i];
        }
        return sum;
    }
    if(!ydiff){
        int sum = 0;
        FOR(i, x1, x2){
            sum += p[i];
        }
        return sum;
    }
    int maxcost = 0, maxind=0, isx=0;
    FOR(i, x1, x2){
        if(maxcost < p[i]){
            maxcost = p[i];
            maxind = i;
            isx=1;
        }
    }
    FOR(i, y1, y2){
        if(maxcost < q[i]){
            maxcost = q[i];
            maxind = i;
            isx=0;
        }
    }

    if(isx){
        return p[maxind] + hoge(x1, y1, maxind, y2) + hoge(maxind+1, y1, x2, y2);
    }
    return q[maxind] + hoge(x1, y1, x2, maxind) + hoge(x1, maxind+1, x2, y2);
}

void solve(){
    int w, h;
    cin >> w >> h;
    REP(i,w) cin >> p[i];
    REP(i,h) cin >> q[i];

    cout << hoge(0,0,w,h) << endl;


}


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    solve();
}

