int main(void) {
  int W, H;
  vector<pair<int, int>> p; // cost, i
  vector<pair<int, int>> q; // cost, i
  cin >> W >> H;
  int w_need = W + 1;
  int h_need = H + 1;
  for (int i = 0; i < W; i++) {
    int cost;
    cin >> cost;
    p.push_back(make_pair(cost, i));
  }
  for (int i = 0; i < H; i++) {
    int cost;
    cin >> cost;
    q.push_back(make_pair(cost, i));
  }
  sort(p.begin(), p.end());
  sort(q.begin(), q.end());
  int qindex = 0, pindex = 0;
  LONG totalCost = 0;
  while (pindex < W || qindex < H) {
    if (pindex < p.size() && p[pindex].first < q[qindex].first) {
      totalCost += (LONG)h_need * p[pindex].first;
      w_need--; w_need = max(w_need, 1);
      pindex++;
    } else {
      totalCost += (LONG)w_need * q[qindex].first;
      h_need--; h_need = max(h_need, 1);
      qindex++;
    }
  }
  cout << totalCost << endl;
  return 0;
}

