void solve()
{
	ll W,H;  cin >> W >> H;
	vector<ll> p(W);  rep(i,0,W-1){ ll p_; cin>>p_; p[i]=p_; }
	vector<ll> q(H);  rep(i,0,H-1){ ll q_; cin>>q_; q[i]=q_; }

	vpll buf;
	each(e,p){
		buf.emplace_back(e,1);
	}
	each(e,q){
		buf.emplace_back(e,0);
	}

	sort(ALL(buf));
	ll h=H+1;
	ll w=W+1;
	ll ans=0;
	each(e,buf){
		ll x,f;  tie(x,f) = e;
		if (f==1){//p
			ans+=x*h;
			w--;
		}
		else{
			ans+=x*w;
			h--;
		}
	}
	cout << ans << '\n';
}


