using namespace std;


class UF
{
private:
    ll         num;
    vector<ll> par;
    vector<ll> siz;
public:
    UF(ll n): num(n) {
        par.resize(n);
        siz.resize(n);
        ll i;
        for(i=0; i<n; i++) {
            par[i]=i; siz[i]=1;
        }
    }

    ll find(ll x) {
        if(x==par[x]) return x;
        return par[x] = find(par[x]);
    }

    void unite(ll x, ll y) {
        x=find(x);
        y=find(y);
        if(x==y) return;
        if(siz[x]<siz[y]) {
            par[x]=y;
            siz[y]=siz[x]+siz[y];
        }
        else {
            par[y]=x;
            siz[x]=siz[x]+siz[y];
        }
    }

    bool same(ll x, ll y) {
        return find(x)==find(y);
    }

    ll size(ll x) {
        return siz[find(x)];
    }
    ll ngroup() {
        ll count=0;
        ll i;
        for(i=0; i<num; i++) {
            if(par[i]==i) count++;
        }
        return count;
    }
};


