int main(){
  ll w,h;
  cin>>w>>h;
  vector <PP> path;

  ll p[N],q[N];
  for(int i=0;i<w;i++) cin>>p[i],path.push_back(PP(P(p[i],i+1),0));
  for(int i=0;i<h;i++) cin>>q[i],path.push_back(PP(P(q[i],i+1),1));
  sort(path.begin(),path.end());

  ll sum=0,cnt[2]={};
  bool used[2][N]={},flg[2]={};
  bool cnted[2][N];
  int wh[]={w,h};
  for(int i=0;i<path.size();i++){
    ll cost=path[i].first.first;
    ll k=path[i].first.second;
    ll f=path[i].second;

    used[f][k]=1;
    if(used[f][k-1]&&!cnted[f][k-1])cnt[f]++,cnted[f][k-1]=1;
    if(used[f][k+1]&&!cnted[f][k+1])cnt[f]++,cnted[f][k+1]=1;
    if(!cnted[f][k]&&(used[f][k-1]||used[f][k+1]))cnt[f]++,cnted[f][k]=1;

    sum+=cost*(wh[f]);
    sum-=(cost-!flg[!f]*cost)*cnt[!f];
    flg[f]=1;
  }
  cout <<sum<<endl;  

  return 0;
}

