struct edge {
  int from;
  int to;
  ll cost;
  edge(int from,int to,ll cost) : from(from),to(to),cost(cost) {};
};

namespace std{
  bool operator< (const edge& lhs, const edge& rhs){
    return lhs.cost<rhs.cost;
  }

  bool operator> (const edge& lhs, const edge& rhs){
    return !(lhs.cost<rhs.cost);
  }
}

int main(void){
  int W, H;
  cin >> W >> H;
  const auto idx = [&](int i, int j){ return i + j * (W + 1); };
  vector<int> cost_x(W), cost_y(H);
  REP(i, W) {
    cin >> cost_x[i];
  }
  REP(i, H) {
    cin >> cost_y[i];
  }
  priority_queue<edge, vector<edge>, greater<edge>> q;
  q.push(edge(idx(0, 0), idx(1, 0), cost_x[0]));
  q.push(edge(idx(0, 0), idx(0, 1), cost_y[0]));
  map<int, bool> checked;
  checked[0] = true;
  ll ans = 0;
  while (!q.empty()) {
    edge e = q.top();
    q.pop();
    if (checked[e.to]) {
      continue;
    }
    ans += e.cost;
    // cout << e.cost << endl;
    int x = e.to % (W + 1), y = e.to / (W + 1);
    // cout << x << "," << y << endl;
    checked[e.to] = true;
    if (x > 0 && !checked[idx(x - 1, y)]) {
      q.push(edge(e.to, idx(x - 1, y), cost_x[x - 1]));
    }
    if (x < W && !checked[idx(x + 1, y)]) {
      q.push(edge(e.to, idx(x + 1, y), cost_x[x]));
    }
    if (y > 0 && !checked[idx(x, y - 1)]) {
      q.push(edge(e.to, idx(x, y - 1), cost_y[y - 1]));
    }
    if (y < H && !checked[idx(x, y + 1)]) {
      q.push(edge(e.to, idx(x, y + 1), cost_y[y]));
    }
  }
  cout << ans << endl;
  return 0;
}

