using IntType = long long int;
const int SIZE_XY_MAX = 100005;
int sizeX, sizeY;
IntType costX[SIZE_XY_MAX];
IntType costY[SIZE_XY_MAX];

struct Edge {
	enum Type {
		X = 0, Y = 1
	};
	Type type;
	int pos;
	IntType cost;
	Edge() : type(Type::X), pos(0), cost(-1) {}
	Edge(Type t, int p, IntType c) : type(t), pos(p), cost(c) {}
	bool operator>(const Edge& r) const { return cost > r.cost; }
};

IntType greedy() {
	priority_queue<Edge, vector<Edge>, greater<Edge>> edgeXq;
	priority_queue<Edge, vector<Edge>, greater<Edge>> edgeYq;
	REP(i, sizeX) {
		edgeXq.emplace(Edge::Type::X, i, costX[i]);
	}
	REP(j, sizeY) {
		edgeYq.emplace(Edge::Type::Y, j, costY[j]);
	}
	int fillMaxXY[2] = { sizeX + 1, sizeY + 1};
	int filledXY[2] = { 0,0 };
	IntType cost = 0;
	while (!(edgeXq.empty() && edgeYq.empty())) {
		Edge eg;
		if (edgeXq.empty()) {
			eg = edgeYq.top();
			edgeYq.pop();
		}
		else if (edgeYq.empty()) {
			eg = edgeXq.top();
			edgeXq.pop();
		}
		else {
			auto& eX = edgeXq.top();
			auto& eY = edgeYq.top();
			if (eX.cost < eY.cost) {
				eg = eX;
				edgeXq.pop();
			}
			else if (eX.cost > eY.cost) {
				eg = eY;
				edgeYq.pop();
			}
			else {
				int fillNumX = filledXY[Edge::Type::X] - filledXY[Edge::Type::Y];
				int fillNumY = filledXY[Edge::Type::Y] - filledXY[Edge::Type::X];
				if (fillNumX >= fillNumY) {
					eg = eX;
					edgeXq.pop();
				}
				else {
					eg = eY;
					edgeYq.pop();
				}
			}
		}
		int fillNum = fillMaxXY[eg.type] - filledXY[1 - eg.type];
		cost += eg.cost * fillNum;
		filledXY[eg.type]++;
	}
	return cost;
}
int main() {
	cin >> sizeX >> sizeY;
	REP(i, sizeX) {
		cin >> costX[i];
	}
	REP(j, sizeY) {
		cin >> costY[j];
	}
	IntType minCost = greedy();

	cout << minCost - 1 << endl;

	return 0;
}

