class Solve
{
private:
	int w, h;
	vector<int> p;
	vector<int> q;

public:
	Solve(){
		cin >> w >> h;
		for (int i = 0; i < w; ++i)
		{
			int tmp;
			cin >> tmp;
			p.push_back(tmp);
		}
		for (int i = 0; i < h; ++i)
		{
			int tmp;
			cin >> tmp;
			q.push_back(tmp);
		}
		sort(p.begin(), p.end());
		sort(q.begin(), q.end());

	}

	void exec(){
		int i1 = 0;
		int i2 = 0;
		ll ans = 0;
		for (int i = 0; i < w + h; ++i)
		{
			if(i1 == w) {
				ans += q[i2] * (w - i1 + 1);
				i2++;
				continue;
