	p[w] = q[h] = 100000007;
	int s = 0, t = 0;
	while (s < w || t < h)
	{
		if (p[s] < q[t])
		{
			sum += longq*p[s];
			longp--; s++;
		}
		else
		{
			sum += longp*q[t];
			longq--; t++;
		}
	}
	cout << sum << endl;
	return 0;
}

