typedef long long ll;
#define INF INT_MAX/2
int W, H;
int p[101010], q[101010];
ll ans = 0;
//-----------------------------------------------------------------
int main() {
	cin >> W >> H;
	rep(i, 0, W) scanf("%d", &p[i]);
	rep(i, 0, H) scanf("%d", &q[i]);

	priority_queue<int, vector<int>, greater<int>> pi, pj;
	rep(i, 0, W) pi.push(p[i]);
	rep(i, 0, H) pj.push(q[i]);

	while (!pi.empty() || !pj.empty()) {
		int i = INF, j = INF;

		if(!pi.empty()) i = pi.top();
		if(!pj.empty()) j = pj.top();

		if (i < j) {
			pi.pop();
			ans += (ll)i * (ll)(H + 1);
			W--;
		}
		else {
			pj.pop();
			ans += (ll)j * (ll)(W + 1);
			H--;
		}
	}

	cout << ans << endl;
}

