int vertex = 0;
const int inf = 0x3fffffff;
int prim(vector<long long > mincost, vector<vector<long long> > cost, vector<bool> used)
{
	for (int i = 0; i < vertex; ++i)
	{
		mincost[i] = inf;
		used[i] = false;
	}
	mincost[0] = 0;
	int res = 0;
	while (true)
	{
		int v = -1;
		for (int u = 0; u < vertex; ++u)
		{
			if (!used[u] && (v == -1 || mincost[u] < mincost[v]))
			{
				v = u;
			}
		}
		if (v == -1)
		{
			break;
		}
		used[v] = true;
		res += mincost[v];
		for (int u = 0; u < vertex; ++u)
		{
			mincost[u] = min(mincost[u], cost[v][u]);
		}
	}
	return res;
}
