#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
typedef pair<int,int> pp;
vector<int> par;
vector<int> rnk;

void init_union_find(int n) {
    par.resize(n);
    rnk.resize(n);
    for(int i=0; i<n; i++) {
        par[i] = i;
        rnk[i] = 0;
    }
}

int find(int x) {
    if(x != par[x]) par[x] = find(par[x]);
    return par[x]; 
}

void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if(x == y) return;
    if(rnk[x] > rnk[y]) par[y] = x;
    else par[x] = y;
    if(rnk[x] == rnk[y]) rnk[y]++;
}

int main() {
    int W,H;
    cin >> W >> H;
    vector<pp> p(W+H);
    for(int i=0; i<W+H; i++) {
        int tmp;
        cin >> tmp;
        p[i] = pp(tmp,i);
    }
    sort(p.begin(), p.end());
    init_union_find((W+1)*(H+1));
    int res = 0;
    for(int index=0; index<p.size(); index++) {
        pp e = p[index];
        if(e.second < W) {
            for(int j=0; j<=H; j++) {
                int u = (W+1)*j + e.second;
                int v = (W+1)*j + e.second + 1;
                if(find(u) != find(v)) {
                    unite(u,v);
                    res += e.first;
                }
            }
        } else {
            for(int i=0; i<=W; i++) {
                int u = (e.second - W) * (W+1) + i;
                int v = (e.second - W + 1) * (W+1) + i;
                if(find(u) != find(v)) {
                    unite(u,v);
                    res+= e.first;
                }
            }

        }
    }
    cout << res << endl;
}

