void solve(void)
{
  int h, w;
  cin >> h >> w;
  vector<pair<int, int>> vp;
  for (int i = 0; i < h; i++)
  {
    int x;
    cin >> x;
    vp.emplace_back(x, 0);
  }
  for (int i = 0; i < w; i++)
  {
    int x;
    cin >> x;
    vp.emplace_back(h, 1);
  }
  sort(ALL(vp));
  int res = 0;
  w++;
  h++;
  for (auto &&i : vp)
  {
    if (i.second == 0)
      res += w * i.first, h--;
    else
      res += h * i.first, w--;
  }
  cout << res << endl;

  return;
}

