ll p[N], q[N], n, m;
const ll INF = 1ll << 60;

int main(int argc, char *argv[]) {
    if (argc == 2) {
        freopen(argv[1], "r", stdin);
    }

    while (cin >> n >> m) {
        for (int i = 0; i < n; i++) cin >> p[i];
        for (int j = 0; j < m; j++) cin >> q[j];
        sort(p, p + n);
        p[n] = INF;
        sort(q, q + m);
        q[m] = INF;

        int tmpx = 0, tmpy = 0, x = 0, y = 0;
        ll cnt = (n + 1) * (m + 1) - 1, ans = 0;
        while (cnt > 0) {
            if (p[x] < q[y]) {
                ll tmp = min(cnt, m + 1 - tmpy);
                tmpx++;
//                cout << p[x] << " " << tmp << endl;
                ans += p[x++] * tmp;
                cnt -= tmp;
            } else {
                ll tmp = min(cnt, n + 1 - tmpx);
                tmpy++;
//                cout << q[y] << " " << tmp << endl;
                ans += q[y++] * tmp;
                cnt -= tmp;
            }
        }
        cout << ans << endl;

    }

    return 0;
}

