		if (i != pi.size() && pi[i] <= pj[j]) {
			//cout << "pi.top(): " << pi[i]<<" H+1: " << (H + 1) << endl;
			ans += pi[i] * (H+1);
			W--;
			i++;
		}
		else {
			//cout << "pj.top(): " << pj[j] << " W+1: " << (W + 1) << endl;
			ans += pj[j] * (W+1);
			H--;
			j++;
		}
	}

	cout << ans << endl;

	return 0;
}

