	if(a.cost<b.cost)return 0;
	if(a.cost>=b.cost)return 1;
	return 0;
}
int main()
{
	int m,n;
	ll ans=0;
	scanf("%d%d",&m,&n);
	for(int i=0;i<m;i++)
