	int d[n],color[n],p[n];
	int m[n][n];
	int i1,i2,j1,j2;
	for(int i = 0; i < n; i++){
		d[i] = INFTY;
		p[i] = -1;
		color[i] = WHITE;
	}
	for(int idx = 0; idx < n; idx++){
		for(int jdx = 0; jdx < n; jdx++){
			m[idx][jdx] = INFTY;
		}
	}
	int ww= w+1;
	int hh = h+1;
	for(int idx = 0; idx < n; idx++){
		for(int jdx = 0; jdx < n; jdx++){
			i1 = idx % ww;
			j1 = idx % hh;
			i2 = jdx % ww;
			j2 = jdx % hh;
			//cout << i1 << j1 << i2 << j2 << endl;
			if(j1==j2){
				//cout << "!" << j1 << i1 << i2 << endl;
				if(i1 == i2 + 1){
					m[idx][jdx] = p1[i2];
					m[jdx][idx] = p1[i2];
					//cout << p1[i2] << endl;
				}
			}
			else if(i1==i2){
				//cout << "?" << i1 << j1 << j2 << endl;
				if(j1 == j2 + 1){
					m[idx][jdx] = q1[j2];
					m[jdx][idx] = q1[j2];
					//cout << q1[j2] << endl;			
				}
			}

		}
	}
	if(0){
		for(int idx = 0; idx < n; idx++){
			for(int jdx = 0; jdx < n; jdx++){
				cout << m[idx][jdx] << " ";
			}
			cout << endl;
		}
	}



	d[0] = 0;
	while(1){
		minv = INFTY;
		u = -1;
		for(int i = 0; i < n; i++){
			if(minv > d[i] && color[i] != BLACK){
				u = i;
				minv = d[i];
			}
		}
		if(u==-1)
