template <class T>
constexpr T inf=(T(1)<<(8*sizeof(T)-3));

template <class Weight>
struct Edge {
  size_t src, dst;
  Weight cost;

  Edge(size_t src, size_t dst, Weight cost=1):
    src(src), dst(dst), cost(cost)
  {}

  bool operator <(const Edge<Weight> &rhs) const {
    if (cost != rhs.cost) return cost < rhs.cost;
    if (src != rhs.src) return src < rhs.src;
    return dst < rhs.dst;
  }
};

class UnionFind {
  std::vector<intmax_t> tree;

public:
  UnionFind(size_t n): tree(n, -1) {}

  size_t find(size_t v) {
    if (tree[v] < 0)
      return v;

    return (tree[v] = find(tree[v]));
  }

  bool unite(size_t u, size_t v) {
    u = find(u);
    v = find(v);
    if (u == v)
      return false;

    if (-tree[u] >= -tree[v])
      std::swap(u, v);

    tree[v] += tree[u];
    tree[u] = v;
    return true;
  }

  bool connected(size_t u, size_t v) {
    return (find(u) == find(v));
  }

  size_t size(size_t v) {
    return -tree[find(v)];
  }
};

int main() {
  size_t W, H;
  scanf("%zu %zu", &W, &H);

  std::vector<std::pair<Edge<intmax_t>, bool>> es;
  std::vector<intmax_t> p(W), q(H);
  for (size_t j=0; j<W; ++j) {
    scanf("%jd", &p[j]);
    es.emplace_back(Edge<intmax_t>(j, j+1, p[j]), true);
  }

  for (size_t i=0; i<H; ++i) {
    scanf("%jd", &q[i]);
    es.emplace_back(Edge<intmax_t>(W+i, W+i+1, q[i]), false);
  }

  std::sort(es.begin(), es.end());
  size_t a=W+1, b=H+1;
  intmax_t res=0;
  UnionFind uf(a+b);
  for (const auto &e: es) {
    if (uf.connected(e.first.src, e.first.dst))
      continue;

    uf.unite(e.first.src, e.first.dst);
    if (e.second) {
      res += p[e.first.src]*b;
      --a;
    } else {
      res += q[e.first.src-W]*a;
      --b;
    }
  }

  printf("%jd\n", res);
}

