class Node {
public:
    int val;
    int type = 0;
    int index = 0;
    Node(int v, int t, int ind):val(v), type(t), index(ind) {}

    bool operator < (const Node& other) const {
        return val > other.val;
    }

};
class Solution {
public:
    void solve() {
        int W, H;
        while (cin >> W >> H) {
            vector<int> vecW, vecH;
            int kw = 0;
            int kh = 0;

            priority_queue<Node> que;
            for (int i = 0; i < W; ++i) {
                int tmp;
                scanf("%d", &tmp);
                Node cn(tmp, 0, i);
                que.push(cn);
            }
            for (int i = 0; i < H; ++i) {
                int tmp;
                scanf("%d", &tmp);
                Node cn(tmp, 1, i);
                que.push(cn);
            }
            long long ans = 0;
            while (!que.empty()) {
                Node cur = que.top();
                que.pop();

                if (cur.type == 0) {
                    // is W
                    ans += static_cast<long long>(cur.val) * static_cast<long long>(H - kh + 1);
                    kw++;
                }
                else {
                    // is H
                    ans += static_cast<long long>(cur.val) * static_cast<long long>(W - kw + 1);
                    kh++;
                }
            }
            cout << ans << endl;
        }
    }
};


int main() {
    Solution sol;
    sol.solve();
    return 0;
}

