    cin.tie(nullptr);

    int n[2];
    cin >> n[0] >> n[1];

    vector<int> p[2];
    for (int i = 0; i < 2; ++i) {
        p[i].resize(n[i]);
        for (int j = 0; j < n[i]; ++j) {
            cin >> p[i][j];
        }
    }

    TDsu dsu[2];
    int cn[2];
    for (int i = 0; i < 2; ++i) {
        dsu[i].Init(n[i] + 1);
        cn[i] = n[i] + 1;
    }

    priority_queue<TEdge> q;
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < n[i]; ++j) {
            q.push(TEdge{j, j + 1, i, p[i][j]});
        }
    }

    long long cost = 0;
    while (!q.empty()) {
        TEdge e = q.top();
        q.pop();

