#define MAX_INT 999999
using namespace std;

// 边的结构体
typedef struct {
    int x;
    int y;
    int cost;
} Tpath;

void gprim();

//main
int main(int argc, char** argv)
{
    gprim();

    return 0;
}
//运行prim算法
void gprim()
{
    int w, h;
    cin >> w >> h;
    int houses = (w + 1)*(h + 1);
    vector<vector<int>> g(houses, vector<int>(houses, -1));
    int costi;
    for (int i = 0; i < w; i++){
        cin >> costi;
        for (int j = i*(h+1); j < i*(h+1) + h + 1; j++){
            int k = j + h + 1;
            if (k < houses)
                g[j][k] = costi;
        }
    }
    for (int i = 0; i < h; i++){
        cin >> costi;
        for (int j = i ; j < houses-h; j+=h+1){
            int k = j  + 1;
            if (k < houses)
                g[j][k] = costi;
        }
    }
    vector<Tpath> p;   //记录边
    vector<int>u;      //集合S
    u.push_back(0);    //将V0加入到S中
    int node1 = 0, node2 = 0, cost = 0;
    int i = 0;
    vector<int>::iterator  it;
    for (u.size(); u.size() < houses;){
        // get the lowcost path
        node1 = -1;
        node2 = -1;
        cost = MAX_INT;
        for (it = u.begin(); it != u.end(); it++){      // 从V-S集合里面寻找到离S集合最lowcost的节点和对应的边。将其记录下来为 为cost,node1,node2
            int k = (*it);
            for (i = 0; i < houses; i++){
                if (i == (*it))continue;
                if (g[k][i] >= 0 && (find(u.begin(), u.end(), i) == u.end()) && g[k][i] < cost){
                    node1 = k;
                    node2 = i;
                    cost = g[k][i];
                }
            }
        }

        // 将该节点加入到S中 并记录下路径path
        Tpath path;
        path.cost = cost;
        path.x = node1;
        path.y = node2;
        p.push_back(path);
        u.push_back(node2);
    }
    //输出
    vector<Tpath>::iterator itO;
    int mincost = 0;
    for (itO = p.begin(); itO != p.end(); itO++){
        //printf("(%d ,%d) cost: %d\n", itO->x + 1, itO->y + 1, itO->cost);
        mincost += itO->cost;
    }
    printf("%d", mincost);
    system("pause");
}

