	que.push( make_pair( 0, make_pair( 0, 0 ) ) );
	long long int ans = 0;
	while( que.size() ) {
		auto now = que.top(); que.pop();
		//cout << now.second.first << " " << now.second.second << endl;
		if( D[now.second.first][now.second.second] != now.first ) {
			continue;
