    long ans = 0;
    long vc = 0, cc = 0;
    long ec = 0;
    REP(i,v.size()) {
        if (ec == (w + 1) * (h + 1) - 1) {
            break;
        }
        if (v[i].second == 0) {
            cc++;
            ans += v[i].first * (h + 1 - vc);
            ec += h + 1 - vc;
        } else {
            vc++;
            ans += v[i].first * (w + 1 - cc);
            ec += w + 1 - cc;
        }
    }
    cout << ans << endl;
}

