int prim(){
    long u, y,minv;
    y=0;
    long d[W][H],p[W][H],color[W][H];
    for(int i=0;i<W;i++){
        for(int j=0;j<H;j++){
        d[i][j] = IN;
        p[i][j] = -1;
        color[i][j] = 0;
        }
    }
    d[0][0] = 0;
    while(1){
        minv = IN;
        u=-1;
        for(int i=0;i<W;i++){
            for(int j=0;j<H;j++){
            if(minv > d[i][j] && color[i][j] != 2){
                u=i;
                y=j;
                minv=d[i][j];
            }
            }
        }
        if(u==-1)break;
        color[u][y] = 2;
        for(int v=0;v<W;v++){
            for(int w=0;w<H;w++){
            if(color[v][w] != 2 && M[u][v] != IN){
                if(d[v][w] > M[u][v]){
                    d[v][w] = M[u][v];
                    p[v][w] = u;
                    color[v][w] = 1;
                }
                }
            }
        }
    }
    int sum = 0;
    for (int i=0;i<W;i++){
        for(int v=0;v<H;v++){
        if(p[i][v] != -1) sum+=M[i][v];
        }
    }
    return sum;
}


