struct UnionFind {
    vector<int> parent;
    int __size;
    UnionFind(int size_) : parent(size_, -1), __size(size_) {}
    bool unite(int x,int y) {
        if ((x = find(x)) != (y = find(y))) {
            if (parent[y] < parent[x]) swap(x, y);
            parent[x] += parent[y];
            parent[y] = x;
            __size--;
            return true;
        }
        return false;
    }
    bool same(int x, int y) { return find(x) == find(y); }
    int find(int x) { return parent[x] < 0 ? x : parent[x] = find(parent[x]); }
    int size(int x){ return -parent[find(x)]; }
    int size(){ return __size; }
};

int W, H, res;
priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> pq_h, pq_w;

int main() {

    cin >> W >> H;

    REP(i, W) {
        int p;
        cin >> p;
        pq_w.emplace(make_pair(p, i));
    }
    REP(i, H) {
        int p;
        cin >> p;
        pq_h.emplace(make_pair(p, i));
    }

    UnionFind uf_h(H + 1), uf_w(W + 1);

    int a = W + 1;
    int b = H + 1;

    while ((a != 1 or b != 1) and (not pq_h.empty() or not pq_w.empty())) {
        if (pq_h.empty()) {
            pair<int, int> pw = pq_w.top();
            pq_w.pop();
            res += b * pw.first;--a;
            uf_w.unite(pw.second, pw.second + 1);
            continue;
        }
        if (pq_w.empty()) {
            pair<int, int> ph = pq_h.top();
            pq_h.pop();
            res += a * ph.first;--b;
            uf_h.unite(ph.second, ph.second + 1);
            continue;
        }
        pair<int, int> ph = pq_h.top();
        pair<int, int> pw = pq_w.top();
        if (ph.first == pw.first) {
            if (uf_h.size() <= uf_w.size()) {
                pq_h.pop();
                res += a * ph.first;--b;
                uf_h.unite(ph.second, ph.second + 1);
            } else {
                pq_w.pop();
                res += b * pw.first;--a;
                uf_w.unite(pw.second, pw.second + 1);
            }
        } else if (ph.first < pw.first) {
            pq_h.pop();
            res += a * ph.first;--b;
            uf_h.unite(ph.second, ph.second + 1);
        } else {
            pq_w.pop();
            res += b * pw.first;--a;
            uf_w.unite(pw.second, pw.second + 1);
        }
        // cout << a << ' ' << b << ' ' << pq_h.size() << ' ' << pq_w.size() << endl;
        // cout << res << endl;
        // cout << "are : " << ((a != 1 or b != 1) and (not pq_h.empty() or not pq_w.empty())) << endl;
        // cout << uf_h.size() << ' ' << uf_w.size() << ' ' << pq_h.size() << ' ' << pq_w.size() << endl;
    }

    cout << res << endl;

}

