	for(int i=0; i<H; i++){
		cin>>q;
		Q[i]=q;
	}
	Q[H]=100000000+1;
	sort(Q.begin(), Q.end());

	int p_index=0, q_index=0;
	for(int i=0; i<W+H; i++){
		if(P[p_index] <= Q[q_index]){
			ans+=P[p_index]*(H+1-q_index);
			p_index++;
		}else{
			ans+=Q[q_index]*(W+1-p_index);
			q_index++;
		}
	}

	cout<<ans<<endl;

	return 0;
