struct Edge {
    int u, v, dir;
    long long cost;

    bool operator <(const Edge &another) {
        return cost < another.cost;
    }
};

int main() {
    int w, h;
    cin >> w >> h;
    vector<Edge> edges;
    //dir = 0: 横 dir = 1: 縦
    for (int i = 0; i < w; i++) {
        int c;
        cin >> c;
        edges.push_back(Edge{i, i + 1, 0, c});
    }
    for (int i = 0; i < h; i++) {
        int c;
        cin >> c;
        edges.push_back(Edge{i, i + 1, 1, c});
    }
    sort(edges.begin(), edges.end());

    //cnt[0]: 横 cnt[1]: 縦
    vector<int> cnt(2);
    cnt.at(0) = w + 1;
    cnt.at(1) = h + 1;
    int ans = 0;
    for (int i = 0; i < h + w; i++) {
        ans += edges.at(i).cost *  max(0, cnt.at(edges.at(i).dir ^ 1));
        cnt.at(edges.at(i).dir)--;
    }

    cout << ans << endl;
}

