int main() {
	ll W, H; cin >> W >> H;
	priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
	REP(i, W) {
		ll p; cin >> p;
		pq.push({ p,0 });
	}
	REP(i, H) {
		ll q; cin >> q;
		pq.push({ q,1 });
	}
	VL cnt(2);
	cnt[0] = W+1;
	cnt[1] = H+1;
	ll ans = 0;
	while (!pq.empty()) {
		ll cost = pq.top().first;
		int axis = pq.top().second;
