long long int saiki( long long int W, long long int H, vector<long long int>P, vector<long long int >Q ) {
	if( W == 0 && H == 0 ) {
		return 0;
	}
	int min = LLONG_MAX/6, idx = 0;
	bool Qflug = false;
	for( size_t i = 0; i < P.size(); i++ ) {
		if( min > P[i] * (H + 1) ) {
			min = P[i] * (H + 1);
			idx = i;
		}
	}
	for( size_t i = 0; i < Q.size(); i++ ) {
		if( min > Q[i] * (W + 1) ) {
			min = Q[i] * (W + 1);
			idx = i;
			Qflug = true;
		}
	}
	if( !Qflug ) {
		//cout << min << endl;
		//cout << P.size() << " " << idx << endl;
		P.erase( P.begin() + idx );
		return min + saiki( W - 1, H, P, Q );
	} else {
		Q.erase( Q.begin() + idx );
		return  min + saiki( W, H - 1, P, Q );
	}
}

