#define MAX_W (100000L)
#define MAX_H (100000L)

using namespace std;

int main(int argc, char *argv[]) {
  // read inputs
  long W, H, ps[MAX_W], qs[MAX_H];
  scanf("%ld %ld", &W, &H);
  for (int i = 0; i < W; i++) {
    scanf("%ld", &ps[i]);
  }
  for (int j = 0; j < W; j++) {
    scanf("%ld", &qs[j]);
  }

  // sort inputs
  sort(ps, ps + W);
  sort(qs, qs + H);

  // solve
  long ans = 0;
  int m = 0, n = 0;
  while (m < W && n < H) {
    const long p = ps[m], q = qs[n];
    if (p < q) {
      ans += p * (H + 1 - n);
      m++;
    } else {
      ans += q * (W + 1 - m);
      n++;
    }
  }
  while (m < W) {
    ans += ps[m++];
  }
  while (n < H) {
    ans += qs[n++];
  }
  printf("%ld\n", ans);

  return 0;
}

