typedef long long ll;
// 素集合データ構造
struct UnionFind {
	// par[i]：データiが属する木の親の番号。i == par[i]のとき、データiは木の根ノードである
	vector<int> par;
	// sizes[i]：根ノードiの木に含まれるデータの数。iが根ノードでない場合は無意味な値となる
	vector<int> sizes;

	UnionFind(int n) : par(n), sizes(n, 1) {
		// 最初は全てのデータiがグループiに存在するものとして初期化
		rep(i, n) par[i] = i;
	}

	// データxが属する木の根を得る
	int find(int x) {
		if (x == par[x]) return x;
		return par[x] = find(par[x]);  // 根を張り替えながら再帰的に根ノードを探す
	}

	// 2つのデータx, yが属する木をマージする
	void unite(int x, int y) {
		// データの根ノードを得る
		x = find(x);
		y = find(y);

		// 既に同じ木に属しているならマージしない
		if (x == y) return;

		// xの木がyの木より大きくなるようにする
		if (sizes[x] < sizes[y]) swap(x, y);

		// xがyの親になるように連結する
		par[y] = x;
		sizes[x] += sizes[y];
		// sizes[y] = 0;  // sizes[y]は無意味な値となるので0を入れておいてもよい
	}

	// 2つのデータx, yが属する木が同じならtrueを返す
	bool same(int x, int y) {
		return find(x) == find(y);
	}

	// データxが含まれる木の大きさを返す
	int size(int x) {
		return sizes[find(x)];
	}
};

void solve() {
#ifdef _WIN32
	istream &cin = ifstream("input.txt");
#endif

	int w, h;
	cin >> w >> h;
	VI p(w), q(h);
	multimap<int, int> mmp, mmq;
	priority_queue<int, vector<int>, greater<int>> pq;
	rep(i, w) {
		cin >> p[i];
		mmp.insert({p[i], i});
		pq.push(p[i]);
	}
	rep(i, h) {
		cin >> q[i];
		pq.push(q[i]);
		mmq.insert({q[i], i});
	}

	UnionFind uf((w + 1) * (h + 1));
	ll ans = 0;

	while (!pq.empty()) {
		int mi = pq.top(); pq.pop();

		auto ite = mmq.find(mi);
		int index;
		if (ite != mmq.end()) {
			index = (*(ite)).second;
			mmq.erase(ite);
			rep(i, w + 1) {
				int x1 = (w + 1) * index + i;
				if (!uf.same(x1, x1 + w + 1)) {
					uf.unite(x1, x1 + w + 1);
					ans += q[index];
				}
			}

		} else {
			ite = mmp.find(mi);
			index = (*ite).second;
			mmp.erase(ite);
			rep(i, h + 1) {
				int x1 = i * (w + 1) + index;
				if (!uf.same(x1, x1 + 1)) {
					uf.unite(x1, x1 + 1);
					ans += p[index];
				}
			}
		}
	}

	cout << ans << endl;
}




