struct UF {
  int groups;
  vector<int> parent;
  UF(int n):parent(n,-1),groups(n){}
  int root(int x){return parent[x]<0?x:parent[x]=root(parent[x]);}
  bool merge(int x,int y){
    x=root(x);y=root(y);
    if(x==y)return false;
    if(parent[y]<parent[x])swap(x,y);
    if(parent[x]==parent[y])--parent[x];
    parent[y]=x;
    --groups;
    return true;
  }
};

