typedef pair<int, int>  pii;
typedef pair<llint, pair<pii, pii> >  edge;
int dir[][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

int main() {
    int w, h;
    llint   tmp;

    scanf("%d%d", &w, &h);
    vector<llint> vp(w), vq(h);

    repeat(i, w) {
        scanf("%lld", &tmp);
        vp[i] = tmp;
    }
    repeat(j, h) {
        scanf("%lld", &tmp);
        vq[j] = tmp;
    }

    vector<vector<bool> >   conn(w+1, vector<bool>(h+1, false));
    priority_queue<edge, vector<edge>, greater<edge> > qe;
    llint   tot = 0;

    conn[0][0] = true;
    qe.push(edge(vp[0], pair<pii, pii>(pii(0, 0), pii(1, 0))));
    qe.push(edge(vq[0], pair<pii, pii>(pii(0, 0), pii(0, 1))));

    edge    te;
    int x1, y1, x2, y2;
    while(!(qe.empty())) {
        te = qe.top(); qe.pop();
        x1 = te.second.second.first;
        y1 = te.second.second.second;

        if(conn[x1][y1])   continue;
        conn[x1][y1] = true;
        tot += te.first;

        repeat(i, 4) {
            x2 = x1 + dir[i][0];
            y2 = y1 + dir[i][1];

            if(x2 >= 0 && x2 <= w && y2 >= 0 && y2 <= h && !(conn[x2][y2])) {
                if(dir[i][0] == 1) {
                    qe.push(edge(vp[x1], pair<pii,pii>(pii(x1, y1), pii(x2, y2))));
                }
                else if(dir[i][0] == -1) {
                    qe.push(edge(vp[x2], pair<pii,pii>(pii(x1, y1), pii(x2, y2))));
