class UF
{
private:
    size_t     num;
    vector<size_t> par;
    vector<size_t> siz;
public:
    UF(size_t n): num(n) {
        par.resize(n);
        siz.resize(n);
        size_t i;
        for(i=0; i<n; i++) {
            par[i]=i; siz[i]=1;
        }
    }

    size_t find(size_t x) {
        if(x==par[x]) return x;
        return par[x] = find(par[x]);
    }

    void unite(size_t x, size_t y) {
        x=find(x);
        y=find(y);
        if(x==y) return;
        if(siz[x]<siz[y]) {
            par[x]=y;
            siz[y]=siz[x]+siz[y];
        }
        else {
            par[y]=x;
            siz[x]=siz[x]+siz[y];
        }
    }

    bool same(size_t x, size_t y) {
        return find(x)==find(y);
    }

    size_t size(size_t x) {
        return siz[find(x)];
    }
