//最小全域木をクラスカル法で求める
//クラスカル法とは辺をコストの小さい順にソートし両端点が異なる連結成分にあるならその辺を使う
//という操作を繰り返すそのためにまずpiたちとqiたちを一緒にしてソートする
//これらの値の小さい順に辺を追加できるだけ追加していけば最小全域木が求まる
//各ステップで辺は何本追加できるか？
//配列のpiに対応する要素を見るときは(i,j)と(i+1,j)を結ぶ辺を何本追加できるかを求め
//さらにすべてのjに対し(i,j)と(i+1,j)を連結にすればよい
//そしてこの連結操作はこれ以降x座標iとi+1を同一視するという操作です
//よってこの操作では(i,j)と(I,J+1)を結ぶような辺の数が1減少するということが起こる
//以上をまとめるとPIたちとqiたちをまとめてソートし
//a=W+1,b=H+1としてその列を前から見て
//(i,j)と(i+1,j)を結ぶ辺を見るときはそのような列をb本使いaを1減らし
//(i,j)と(i,j+1)を結ぶ辺を見るときはそのような辺をa本使いbを1減らす

int main() {
	ll W, H; cin >> W >> H;
	ll a = W + 1;
	ll b = H + 1;
	vector<pii>V;
	ll sum = 0;
	REP(i, W) {
		int x; cin >> x;
		V.push_back({ x,1 });
	}
	REP(i, H) {
		int x; cin >> x;
		V.push_back({ x,0 });
	}
	sort(V.begin(), V.end());
	for (int i = 0; i < V.size(); ++i) {
		if (V[i].second == 1) {
			sum += V[i].first*b;
			a--;
		}
		else {
			sum += V[i].first*a;
			b--;
		}
	}
	cout << sum << endl;
	return 0;
}

