	REP(i, h) { ll tmp; cin >> tmp; q[i] = {tmp,i}; }

	auto to = [&w](ll x, ll y) {
		return y * (w + 1) + x;
	};

	SORT(p); SORT(q);
	queue<PAIR> qx, qy;
	REPC(x, p) { qx.emplace(x); }
	REPC(x, q) { qy.emplace(x); }

	auto tree = UnionFind((w + 1) * (h + 1));
	ll ans = 0;
	while (!qx.empty() || !qy.empty()) {
		if (qy.empty() || (!qx.empty() && qx.front() < qy.front())) {
			ll val = qx.front().first;
			ll it = qx.front().second;
			qx.pop();
			REP(y, h + 1) if (!tree.isSame(to(it, y), to(it + 1, y))) {
				ans += val;
