int W, H;
int pi[100000005];
int qj[100000005];

multimap<int, int> wh_multimap;
set<int> wh_done;

int whi(int i, int j)
{
    return i * H + j;
}

pair<int, int> whi_r(int wh)
{
    return make_pair(wh / H, wh % H);
}


void insert_neighbours(int i, int j)
{
    // cout << "insert: ";
    int min_i, min_j, max_i, max_j;
    if (i > 0) {
        int cost = pi[i - 1];
        int wh = whi(i - 1, j);
        wh_multimap.insert(make_pair(cost, wh));
        // cout << i - 1 << ":" << j << " ";
    }
    if (i < W - 1) {
        int cost = pi[i];
        int wh = whi(i + 1, j);
        wh_multimap.insert(make_pair(cost, wh));
        // cout << i + 1 << ":" << j << " ";
    }
    if (j > 0) {
        int cost = qj[j - 1];
        int wh = whi(i, j - 1);
        wh_multimap.insert(make_pair(cost, wh));
        // cout << i << ":" << j - 1 << " ";
    }
    if (j < H - 1) {
        int cost = qj[j];
        int wh = whi(i, j + 1);
        wh_multimap.insert(make_pair(cost, wh));
        // cout << i << ":" << j + 1 << " ";
    }
    // cout << endl;
}

pair<int, int> get_min_wh()
{
    while(!wh_multimap.empty()) {
        multimap<int, int>::iterator min_whi_i = wh_multimap.begin();
        pair<int, int> min_wh = *min_whi_i;
        wh_multimap.erase(min_whi_i);
        // cout << "?" << min_wh.second << endl;
        if (wh_done.find(min_wh.second) == wh_done.end()) {
            wh_done.insert(min_wh.second);
            return min_wh;
        } else {
            // cout << "\t nope: " << min_wh.second << endl;
        }
    }
    return make_pair(-1, -1);
}


int main()
{
    // int pi[100000005];

    cin >> W >> H;

    for (int i = 0; i < W; i++)
        cin >> pi[i];

    for (int j = 0; j < H; j++)
        cin >> qj[j];

    W++; H++;

    insert_neighbours(0, 0);
    wh_done.insert(0);

    int cost = 0;
    while(!wh_multimap.empty())
    {
        /*
        for (multimap<int, int>::iterator it = wh_multimap.begin(); it != wh_multimap.end(); it++)
            cout << "\t::" << it->first << " " << it->second << endl;
        for (set<int>::iterator it = wh_done.begin(); it != wh_done.end(); it++)
            cout << "\t:::" << *it << endl;
            */
        pair<int, int> min_wh = get_min_wh();
        if (min_wh.first == -1)
            break;
        cost += min_wh.first;
        pair<int, int> wh = whi_r(min_wh.second);
        // cout << "done: " << wh.first << ":" << wh.second << "(" << min_wh.first << ")" << endl;
        insert_neighbours(wh.first, wh.second);
    }

    cout << cost << endl;

}

