int main() {
    ll H, W;
    cin >> H >> W;
    priority_queue<ll, V<ll>, greater<ll>> pq_h, pq_w;
    for(ll i = 0; i < H; i++) {
        ll a;
        cin >> a;
        pq_w.push(a);
    }
    for(ll i = 0; i < W; i++) {
        ll a;
        cin >> a;
        pq_h.push(a);
    }

    ll rest = (H + 1) * (W + 1) - 1;
    ll cnt_h = 0, cnt_w = 0;
    pq_h.push(inf);
    pq_w.push(inf);

    ll ans = 0;
    while(rest) {
        ll a = pq_h.top();
        ll b = pq_w.top();
        if(a < b) {
            pq_h.pop();
            ll cnt = min(H + 1 - cnt_w, rest);
            cnt_h++;
            ans += cnt * a;
            rest -= cnt;
        } else {
            pq_w.pop();
            ll cnt = min(W + 1 - cnt_h, rest);
            cnt_w++;
            ans += cnt * b;
            rest -= cnt;
        }
    }

    cout << ans << endl;
    return 0;
}

