typedef pair<int,int> point;
struct edge
{
	point start;
	point end;
	int weight;
	edge(point s,point e,int w):start(s),end(e),weight(w){}

};

bool operator<(const edge& a,const edge& b)
{
	return a.weight>b.weight;
}

void solve()
{

	int w,h;
	cin>>w>>h;
	vector<int>pw;
	vector<int>qh;
	vector<vector<bool>>used(w+1,vector<bool>(h+1,false));
	std::priority_queue<edge> pq;
	pq.push(edge(point(0,0),point(0,0),0));
	int result=0;


	for(int i=0;i<w;++i)
	{
		int t;
		cin>>t;
		pw.push_back(t);
	}
	for(int i=0;i<h;++i)
	{
		int t;
		cin>>t;
		qh.push_back(t);
	}
	int counter=0;
	for(;counter<(w+1)*(h+1);)
	{
		if(used[pq.top().end.first][pq.top().end.second])
		{
			pq.pop();
			continue;
		}
		result+=pq.top().weight;
		used[pq.top().end.first][pq.top().end.second]=true;
		int ii=pq.top().end.first;
		int jj=pq.top().end.second;
		pq.pop();
		if(ii>0)pq.push(edge(point(ii,jj),point(ii-1,jj),pw[ii-1]));
		if(jj>0)pq.push(edge(point(ii,jj),point(ii,jj-1),qh[jj-1]));
		if(ii<w)pq.push(edge(point(ii,jj),point(ii+1,jj),pw[ii]));
		if(jj<h)pq.push(edge(point(ii,jj),point(ii,jj+1),qh[jj]));
		++counter;
	}
	cout<<result;

}
int main()
{
	freopen("input","r",stdin);

	solve();
	return 0;
}

