void Calc() {
  int w, h;
  in, w, h;

  auto p = in.Array(w);
  auto q = in.Array(h);

  vector<pair<int, int>> a;
  a.reserve(w + h);
  for (auto& i : p) {
    a.push_back({ i,0 });
  }
  for (auto& i : q) {
    a.push_back({ i,1 });
  }
  sort(all(a));

  ll ans = 0;
  int cnt[2] = { 0 };
  int wh[2] = { h + 1,w + 1 };
  for (auto& i : a) {
    ans += (ll) max(0ll, (ll) i.first *(wh[i.second] - cnt[1 - i.second]));
    cnt[i.second]++;
  }

  cout << (ans) << endl;

}

