long long int f(int x0, int y0, int x1, int y1, int maxX, int maxY, int maxXidx, int maxYidx) {
		if (x0 == x1) {
			long long int ret = 0;
			ret = sumY[y1] - sumY[y0];
			return ret;
		} else if (y0 == y1) {
			long long int ret = 0;
			ret = sumX[x1] - sumX[x0];
			return ret;
		}

		if (maxX == 0)
			for (int x=x0;x<x1;x++) {
				if (maxX < p[x]) {
					maxX = p[x];
					maxXidx = x;
				}
			}

		if (maxY == 0)
			for (int y=y0;y<y1;y++) {
				if (maxY < q[y]) {
					maxY = q[y];
					maxYidx = y;
				}
			}

		if (maxX > maxY) {
			long long int ret =
					f(x0, y0, maxXidx, y1, 0, maxY, 0, maxYidx) + 
					f(maxXidx+1, y0, x1, y1, 0, maxY, 0, maxYidx) + 
					maxX;
			return ret;
		} else {
			long long int ret =
					f(x0, y0, x1, maxYidx, maxX, 0, maxXidx, 0) + 
					f(x0, maxYidx+1, x1, y1, maxX, 0, maxXidx, 0) + 
					maxY;
