//init:O(n).unite,find:(Ack^-1(n,n))
class union_find{
	private:
	vector<int> parent,rank,gs;
    int size;
	public:
    int count_group;
    union_find()=default;
    union_find(int n){ init(n); }

    void init(int n){
		size=n;
		count_group=n;
		parent.resize(size);
		rank.assign(size,0);
        gs.assign(size,1);
		for(int i=0; i<size; ++i) parent[i]=i;
	}

	int find(int x){
		if(parent[x]==x) return x;
		else return parent[x]=find(parent[x]);
	}

	void unite(int x,int y){
		x=find(x);
		y=find(y);
		if(x==y) return;
		if(rank[x]<rank[y]){
			parent[x]=y;
            gs[y]+=gs[x];
		} else {
			parent[y]=x;
            gs[x]+=gs[y];
			if(rank[x]==rank[y]) ++rank[x];
		}
		--count_group;
	}

	bool is_same_group(int x,int y){
		return find(x)==find(y);
	}

    int group_size(int x){
        return gs[find(x)];
    };
};

void solve(){
    int w,h;
    cin >> w >> h;
    vector<tuple<int64_t,int,int>> vt;
    rep(i,0,w){
        int p;
        cin >> p;
        vt.push_back(make_tuple(p,i,i+1));
    }
    rep(i,0,h){
        int q;
        cin >> q;
        vt.push_back(make_tuple(q,i+w+1,i+w+2));
    }
    sort(vt.begin(),vt.end());
    union_find uf(w+h+2);
    int64_t ans=0,cnt1=0,cnt2=0;
    for(auto &edge:vt){
        int64_t cost=get<0>(edge);
        int a=get<1>(edge),b=get<2>(edge);
        if(uf.is_same_group(a,b)) continue;
        uf.unite(a,b);
        if(a<=w){
            ans+=cost*(h+1-cnt1);
            ++cnt2;
        }else{
            ans+=cost*(w+1-cnt2);
            ++cnt1;
        }
    }
    cout << ans << endl;
}

