        pq[i] = {p, 1};
    }
    for (int i = 0; i < H; i++) {
        ll q;
        cin >> q;
        pq[i+W] = {q, 2};
    }
    sort(pq.begin(), pq.end());

    int w, h;
    w = W + 1;
    h = H + 1;

    ll ans = 0;
    for (int i = 0; i < W+H; i++){
        ll cost = pq[i].first;
        int dir = pq[i].second;
        if (dir == 1) {
            if (w > 1) {
                ans += cost * h;
                w--;
            }
        }
        else {
            if (h > 1) {
                ans += cost * w;
                h--;
            }
        }
        if (w == 1 && h == 1) break;

    }

    cout << ans << endl;

}

