		if (edge[i].second == 'x') {
			sum += edge[i].first * y;
			num += y;
			--x;
			if (num >= total) {
				sum -= edge[i].first * (num - total);
				break;
			}
		}
		if (edge[i].second == 'y') {
			sum += edge[i].first * x;
			num += x;
			--y;
			if (num >= total) {
				sum -= edge[i].first * (num - total);
				break;
			}
		}
	}

	cout << sum << endl;
	return 0;

