int main(){
    ll w, h;
    cin >> w >> h;
    vector<pair<ll, ll>> cost;
    REP(i, w){
        ll pi;
        cin >> pi;
        cost.emplace_back(pi, 0);
    }
    REP(i, h){
        ll qi;
        cin >> qi;
        cost.emplace_back(qi, 1);
    }

    sort(ALL(cost));

    ll ans = 0;
    for(auto p : cost){
        const ll ci = p.first;
        const ll flg = p.second;
        if(flg == 0){ // horizontal
            ans += (h + 1) * ci;
            w--;
        }else{ // vertical
            ans += (w + 1) * ci;
            h--;
        }
        if(w + h == 0){ break; }
    }
    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define REP(i, n) for (int i = 0; i < n; ++i)

struct tup {
    int cst, idx;
    bool isW;
    tup() : cst(0), idx(0), isW(false) {}
    tup(int cst, int idx, bool isW) : cst(cst), idx(idx), isW(isW) {}
    bool operator<(const tup &t) const {
        return cst < t.cst;
    }
};

struct UnionFind {
    vector<int> parent;
    long long __size;
    UnionFind(int size_) : parent(size_, -1), __size(size_) {}
    bool unite(int x,int y) {
        if ((x = find(x)) != (y = find(y))) {
            if (parent[y] < parent[x]) swap(x, y);
            parent[x] += parent[y];
            parent[y] = x;
            __size--;
            return true;
        }
        return false;
    }
    bool same(int x, int y) { return find(x) == find(y); }
    int find(int x) { return parent[x] < 0 ? x : parent[x] = find(parent[x]); }
    int size(int x){ return -parent[find(x)]; }
    long long size(){ return __size; }
};

int W, H;
long long res;
vector<tup> v;

int main() {

    cin >> W >> H;

    REP(i, W) {
        int p; cin >> p;
        v.emplace_back(tup(p, i, true));
    }
    REP(i, H) {
        int p; cin >> p;
        v.emplace_back(tup(p, i, false));
    }
    sort(v.begin(), v.end());

    UnionFind uf_h(H + 1), uf_w(W + 1);

    for (auto& e : v) {
        if (uf_h.size() == 1 and uf_w.size() == 1) break;
        if (e.isW) {
            res += uf_h.size() * e.cst;
            uf_w.unite(e.idx, e.idx + 1);
        } else {
            res += uf_w.size() * e.cst;
            uf_h.unite(e.idx, e.idx + 1);
        }
    }

    cout << res << endl;

}

