typedef long long ll;

int main(){
  int W,H; cin >> W >> H;

  int a = W+1; 
  int b = H+1;

  vector<pair<int,int>> edge;

  for(int i = 0; i < W; i++){
    int p; cin >> p; edge.push_back({p,1});
    // 1 は x方向を意味
  }

  for(int j = 0; j < H; j++){
    int q; cin >> q; edge.push_back({q,2});
  }

  sort(edge.begin(),edge.end());


  int itr = 0; 

  ll ans = 0; ll cnt = 0;

  while( a > 0 && b > 0){

    int cost = edge[itr].first;
    int dir = edge[itr].second;

    if( dir == 1 ){ 
      ans += cost*b; cnt += b; a--; 
    }
    if( dir == 2){
      ans += cost*a; cnt += a; b--;
    }

    if( cnt >= (W+1)*(H+1)-1){break;}

    itr++;
  }

  cout << ans << endl;

  return 0;
}

