	VI p(w), q(h);
	VI fp(w), fq(h);
	priority_queue<int, vector<int>, greater<int>> pq;
	rep(i, w) cin >> p[i], pq.push(p[i]);
	rep(i, h) cin >> q[i], pq.push(q[i]);

	Graph g; UnionFind uf((w + 1) * (h + 1));
	ll ans = 0;

	while (!pq.empty()) {
		int mi = pq.top(); pq.pop();
		int index = (int)(find(all(q), mi) - q.begin());
		while (index != h && fq[index] == 1) {
			index = (int)(find(q.begin() + index + 1, q.end(), mi) - q.begin());
		}
		if (index != h) {
			fq[index] = 1;
			rep(i, w + 1) {
				int x1 = (w + 1) * index + i;
				if (!uf.same(x1, x1 + w + 1)) {
					uf.unite(x1, x1 + w + 1);
					ans += q[index];
				}
			}

		} else {
			index = (int)(find(all(p), mi) - p.begin());
			while (fp[index] == 1) {
				index = (int)(find(p.begin() + index + 1, p.end(), mi) - p.begin());
			}
			fp[index] = 1;
			rep(i, h + 1) {
				int x1 = i * (w + 1) + index;
				if (!uf.same(x1, x1 + 1)) {
					uf.unite(x1, x1 + 1);
					ans += p[index];
				}
			}
		}
	}

	cout << ans << endl;
}




