/* Union Find (Disjoint Set) */
struct UF {
    vector<int> par, rk;

    UF(int _n) {
        par.resize(_n + 1), rk.assign(_n + 1, 0);
        for (int i = 0; i <= _n; ++i) {
            par[i] = i;
        }
    }

    int find(int x) {
        if (x != par[x]) par[x] = find(par[x]);
        return par[x];
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    bool unite(int x, int y) {
        x = find(x), y = find(y);
        if (x == y) return false;
        if (rk[x] < rk[y]) par[x] = y;
        else {
            par[y] = x;
            if (rk[x] == rk[y]) rk[x]++;
        }
        return true;
    }
};

