struct path{
		int cst,x;char wh;
		path(){};
		path(int cst_,int x_,char wh_){
			cst=cst_,x=x_,wh=wh_;
		};
	bool operator<(const path& o)const{return cst>o.cst;}
};

struct unionFind{
	int n,cn;vector<int>pr;
	unionFind(){};
	unionFind(int n_){
		n=n_;
		cn=n;
		pr.resize(n,-1);
	};
	int root(int a){
		if(pr[a]==-1)return a;
		else return pr[a]=root(pr[a]);
	}
	void unify(int a,int b){
		a=root(a),b=root(b);
		if(a==b)return;
		pr[a]=b;
		cn--;
	}
	bool same(int a,int b){return root(a)==root(b);}

};


signed main(){
	int w,h;cin>>w>>h;
	priority_queue<path> pq;	
	unionFind uw(w+1),uh(h+1);
	int y;
	rep(i,w){
		cin>>y;pq.push(path(y,i,'w'));
	}
	rep(i,h){
		cin>>y;pq.push(path(y,i,'h'));
	}

	int cst=0,num=0;

	while(!pq.empty()){
		auto u=pq.top();pq.pop();
		if(u.wh=='w'){
//			if(uw.same(u.x,u.x+1))continue;
			uw.unify(u.x,u.x+1);
			cst+=u.cst*uh.cn;
			num+=uh.cn;


		}else if(u.wh=='h'){
//			if(uh.same(u.x,u.x+1))continue;
			uh.unify(u.x,u.x+1);
			cst+=u.cst*uw.cn;
			num+=uw.cn;

		}
//		cerr<<u.wh<<u.x<<" "<<cst<<" "<<num<<endl;
		if(num>=(h+1)*(w+1)-1)break;
	}
	cout<<cst<<endl;
}

