int main()
{
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	ll W, H; cin >> W >> H;
	vector<LI> edges(W + H);
	rep (i, W){
		ll p; cin >> p;
		edges[i].first = p;
		edges[i].second = CW;
	} // end rep

	rep (j, H){
		ll q; cin >> q;
		edges[j + W].first = q;
		edges[j + W].second = CH;
	} // end rep

	sort (ALL (edges));

	int currW = W + 1;
	int currH = H + 1;

	ll res = 0LL;
	rep (i, W + H){
		if (edges[i].second == CH){
			if (currH > 0){
				--currH;
				res += edges[i].first * (ll)currW;
		   	} // end if
		}else{ // if (edges[i].second == CW)
			if (currW > 0){
				--currW;
				res += edges[i].first * (ll)currH;
			} // end if
		} // end if
	} // end rep

	cout << res << endl;

	return 0;
}

