int main() {
    int h, w;

    std::cin >> h >> w;

    std::vector<std::pair<long long, int> > cost(h + w);

    for (int i = 0; i < h + w; i++) {
        long long c;
        std::cin >> c;
        if (i < w) {
            cost[i] = { c, 0 };
        } else {
            cost[i] = { c, 1 };
        }
    }

    std::sort(cost.begin(), cost.end());

    long long total_cost = 0;
    long long a = w + 1, b = h + 1;

    for (int i = 0; i < cost.size(); i++) {
        if (cost[i].second == 0) {
            total_cost += b * cost[i].first;
            a--;
        } else {
            total_cost += a * cost[i].first;
            b--;
        }
    }

    std::cout << total_cost << std::endl;
    return 0;
}

