void solve() {
	cin >> w >> h;
	p = vector<int>(w);
	q = vector<int>(h);

	rep(i, w) cin >> p[ i ];
	rep(i, h) cin >> q[ i ];
	sort(all(p));
	sort(all(q));

	// print("it's P:\n");
	rep(i, w) {
		int v = p[ i ];
		auto it = lower_bound(all(q), v) - q.begin();
		int cnt = h - it + 1;
		ans += (ll)cnt * v;

		// cout << "for v = " << v << ", cnt = " << cnt << endl;
	}
	// print("it's Q:\n");
	rep(i, h) {
		int v = q[ i ];
		auto it = upper_bound(all(p), v) - p.begin();
		int cnt = w - it + 1;
		ans += (ll)cnt * v;

		// cout << "for v = " << v << ", cnt = " << cnt << endl;
	}
	print(ans);
}

