int main() {
	int W, H;
	cin >> W >> H;
	vector<unsigned long long> P(W);
	vector<unsigned long long> Q(H);
	for (int i = 0; i < W; i++) {
		cin >> P[i];
	}
	for (int i = 0; i < H; i++) {
		cin >> Q[i];
	}
	sort(P.begin(), P.end());
	sort(Q.begin(), Q.end());
	int pi = 0;
	int qi = 0;
	int w = W + 1;
	int h = H + 1;
	unsigned long long cost = 0;
	while(true) {
		long long p = P[pi];
		long long q = Q[qi];
		if (p < q) {
			cost += p * h;
			w--; pi++;
		} else {
			cost += q * w;
			h--; qi++;
		}
		if (pi == W) {
			for (int i = qi; i < H; i++) {
				cost += Q[i];
			}
			break;
		}
		if (qi == H) {
			for (int i = pi; i < W; i++) {
				cost += P[i];
			}
			break;
		}
	}
	cout << cost << endl;
	return 0;
}

