	}
	vector<vector<bool>> vis(w + 1, vector<bool>(h + 1));
	set<pair<int, PII>> queue;
	int res = 0;
	vector<PII> dirs = {
		{0, 1},
		{0, -1},
		{1, 0},
		{-1, 0}
	};
