#define MAX   200200
#define ROW   0
#define COL   1

struct Item {
    int cost, pos, type;
    Item() {
        cost = pos = type = 0;
    }
    Item(int _cost, int _pos, int _type) {
        cost = _cost; pos = _pos; type = _type;
    }
    bool operator < (const Item &x) const {
        return cost < x.cost;
    }
};

int w, h, rowCost[MAX], colCost[MAX];

void init(void) {
    scanf("%d%d", &w, &h);
    FOR(i, 1, w) scanf("%d", &rowCost[i]);
    FOR(i, 1, h) scanf("%d", &colCost[i]);
}

void process(void) {
    vector<Item> items;
    FOR(i, 1, w) items.push_back(Item(rowCost[i], i, ROW));
    FOR(i, 1, h) items.push_back(Item(colCost[i], i, COL));
    sort(ALL(items));

    DisjointSet dsuRow(w + 1), dsuCol(h + 1);
    int numCompRow = w + 1;
    int numCompCol = h + 1;
    long long res = 0;
    FORE(it, items) {
        if (it->type == ROW) {
            if (!dsuRow.join(it->pos, it->pos + 1)) continue;
            numCompRow--;
            res += 1LL * it->cost * numCompCol;
         } else {
            if (!dsuCol.join(it->pos, it->pos + 1)) continue;
            numCompCol--;
            res += 1LL * it->cost * numCompRow;
         }
    }
    cout << res << endl;
}
int main(void) {
    init();
    process();
    return 0;
}


