struct Node {
	int l;
	bool heng;
};

Node list[300000];

bool cmp(Node a, Node b) {
	return a.l < b.l;
}

int main() {
	int w, h;

	cin >> w >> h;
	int i = 0;
	for (i = 0; i < w; i++) {
		cin >> list[i].l;
		list[i].heng = true;
	}
	for (; i < w + h; i++) {
		cin >> list[i].l;
		list[i].heng = false;
	}

	sort(list, list + w + h, cmp);

	int ans = 0;
	int ii = w + h;
	for (i = 0; i < ii; i++) {
		if (list[i].heng) {
			ans += list[i].l * (h + 1);
			w--;
		}
		else {
			ans += list[i].l * (w + 1);
			h--;
		}
	}
	cout << ans << endl;


	return 0;
}

