#define MAXN 100007

int w, h;
ll p[MAXN], psum[MAXN], q[MAXN], qsum[MAXN];

void init() {
  w = scan(); h = scan();
  for (int i = 0; i < w; ++i) {
    p[i] = scan_ll();
  }
  for (int i = 0; i < h; ++i) {
    q[i] = scan_ll();
  }
}

ll work() {
  sort(p, p + w, greater<int>());
  sort(q, q + h, greater<int>());
  psum[0] = p[0];
  qsum[0] = q[0];

  for (int i = 1; i < w; ++i) {
    psum[i] = psum[i-1] + p[i];
  }
  for (int i = 1; i < h; ++i) {
    qsum[i] = qsum[i-1] + q[i];
  }

  ll ans = 0;
  while (w > 0 && h > 0) {
    ll val0 = p[w-1] * (h+1);
    ll val1 = q[h-1] * (w+1);
    if (p[w-1] < q[h-1]) {
      msg(val0<<" w "<<p[w-1]<<' '<<h);
      ans += val0;
      --w;
    } else {
      msg(val1<<" h "<<q[h-1]<<' '<<w);
      ans += val1;
      --h;
    }
  }
  while (w > 0) {
    ans += p[w-1];
    --w;
  }
  while (h > 0) {
    ans += q[h-1];
    --h;
  }

  return ans;
}

int main() {
  init();
  cout << work() << endl;
}

