  for(int i=0; i<W; i++) ix[i] = i;
  for(int i=0; i<H; i++) ix[W+i] = W+i;

  sort(ix, ix+W+H, comp);

  ll nx = W+1;
  ll ny = H+1;

  ll res=0;
  for(int i=0; i<W+H; i++){
    if(ix[i]/W == 0){ //x
      int x=ix[i]%W;
      res+=P[x]*ny;
      nx--;
