int main() {
	int W, H;
	cin >> W >> H;
	priority_queue<int,vector<int>,greater<int> >P;
	priority_queue<int,vector<int>,greater<int> >Q;
	for (int i = 0; i < W; i++) {
		int buff;
		cin >> buff;
		P.push(buff);
	}
	for (int i = 0; i < H; i++) {
		int buff;
		cin >> buff;
		Q.push(buff);
	}
	int nowW = W;
	int nowH = H;
	int answer = 0;
	while (!P.empty() || !Q.empty()) {
		if (P.empty()) {
			answer += Q.top() * (nowW + 1);
			nowH--;
			Q.pop();
		}
		else if (Q.empty()) {
			answer += P.top() * (nowH + 1);
			nowW--;
			P.pop();
		}
		else {
			if (P.top() * (nowH + 1) < Q.top() * (nowW + 1)) {
				answer += P.top() * (nowH + 1);
				nowW--;
				P.pop();
			}
			else if(P.top() * (nowH + 1) > Q.top() * (nowW + 1)) {
				answer += Q.top() * (nowW + 1);
				nowH--;
				Q.pop();
			}
			else if (Q.top() > P.top()) {
				answer += P.top() * (nowH + 1);
				nowW--;
				P.pop();
			}
			else {
				answer += Q.top() * (nowW + 1);
				nowH--;
				Q.pop();
			}
		}
	}
	cout << answer << endl;

}

