int main() {
	int W, H;
	cin >> W >> H;
	vector<int> q_w, q_h;
	for (int i = 0; i < W; i++) {
		int q;
		cin >> q;
		q_w.push_back(q);
	}
	for (int i = 0; i < H; i++) {
		int q;
		cin >> q;
		q_h.push_back(q);
	}

	vector<vector<int>> points;
	for (int i = 0; i < W; i++) {
		vector<int> row;
		for (int j = 0; j < H; j++) {
			row.push_back(-1);
		}
		points.push_back(row);
	}
	points[0][0] = 0;

	int end = (W > H) ? W : H;
	for (int d = 2; d <= end; d++) {
		for (int i = d-2; i < d && i < W; i++) {
			for (int j = d-2; i + j < d && j < H; j++) {
				int cost = points[i][j];
				if (i - 1 >= 0 && points[i - 1][j] != -1 && (cost == -1 || cost > q_w[i - 1])) cost = q_w[i - 1];
				if (i + 1 < W && points[i + 1][j] != -1 && (cost == -1 || cost > q_w[i + 1])) cost = q_w[i + 1];
				if (j - 1 >= 0 && points[i][j - 1] != -1 && (cost == -1 || cost > q_h[j - 1])) cost = q_h[j - 1];
				if (j + 1 < H && points[i][j + 1] != -1 && (cost == -1 || cost > q_h[j + 1])) cost = q_h[j + 1];
				points[i][j] = cost;
			}
		}
	}
	int cost = 0;
	for (int i = 0; i < W; i++) {
		for (int j = 0; j < H; j++) {
			cost += points[i][j];
		}
	}
	cout << cost << endl;
	return 0;
}

