struct UnionFind {
	vector<int> par;
	vector<int> rank;

	UnionFind(int n) : par(n), rank(n, 0) {
		rep(i, n) par[i] = i;
	}

	int find(int x) {
		if(par[x] == x) return x;
		return par[x] = find(par[x]);
	}

	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if(x == y) return;

		if(rank[x] < rank[y]) {
			par[x] = y;
		} else {
			par[y] = x;
			if(rank[x] == rank[y]) rank[x]++;
		}
	}

	bool same(int x, int y) {
		return find(x) == find(y);
	}
};

