void solve() {
	int ans = 0;
	UnionFind uf(V);
	rep(i, E) {
		int u = edges[i].S.F, v = edges[i].S.S;
		if(!uf.same(u, v)) {
			uf.unite(u, v);
			ans += edges[i].F;
		}
	}
	cout << ans << endl;
}

