// union find tree
class UFT {
    private:
    vector<ll> r;
    vector<ll> p;

    public:
    UFT(ll n) {
        r.resize(n);
        p.resize(n);

        for (ll i = 0; i < n; ++i) {
            r[i] = 0;
            p[i] = i;
        }
    }

    void link(ll x, ll y) {
        if (r[x] > r[y]) {
            p[y] = x;
        } else {
            p[x] = y;

            if (r[x] == r[y]) {
                r[y]++;
            }
        }
    }

    ll find(ll x) {
        if (x != p[x]) {
            p[x] = find(p[x]);
        }
        return p[x];
    }

    bool same(ll x, ll y) {
        return find(x) == find(y);
    }

    void unite(ll x, ll y) {
        link(find(x), find(y));
    }
};

