class UF {
public:
    int size;
    int *id;
    UF(int n) {
        size = n+1;
        id = new int[n];
        for(int i=0; i<=n; i++)
        {
            id[i] = i;
        }
    }

    ~UF() {
        delete [] id;
    }

    int find(int p) {
        if (p != id[p]){
            id[p] = find(id[p]);
        }
        return id[p];
    }

    void unite(int x, int y)    {
        int i = find(x);
        int j = find(y);
        if (i == j) return;
        id[i] = j;
        size--;
    }

    bool connected(int x, int y)    {
        return find(x) == find(y);
    }
};

