  int n = ((w+1) * (h+1)); // 家の総数
  vector< pair<int, int> > house(n);
  rep (i, w+1) {
    rep (j, h+1) {
      house.push_back(make_pair(i, j));
    }
  }

  set<int> pass;
  multimap<int, int> corridor;
  corridor.insert(make_pair(0, 0));  // 原点から

  while (pass.size() < n) {
    int cost = corridor.begin()->first;
    int v = corridor.begin()->second;
