          corridor.insert(make_pair(p[vi], k));
        } else if ((vi - ki) == 1) {
          corridor.insert(make_pair(p[ki], k));
        } else if ((kj - vj) == 1) {
          corridor.insert(make_pair(q[vj], k));
        } else if (vj == (kj + 1)) {
          corridor.insert(make_pair(q[kj], k));
        } else {
