long long getId(long long x, long long y)
{
	return y * (W + 1) + x;
}

bool cmp(pair<long long, long long> p1, pair<long long, long long> p2)
{
	return p1.first < p2.first;
}

long long getPar(vector<long long>& p, long long k)
{
	if (p[k] == k)
		return k;
	return p[k] = getPar(p, p[k]);
}

int main()
{
	long long ans, i, j, k;
	cin >> W >> H;
	long long N = (W + 1) * (H + 1);
	vector<pair<long long, long long>> v;
	for (i = 0; i < W; i++)
	{
		cin >> k;
		v.push_back(make_pair(k, i));
	}
	for (i = 0; i < H; i++)
	{
		cin >> k;
		v.push_back(make_pair(k, i + M));
	}
	sort(v.begin(), v.end(), cmp);
	vector<long long> p(N);
	for (i = 0; i < N; i++)
		p[i] = i;
	for (ans = 0, k = 0, i = 0; i < v.size() && k < N - 1; i++)
	{
		pair<long long, long long> pr = v[i];
		if (pr.second < M)
		{
			for (j = 0; j <= H; j++)
			{
				long long x = getId(pr.second, j), y = getId(pr.second + 1, j);
				long long px = getPar(p, x), py = getPar(p, y);
				if (px == py)
					continue;
				p[px] = py;
				ans += pr.first;
				k++;
			}
		}
		else
		{
			for (j = 0; j <= W; j++)
			{
				long long x = getId(j, pr.second - M), y = getId(j, pr.second - M + 1);
				long long px = getPar(p, x), py = getPar(p, y);
				if (px == py)
					continue;
				p[px] = py;
				ans += pr.first;
				k++;
			}
		}
	}
	cout << ans << endl;
	return 0;
}

