	for(int i=0; i<h; i++){
		if(i==0) q_sum[i] = q_sorted[i];
		else q_sum[i] = q_sum[i-1]+q_sorted[i];
	}
	ll result = q_sum[h-1];
	for(int i=0; i<w; i++){
		int index = lower_bound(q_sorted.begin(), q_sorted.end(), p[i]) - q_sorted.begin();
		result += p[i]*(h+1-index);
		if(index>0) result += q_sum[index-1];
	}
	cout << result << endl;
	return 0;
}

