  auto p = IN.vll(w);
  auto q = IN.vll(h);
  p.push_back(INF);
  q.push_back(INF);
  sort(rall(p));
  sort(rall(q));

  ll cnt = 0;
  ll cntH = 0, cntV = 0;
  ll res = 0;

  while (true) {
    ll take; bool horizontal;
    if (horizontal = p.back() > q.back()) take = q.back(), q.pop_back();
    else take = p.back(), p.pop_back();
    if (take == INF) break;
    if (horizontal) {
      res += (w + 1 - cntV) * take;
      cntH++;
    } else {
      res += (h + 1 - cntH) * take;
      cntV++;
    }
  }

  OUT(res);
}

