void calc() {
    ll res = 0;
    ll v = 0, g = 0;
    sort(p, p + w);
    sort(q, q + h);

    int ip = 0, iq = 0;
    while (ip < w || iq < h) {
        ll pcost = (ip == w ? 1e18 : p[ip]);
        ll qcost = (iq == h ? 1e18 : q[iq]);

        if (pcost < qcost) {
            res += (h + 1 - g) * pcost;
            ++v;
            ++ip;
        } else {
            res += (w + 1 - v) * qcost;
            ++g;
            ++iq;
        }
    }
    cout << res << "\n";
}

void solve() {
    read();
    calc();
}

