using namespace std;

#define REP(i,n) for(int i=0;i<(int)n;++i)
#define FOR(i,c) for(decltype((c).begin())i=(c).begin();i!=(c).end();++i)
#define ALL(c) (c).begin(), (c).end()

typedef long long Weight;
struct Edge {
	int src, dst;
	Weight weight;
	Edge(int src, int dst, Weight weight) :
		src(src), dst(dst), weight(weight) { }
};
bool operator < (const Edge &e, const Edge &f) {
	return e.weight != f.weight ? e.weight > f.weight : // !!INVERSE!!
	e.src != f.src ? e.src < f.src : e.dst < f.dst;
}
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;

typedef vector<Weight> Array;
typedef vector<Array> Matrix;

struct UnionFind {
	vector<int> data;
	UnionFind(int size) : data(size, -1) { }
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) {
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	int size(int x) {
		return -data[root(x)];
	}
};

pair<Weight, Edges> minimumSpanningForest(const Graph &g) {
	int n = g.size();
	UnionFind uf(n);
	priority_queue<Edge> Q;
	REP(u, n) FOR(e, g[u]) if (u < e->dst) Q.push(*e);

	Weight total = 0;
	Edges F;
	while ((int)F.size() < n - 1 && !Q.empty()) {
		Edge e = Q.top(); Q.pop();
		if (uf.unionSet(e.src, e.dst)) {
			F.push_back(e);
			total += e.weight;
		}
	}
	return pair<Weight, Edges>(total, F);
}

int main()
{
	int W, H;
	cin >> W >> H;
	Graph G((W + 1)*(H + 1));
	REP(i, W) {
		int p;
		cin >> p;
		REP(j, H+1) {
			int s = (j*(W + 1)) + i;
			int t = (j*(W + 1)) + i + 1;
			G[s].push_back(Edge(s, t, p));
		}
	}
	REP(j, H) {
		int q;
		cin >> q;
		REP(i, W + 1) {
			int s = (j*(W + 1)) + i;
			int t = ((j + 1)*(W + 1)) + i;
			G[s].push_back(Edge(s, t, q));
		}
	}

	Weight ans;
	tie(ans, ignore) = minimumSpanningForest(G);
	cout << ans << endl;
	return 0;
}

