const int MAXN = 100005 ;

struct Node {
	int v , f , i ;
	Node () {}
	Node ( int v , int f , int i ) : v ( v ) , f ( f ) , i ( i ) {}
	bool operator < ( const Node& a ) const {
		return v < a.v ;
	}
} ;

Node op[MAXN << 1] ;
int px[MAXN] , py[MAXN] ;
int r[MAXN] , c[MAXN] ;
int n , m ;

int F ( int p[] , int x ) {
	return p[x] == x ? x : ( p[x] = F ( p , p[x] ) ) ;
}

void solve () {
	for ( int i = 0 ; i <= n ; ++ i ) {
		px[i] = i ;
	}
	for ( int i = 0 ; i <= m ; ++ i ) {
		py[i] = i ;
	}
	int c = 0 , v ;
	for ( int i = 0 ; i < n ; ++ i ) {
		scanf ( "%d" , &v ) ;
		op[c ++] = Node ( v , 0 , i ) ;
	}
	for ( int i = 0 ; i < m ; ++ i ) {
		scanf ( "%d" , &v ) ;
		op[c ++] = Node ( v , 1 , i ) ;
	}
	int cntx = n + 1 ;
	int cnty = m + 1 ;
	sort ( op , op + c ) ;
	LL ans = 0 ;
	for ( int i = 0 ; i < c ; ++ i ) {
		if ( op[i].f == 0 ) {
			int x = F ( px , op[i].i ) ;
			int y = F ( px , op[i].i + 1 ) ;
			if ( x == y ) continue ;
			ans += 1LL * cnty * op[i].v ;
			px[x] = y ;
			cntx -- ;
			//printf ( "ok 1 %lld\n" , ans ) ;
		} else {
			int x = F ( py , op[i].i ) ;
			int y = F ( py , op[i].i + 1 ) ;
			if ( x == y ) continue ;
			ans += 1LL * cntx * op[i].v ;
			py[x] = y ;
			cnty -- ;
			//printf ( "ok 2 %lld\n" , ans ) ;
		}
	}
	printf ( "%lld\n" , ans ) ;
}

int main () {
	while ( ~scanf ( "%d%d" , &n , &m ) ) solve () ;
	return 0 ;
}

