		if (P.empty()) {
			answer += Q.top() * (nowW + 1);
			nowH--;
			Q.pop();
		}
		else if (Q.empty()) {
			answer += P.top() * (nowH + 1);
			nowW--;
			P.pop();
		}
		else {
			if (P.top() * (nowH + 1) + Q.top() * (nowW)<=P.top() * (nowH) + Q.top() * (nowW + 1)) {
				answer += P.top() * (nowH + 1);
				nowW--;
				P.pop();
			}
			else if(P.top() * (nowH + 1) + Q.top() * (nowW) > P.top() * (nowH)+Q.top() * (nowW + 1)) {
				answer += Q.top() * (nowW + 1);
				nowH--;
				Q.pop();
			}
			else if (Q.top() > P.top()) {
