			for(int jdx = 0; jdx < n; jdx++){
				cout << m[idx][jdx] << " ";
			}
			cout << endl;
		}
	}



	d[0] = 0;
	while(1){
		minv = INFTY;
		u = -1;
		for(int i = 0; i < n; i++){
			if(minv > d[i] && color[i] != BLACK){
				u = i;
				minv = d[i];
			}
		}
		if(u==-1)
			break;
		color[u] = BLACK;
		for(int v = 0; v < n; v++){
			if(color[v] !=BLACK && m[u][v] != INFTY){
				if(d[v] > m[u][v]){
					d[v] = m[u][v];
					p[v] = u;
					color[v] = GRAY;
				}
			}	
		}
	}
	int sum = 0;
	for(int i = 0; i< n; i++){
		if(p[i] != -1){
			sum += m[i][p[i]];
		}
	}
	cout << sum << endl;
}

