    const long p = ps[m], q = qs[n];
    if (p < q) {
      ans += p * (H + 1 - n);
      m++;
    } else {
      ans += q * (W + 1 - m);
      n++;
    }
  }
  printf("%ld\n", ans);

  return 0;
}

