void solve() {
    int w, h;
    cin >> w >> h;
    vector<ll> p(w);
    REP(i, w) cin >> p[i];
    vector<ll> q(h);
    REP(i, h) cin >> q[i];
    sort(ALL(p)); 
    sort(ALL(q));

    int c = 0;
    int r = 0;
    ll ans = 0;
    while (c < w && r < h) {
        if (p[c] > q[r]) {
            ans += q[r] * (w + 1 - c);
            r++;
        } else {
            ans += p[c] * (h + 1 - r);
            c++;
        }
    }
    if (c == w) {
        FOR(i, r, h) {
            ans += q[i];
        }
    } else {
        FOR(i, c, w) {
            ans += p[i];
        }
    }
    cout << ans << EOL;

}

