  sort(p, p + W);
  sort(q, q + H);
  for (int i = 0; i < H; i++) {
    cumq[i + 1] = cumq[i] + q[i];
  }
  for (int i = 0; i < W; i++) {
    int pos = upper_bound(q, q + H, p[i]) - q;
    ans += cumq[pos] + (ll)p[i] * (H - pos);
  }
  cout << ans << endl;

  return 0;
}

