void solve() {
	priority_queue<pair<int, pii>, vector<pair<int, pii> >, greater<pair<int, pii> > > que;
	ll W, H; cin >> W >> H;
	REP(i, W) que.emplace(in(), pii(i, 0));
	REP(i, H) que.emplace(in(), pii(i, 1));

	ll w = W+1, h = H+1;

	ull res = 0;

	while (not que.empty()) {
		auto a = que.top(); que.pop();
		if (a.second.second == 0) {
			res += a.first*h;
			--w;
		}
		else if (a.second.second == 1	) {
			res += a.first*w;
			--h;
		}
	}
	cout << res << endl;
}

