    q[h] = INT_MAX;

    while ((i<w)||(j<h)) {
        if (p[i] < q[j]) {
            ans += p[i]*(h-m+1);
            n++;
            i++;
        } else {
            ans += q[j]*(w-n+1);
            m++;
            j++;
        }
    }
    printf("%ld\n", ans);
    return 0;
}

