int binarySearch(int x){
   int st = 0;
   int en = b.size() - 1;
   int iter = 40;
   int mid;
   ++x;
   while(iter--){
      mid = (st + en) / 2;
      if(b[mid] < x){
         st = mid;
      }
      else{
         en = mid;
      }
   }
   --x;
   int res = -1;
   for(int i = max((int)0, mid - 5); i <= min((int)b.size() - 1, mid + 5); ++i){
      if(b[i] <= x){
         res = i;
      }
   }
   return res;
}

