void dfs(vector<vector<pair<ll,ll> > > &v, int i, int j,int W,int H, pair<ll,ll> old_i, pair<ll,ll> new_i)
{
  if (v[i][j] == old_i)
    {
      v[i][j] = new_i;
      if (i < W){
	dfs(v,i+1,j,W,H,old_i, new_i);
      }
      if (i > 0){//left
	dfs(v,i-1,j,W,H,old_i, new_i);
      }
      if (j < H){//up
	dfs(v,i,j+1,W,H,old_i, new_i);
      }
      if (j > 0){//down
	dfs(v,i,j-1,W,H,old_i, new_i);
      }
    }

}

