// kruskal
struct edge {
  int u, v, cost;
};

bool comp(const edge &e1, const edge &e2) {
  return e1.cost < e2.cost;
}

vector<edge> v;
edge es;
int N, M; // 頂点数と辺の数

int kruskal() {
  int res = 0, num = 0;;
  uf_init(N);
  sort(v.begin(), v.end(), comp);
  rep(i,M) {
    //cout << v[i].u << " " << v[i].v << " " << v[i].cost << endl;
    edge e = v[i];
    if (!same(e.u, e.v)) {
      //cout << e.u << " " << e.v << endl;
      unite(e.u, e.v);
      res += e.cost;
      num++;
    }
    if(num == M-1) break;
  }
  return res;
}

// Union Find
void uf_init(int n) {
  rep(i,n+1) { parent[i] = i; ranks[i] = 0; }
}
int find(int x) {
  if (parent[x] == x) return x;
  else return parent[x] = find(parent[x]);
}
void unite(int x, int y) {
  x = find(x);
  y = find(y);
  if(x == y) return;
  if (ranks[x] < ranks[y]) parent[x] = y;
  else {
    parent[y] = x;
    if(ranks[x] == ranks[y]) ranks[x]++;
  }
}
bool same(int x, int y) {
  return find(x) == find(y);
}


