using namespace std;

int W, H;
vector<int> p, q;
using pos_type = pair<int, int>;
using frontier_type = multimap<int, pos_type>;

set<pos_type> visited;
frontier_type frontier;

int cost(int i1, int j1, int i2, int j2)
{
    if (i1 == i2) {
        return j1 > j2 ? q[j2] : q[j1];
    } else {
        return i1 > i2 ? p[i2] : p[i1];
    }
}

void add(int i, int j)
{
    int di[] = {0, 0, 1, -1};
    int dj[] = {1, -1, 0, 0};

    visited.insert(make_pair(i, j));
    for (int k = 0; k < 4; ++k) {
        int i2 = i + di[k];
        int j2 = j + dj[k];
        if (i2 < 0 or i2 > W or j2 < 0 or j2 > H) continue;
        auto pos = make_pair(i2, j2);
        auto c = cost(i, j, i2, j2);

        auto range = frontier.equal_range(c);
        for (auto ri = range.first; ri != range.second; ++ri) {
            if (ri->second.first == i and ri->second.second == j) {
                frontier.erase(ri);
            }
        }

        if (visited.find(pos) == visited.end()) {
            frontier.insert(make_pair(c, pos));
        }
    }

}

int main()
{
    cin >> W >> H;
    p.reserve(W);
    q.reserve(H);
    for (int i = 0; i < W; ++i) {
        int v; cin >> v;
        p.push_back(v);
    }
    for (int j = 0; j < H; ++j) {
        int v; cin >> v;
        q.push_back(v);
    }

    add(0, 0);
    int WH = (W+1)*(H+1);
    long sum = 0;
    while (visited.size() < WH) {
        auto top = frontier.begin();
		auto c = top->first;
        int i = top->second.first;
        int j = top->second.second;
        sum += c;
        frontier.erase(top);
        add(i, j);
    }

    cout << sum << endl;

    return 0;
}

