	vector<Q> es;
	REPU(i, 0, w) REPU(j, 0, h + 1) {
		es.push_back(Q(p[i], P(encode(i, j, h), encode(i + 1, j, h))));
	}
	REPU(i, 0, w + 1) REPU(j, 0, h) {
		es.push_back(Q(q[j], P(encode(i, j, h), encode(i, j + 1, h))));
	}

	sort(ALL(es));
	UF uf(encode(w, h, h));
	ll ans = 0;
	REPU(i, 0, es.size()) {
		if (uf.unite(es[i].second.first, es[i].second.second)) {
			ans += es[i].first;
		}
	}
	cout << ans << endl;

	return 0;
}

