    }
    ans += (h-pos)*p[i];
    //cout << p[i] << ":" << h-pos << endl;
  }
  rep(i,q.size()){
    it = upper_bound(all(p), q[i]);
    pos = it - p.begin();
    ans += (w-pos)*q[i];
    //cout << q[i] << "::" << w-pos << endl;
  }
  cout << ans << endl;
  return 0;
}

