void c3_init(ll m){
    fact[0]  = rfact[0] = 1;
    for(int i=1; i<400000; i++){
        fact[i] = (fact[i-1]*i)%m;
        rfact[i] = minverse(fact[i],m);
    }
}
ll c3(ll n, ll k, ll m){
    return (((fact[n] * rfact[k])%m) * rfact[n-k])%m;
}


