{
  if (v[i][j] == old_i)
    {
      v[i][j] = new_i;
      if (i < W){//right
	//cout<<"r"<<endl;
	dfs(v,i+1,j,W,H,old_i, new_i);
	      }

      if (i > 0){//left
	//cout<<"l"<<endl;
	dfs(v,i-1,j,W,H,old_i, new_i);
      }

      if (j < H){//up
	//cout<<"u"<<endl;
	dfs(v,i,j+1,W,H,old_i, new_i);
      }
      if (j > 0){//down
	//cout<<"d"<<endl;
	dfs(v,i,j-1,W,H,old_i, new_i);
      }

    }

