    ll a = W + 1, b = H + 1;
    ll ans = 0;
    while(!pq.empty()){
        auto [val, flag] = pq.top();
        pq.pop();
        if(!flag){
            ans += val * b;
            --a;
        }else{
            ans += val * a;
            --b;
        }
    }

    print(ans);

    return 0;
}

