class Point{
private:
	int x;
	int y;
public:
	Point(int _x,int _y){
		x=_x;
		y=_y;
	}
	void Dist(Point *p,int &dx,int &dy){
		dx = x - p->x;
		if (dx<0){
			dx=-dx;
		}
		dy = y - p->y;
		if (dy<0){
			dy=-dy;
		}
	}
	int GetX(){return x;}
	int GetY(){return y;}
};
int main(int argc, char* argv[])
{
	int W,H;
	cin>>W>>H;
	int i,j;
	vector<long long> p(W,0);
	vector<long long> q(H,0);
	for (i=0;i<W;i++){
		cin>>p[i];
	}
	for (i=0;i<H;i++){
		cin>>q[i];
	}

	const int PNUM=(W+1)*(H+1);
	vector<Point*> P(PNUM);
	long long cost=0;
	int pNum=0;
	for (i=0;i<=W;i++){
		for (j=0;j<=H;j++){
			P[pNum++] = new Point(i,j);
		}
	}
	for (i=0;i<pNum-1;i++){
		for (j=i+1;j<pNum;j++){
			int dx,dy;
			P[i]->Dist(P[j],dx,dy);
			if (dx==1 && dy==0){
				cost+=p[P[i]->GetX()];
			}
			if (dx==0 && dy==1){
				cost+=q[P[i]->GetY()];
			}
		}
	}
	cout<<cost<<endl;
	for (i=0;i<pNum-1;i++){
		delete P[i];
	}
	P.clear();
	return 0;
}

