#define ll unsigned long long

ll get(vector<ll> &stu, ll id){
	ll out = stu[id];
	if (out != id) {
		out = get(stu, out);
		stu[id] = out;
	}
	return out;
}

bool myunion(vector<ll> &stu, unordered_set<ll> &cache, ll id1, ll id2){
	ll a = get(stu, id1);
	ll b = get(stu, id2);
	if (a == b){
		return false;
	}
	cache.erase(a);
	stu[a] = b;
	return true;
}

int main(){
	ll w, h;
	cin >> w >> h;
	//vector<double> myw(w, 0), myh(h, 0);
	map<ll,deque<ll>> myw, myh;
	for (ll i = 0; i < w; ++i){
		ll tmp;
		cin >> tmp;
		myw[tmp].push_back(i);
	}
	for (ll i = 0; i < h; ++i){
		ll tmp;
		cin >> tmp;
		myh[tmp].push_back(i);
	}
	++w, ++h;
	vector<ll> stu(w*h);
	unordered_set<ll> cache;
	for (ll i = 0; i < w*h; ++i){
		stu[i] = i;
		cache.insert(i);
	}
	ll out = 0;
	while (cache.size()>1){
		ll id = 0, cost = 0;
		bool tmp = true;
		if (!myh.empty() && !myw.empty()){
			auto a = myh.begin();
			auto b = myw.begin();
			auto c = a->first < b->first ? a : b;
			tmp = a->first < b->first ? true : false;
			id = c->second.front();
			cost = c->first;
		}
		else if (!myh.empty()){
			id = myh.begin()->second.front();
			cost = myh.begin()->first;
			tmp = true;
		}
		else if (!myw.empty()){
			id = myw.begin()->second.front();
			cost = myw.begin()->first;
			tmp = false;
		}

		if (tmp){
			for (ll i = 0; i < w; ++i){
				ll offset1 = id*w + i;
				ll offset2 = (id + 1)*w + i;
				if (myunion(stu, cache, offset1, offset2)){
					out += cost;
				}
			//	cout << tmp << " " << offset1 << " " << offset2 <<" "<< out << endl;
			}
			myh[cost].pop_front();
			if (myh[cost].size() == 0){
				myh.erase(cost);
			}
		}
		else{
			for (ll i = 0; i < h; ++i){
				ll offset1 = i*w + id;
				ll offset2 = offset1 + 1;
				if (myunion(stu, cache, offset1, offset2)){
					out += cost;
				}
				//cout << tmp << " " << offset1 << " " << offset2 <<" "<<out<<endl;
			}
			myw[cost].pop_front();
			if (myw[cost].size()  == 0){
				myw.erase(cost);
			}
		}
	}
	cout << out << endl;
	return 0;
}

