struct A {
    int type;
    int value;

    A () {}
    A (int a, int b): type(a), value(b) {}

    bool operator < (const A& o) const {
        return value == o.value ? type > o.value : value > o.value;
    }
};

int W, H;
int p[100010], q[100010];


int main() {
    cin >> W >> H;
    for (int j = 0; j < W; ++j) {
        cin >> p[j];
    }
    for (int j = 0; j < H; ++j) {
        cin >> q[j];
    }

    priority_queue<A> pq;

    for (int j = 0; j < W; ++j) {
        pq.push(A(0, p[j]));
    }

    for (int k = 0; k < H; ++k) {
        pq.push(A(1, q[k]));
    }

    LL ret = 0;

    int mul[2] = {H+1, W+1};

    while (!pq.empty()) {
        A x = pq.top(); pq.pop();

        ret += x.value * mul[x.type];

        --mul[1-x.type];
    }

    cout << ret << endl;

    return 0;
}

