	long long W;
	long long H;
	scanf("%lld",&W);
	vector<long long> p((W-1)-0+1);
	scanf("%lld",&H);
	vector<long long> q((H-1)-0+1);
	for(int i = 0 ; i <= (W-1)-0 ; i++){
		scanf("%lld",&p[i]);
	}
	for(int i = 0 ; i <= (H-1)-0 ; i++){
		scanf("%lld",&q[i]);
	}
	solve(W, H, p, q);
	return 0;
}

