struct node{
    int y, x;
    LLN weight;
    node( int _y, int _x, LLN _w ) : y( _y ), x( _x ), weight( _w ){};
};

const int nmax = 10000 + 7;
char **mask;

int PP[nmax], QQ[nmax];

struct cmp{
    bool operator () ( const node &n1, const node &n2 ) const{
        return n1.weight > n2.weight;
    }
};

void pre(){
    mask = new char*[nmax];
    for( int i = 0;i < nmax;++i ){
        mask[i] = new char[nmax];
        memset( mask[i], 0, nmax* sizeof( mask[i][0] ) );
    }
}

void init(){
    for( int i = 0;i < nmax;++i ){
        memset( mask[i], 0, nmax* sizeof( mask[i][0] ) );
    }
    memset( PP, 0, sizeof( PP ) );
    memset( QQ, 0, sizeof( QQ ) );
}

const int dy[] = { 0, 0, 1, -1 };
const int dx[] = { 1, -1, 0, 0 };

//iejr: Main Function
int main()
{

#ifdef INPUT_REDIRECTION
    freopen( "in.txt", "r", stdin );
#endif // INPUT_REDIRECTION

#ifdef OUTPUT_REDIRECTION
    freopen( "out.txt", "w", stdout );
#endif // OUTPUT_REDIRECTION

    pre();

    int W, H;
    while( scanf( "%d%d", &W, &H ) != EOF ){
        init();
        for( int i = 0;i < H;++i )scanf( "%d", PP + i );
        for( int j = 0;j < W;++j )scanf( "%d", QQ + j );

        LLN ret = 0;
        priority_queue<node, vector<node>, cmp> q;
        q.emplace( 0, 0, 0 );
        mask[0][0] = 1;
        while( !q.empty() ){
            int y = q.top().y;
            int x = q.top().x;

            if( !mask[y][x] )
                ret += q.top().weight;
            mask[y][x] = 1;
            q.pop();

            for( int t = 0;t < 4;++t ){
                int i = y + dy[t];
                int j = x + dx[t];

                if( i < 0 || i > H || j < 0 || j > W || mask[i][j] )continue;
                if( t == 0 ){
                    q.emplace( i, j, QQ[x] );
                }
                else if( t == 1 ){
                    q.emplace( i, j, QQ[x - 1] );
                }
                else if( t == 2 ){
                    q.emplace( i, j, PP[y] );
                }
                else{
                    q.emplace( i, j, PP[y - 1] );
                }
            }
        }

        printf( "%lld\n", ret );
    }

    for( int i = 0;i < nmax;++i )delete[] mask[i];
    delete mask;

#ifdef INPUT_REDIRECTION
    fclose( stdin );
#endif // INPUT_REDIRECTION

#ifdef OUTPUT_REDIRECTION
    fclose( stdout );
#endif // OUTPUT_REDIRECTION

    return 0;
}

