// O(V^3) 有向グラフ
class WarshallFloyd {
private:
  Graph graph;
  int nodes = this->graph.nodes + 1;
  vector<vector<ll>> distances;

public:
  WarshallFloyd(Graph graph) {
    this->graph = graph;
    nodes = this->graph.nodes + 1;
    this->distances = vector<vector<ll>>(nodes, vector<ll>(nodes, INF));
    itrep(edge, graph.edges) {
      int from = edge->from;
      int to = edge->to;
      int cost = edge->cost;
      distances[from][to] = cost;
    }
  }
  void searchMinimumPath() {
    for (int k = 0; k < nodes; k++) {
      for (int i = 0; i < nodes; i++) {
        for (int j = 0; j < nodes; j++) {
          if (distances[i][k] == INF || distances[k][j] == INF) {
            continue;
          }
          if (distances[i][k] + distances[k][j] < distances[i][j]) {
            distances[i][j] = distances[i][k] + distances[k][j];
          }
        }
      }
    }
  }
  ll getDistance(int from, int to) { return distances[from][to]; }
};

void solve(long long W, long long H, std::vector<long long> p,
           std::vector<long long> q) {

  vector<pair<ll, bool>> cost_pq; // true: p, false: q
  rep(i, 0, W) { cost_pq.push_back(mp(p[i], true)); }
  rep(i, 0, H) { cost_pq.push_back(mp(q[i], false)); }
  sortAscending(cost_pq);

  ll ans = 0;
  int pcnt = 0;
  int qcnt = 0;
  for (auto cpq : cost_pq) {
    if (cpq.second) { // p
      ans += cpq.first * (H + 1 - qcnt);
      pcnt++;
    } else { // q
      ans += cpq.first * (W + 1 - pcnt);
      qcnt++;
    }
  }
  print(ans);
}

int main() {
  long long W;
  scanf("%lld", &W);
  long long H;
  scanf("%lld", &H);
  std::vector<long long> p(W);
  for (int i = 0; i < W; i++) {
    scanf("%lld", &p[i]);
  }
  std::vector<long long> q(H);
  for (int i = 0; i < H; i++) {
    scanf("%lld", &q[i]);
  }
  solve(W, H, std::move(p), std::move(q));
  return 0;
}


