long long int saiki( long long int W, long long int H, vector<long long int>P, vector<long long int >Q ) {
	if( W == 0 && H == 0 ) {
		return 0;
	}
	long long int a;
	if( P.size() == 0 && Q.size() > 0 ) {
		a = Q[Q.size() - 1];
		Q.pop_back();
		return a * (W + 1) + saiki( W, H - 1, P, Q );
	}
	if( Q.size() == 0 && P.size() > 0 ) {
		a = P[P.size() - 1];
		P.pop_back();
		return a * (H + 1) + saiki( W - 1, H, P, Q );
	}
	if( P.size() > 0 && P[P.size() - 1] * (H + 1) < Q[Q.size() - 1] * (W + 1) ) {
		a = P[P.size() - 1];
		P.pop_back();
		return a * (H + 1) + saiki( W - 1, H, P, Q );
	} else if( Q.size() > 0 ) {
		a = Q[Q.size() - 1];
		Q.pop_back();
		return a* (W + 1) + saiki( W, H - 1, P, Q );
	} else {
		return 0;
	}
}

