	ll pass = 0LL;
	sort(all(v));
	rep(i, v.size()){
		ll k = 0LL;
		if(v[i].se == 0){
			if(h-d[0]<0) continue;
			if(pass+h-d[0]>(ll)w*h){
				k = (ll)w*h-pass;
			}
			else k = h-d[0];
			ans += k*v[i].fi;
			d[1]++;
		}
		else{
			if(w-d[1]<0) continue;
			if(pass+w-d[1]>(ll)w*h){
				k = (ll)w*h-pass;
			}
			else k =w-d[1];
			ans += k*v[i].fi;
			d[0]++;
		}
		pass += k;
		//cout<<" "<<ans<<" "<<d[0]<<" "<<d[1]<<" "<<pass<<endl;
	}
	cout<<ans<<endl;
}

