struct Info{
  ll cost;
  bool is_tate;

  bool operator<(const Info &another) const{
    return cost < another.cost;
  }
  bool operator>(const Info &another) const{
    return cost > another.cost;
  }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    ll W, H; cin >> W >> H;
    ll a = W+1;
    ll b = H+1;

    priority_queue<Info, vector<Info>, greater<Info>> que;

    // 縦
    rep(i, W){
      ll p; cin >> p;
      Info info;
      info.is_tate = true;
      info.cost = p;
      que.push(info);
    }

    // よこ
    rep(i, H){
      ll p; cin >> p;
      Info info;
      info.is_tate = false;
      info.cost = p;
      que.push(info);
    }

    ll sum = 0;
    while(!que.empty()){
      auto info = que.top(); que.pop();
      if(info.is_tate){
        sum += b * info.cost;
        a--;
      }
      else{
        sum += a * info.cost;
        b--;
      }
    }
    p(sum);

    return 0;
}

