struct S{
	int t;
	int c;
	int i;
	S(){};
	S(int t, int c, int i) : 
		t(t), c(c), i(i) {};
	bool operator<(S const &a) const{
		if(c != a.c) return c < a.c;
		if(t != a.t) return t < a.t;
		return i < a.i;
	};
};

set<S> q;

void solve(){
	int w, h;
	scanf("%d %d",&w,&h);
	fi(0, w){
		int pi;
		scanf("%d ",&pi);
		q.insert(S(0, pi, i));
	}
	fi(0, h){
		int qi;
		scanf("%d",&qi);
		q.insert(S(1, qi, i));
	}

	ll ans = 0;
	ll takeW = 0;
	ll takeH = 0;
	while(sz(q)){
		S cur = (*q.begin());
		q.erase(cur);

		if(cur.t == 0){
			ans += (h + 1 - takeH) * 1LL * cur.c;
			++takeW;
		}else{
			ans += (w + 1 - takeW) * 1LL * cur.c;
			++takeH;
		}
	}
	printf("%lld\n",ans);
}

