struct DSU {
    vector<int> p, r;
    int n;

    DSU (int n): p(n), r(n, 1), n(n) {
        for (int i = 0; i < n; ++i) p[i] = i;
    }

    int parent(int x) {
        if (p[x] == x) return x;
        return p[x] = parent(p[x]);
    }

    void unite(int a, int b) {
        a = parent(a);
        b = parent(b);
        if (a == b)return;
        if (r[a] < r[b]) swap(a, b);
        p[b] = a;
        n--;
        if (r[a] == r[b]) r[a]++;
    }
};

