void solve(long long W, long long H, std::vector<long long> p, std::vector<long long> q){
    vector<pair<int,int>> v;

    for(int i = 0; i < W; ++i) {
        v.push_back(make_pair(p[i], 0LL));
    }
    for(int j = 0; j < H; ++j) {
        v.push_back(make_pair(q[j], 1LL));
    }
    sort(ALL(v));
    int res = 0;
    int a = W + 1, b = H + 1;
    for(int i = 0; i < v.size(); ++i) {
        if (v[i].second == 0) {
            res += v[i].first * b;
            a--;
            if (b == 1) break;
        } else {
            res += v[i].first * a;
            b--;
            if (a == 1) break;
        }
    }
    cout << res << endl;
}

