using namespace std;

const int MAX_V = 100000; //頂点の数の最大値
const int MAX_E = 100000; //辺の数の最大値
const int INF = INT_MAX; //適当な大きな値

struct E{
  int to, cost;
  E(int t, int c) : to(t), cost(c) {};
};
typedef pair<int, int> pii;


int v; //頂点数
vector<E> g[MAX_V]; //隣接リスト
int mincost[MAX_V]; //全域木と頂点を結ぶ辺の最小コスト
bool used[MAX_V]; //ある頂点が全域木に含まれているか


int prim()
{
  fill(mincost, mincost + v, INF);
  fill(used, used + v, false);
  mincost[0] = 0;
  int ans = 0; //最小全域木の辺の総コスト
  priority_queue<pii, vector<pii>, greater<pii> > q;
  q.push(pii(0, 0));

  //全域木に辺を追加していく
  while(!q.empty()){
    //まだ追加していない頂点のうちコストが最小のものを探す
    //その頂点に関しては、最小コストが確定する
    pii p = q.top();
    q.pop();
    int u = p.second;
    if(used[u] || mincost[u] < p.first) continue;

    //追加した頂点に隣接する頂点の情報を更新
    ans += mincost[u];
    used[u] = true;

    for(int i = 0; i < g[u].size(); i++){
      int w = g[u][i].to;
      int cost = g[u][i].cost;


      if(mincost[w] > cost){ //最小コストとなりうる場合
        mincost[w] = cost;
        q.push(pii(mincost[w], w)); //最小コストの候補をヒープに挿入
      }
    }
  }

  return ans;
}

int main()
{
  int H, W;
  cin >> H >> W;
  v = (H+1)*(W+1);
  for(int i = 0; i < W; i++){
    int p;
    cin >> p;
    for(int j = 0; j <= H; j++){
      g[i+j*(W+1)].push_back(E(i+j*(W+1)+1, p));
      g[i+j*(W+1)+1].push_back(E(i+j*(W+1), p));
    }
  }
  for(int i = 0; i < H; i++){
    int q;
    cin >> q;
    for(int j = 0; j <= W; j++){
      g[j+i*(W+1)].push_back(E(j+(i+1)*(W+1), q));
      g[j+(i+1)*(W+1)].push_back(E(j+i*(W+1), q));
    }
  }

  cout << prim() << endl;
}

