        } else if (qc == H) {
            cost = p[pc];
            pc++;
            from_p = true;
        } else if (p[pc] <= q[qc]) {
            cost = p[pc];
            pc++;
            from_p = true;
        } else {
            cost = q[pc];
            qc++;
            from_p = false;
        }
        if (from_p) {
            ans += (H+1-y)*cost;
            y++;
        } else {
            ans += (W+1-x)*cost;
            x++;
        }
    }

    cout << ans << endl;

    return 0;
}

