using namespace std;
typedef long long ll;
const int WHmax = 1000000;
ll W,H;
ll P[WHmax], Q[WHmax];
ll ix[2*WHmax];
ll all[2*WHmax];

bool comp(int i, int j){
  return all[i] < all[j];
}

int main(){
  cin >> W >> H;
  for(int i=0; i<W; i++) cin >> P[i];
  for(int i=0; i<H; i++) cin >> Q[i];

  for(int i=0; i<W; i++) all[i] = P[i];
  for(int i=0; i<H; i++) all[W+i] = Q[i];
  for(int i=0; i<W; i++) ix[i] = i;
  for(int i=0; i<H; i++) ix[W+i] = W+i;

  sort(ix, ix+W+H, comp);

  ll nx = W+1;
  ll ny = H+1;

  ll res=0;
  for(int i=0; i<W+H; i++){
    if(ix[i]<W){
      int x=ix[i]%W;
      res+=P[x]*ny;
      nx--;
    }
    else{
      int y=ix[i]%W;
      res+=Q[y]*nx;
      ny--;
    }
  }

  cout << res << endl;
  return 0;
}

