typedef long long int int64;

void sort(int *a,int n){
  if(n<=1) return;
  int p=rand()%n;
  int pivot=a[p];
  a[p]=a[0];
  int cnt=1;
  int index=0;
  int l=1;
  int r=n;
  while(l<r){
    if(a[l]==pivot){
      cnt++;
    } else if(a[l]<pivot){
      a[index++]=a[l++];
    } else {
      int swap=a[l];
      a[l]=a[r-1];
      a[r-1]=swap;
      r--;
    }
  }
  sort(a,index);
  sort(a+l,n-l);
  while(cnt--) a[index++]=pivot;
}

