#include <stdio.h>

void merge_sort(int x[], int n)
{
	static int y[100001] = {};
	if (n <= 1) return;
	merge_sort(&(x[0]), n/2);
	merge_sort(&(x[n/2]), (n+1)/2);

	int i, p, q;
	for (i = 0, p = 0, q = n/2; i < n; i++) {
		if (p >= n/2) y[i] = x[q++];
		else if (q >= n) y[i] = x[p++];
		else y[i] = (x[p] < x[q])? x[p++]: x[q++];
	}
	for (i = 0; i < n; i++) x[i] = y[i];
}

int main()
{
	int i, j, W, H, p[100001], q[100001];
	scanf("%d %d", &W, &H);
	for (i = 0; i < W; i++) scanf("%d", &(p[i]));
	for (j = 0; j < H; j++) scanf("%d", &(q[j]));
	merge_sort(p, W);
	merge_sort(q, H);

	int count[2] = {};
	long long ans = 0;
	for (i = 0, j = 0; i < W || j < H; ) {
		if (i == W) ans += q[j++];
		else if (j == H) ans += p[i++];
		else if (p[i] < q[j]) {
			ans += (long long)p[i++] * (H - count[1] + 1);
			count[0]++;
		} else {
			ans += (long long)q[j++] * (W - count[0] + 1);
			count[1]++;
		}
	}

	printf("%lld\n", ans);
	fflush(stdout);
	return 0;
}

