import java.io.IOException;
import java.io.InputStream;
import java.io.PrintStream;
import java.util.NoSuchElementException;

public class Main {
	static FastScanner sc = new FastScanner();
	static PrintStream out = System.out;
	static long sumX[];
	static long sumY[];
	static long sortX[];
	static long sortXidx[];
	static long sortY[];
	static long sortYidx[];

	public static void main(String args[]) {
		int W = ni();
		int H = ni();
		int p[] = na(W);
		int q[] = na(H);
		sumX = new long[W+1];
		sumY = new long[H+1];
		for (int x=0;x<W;x++) {
			sumX[x+1] = sumX[x] + p[x];
		}
		for (int y=0;y<H;y++) {
			sumY[y+1] = sumY[y] + q[y];
		}

		System.out.println(f(0, 0, W, H, p, q, 0, 0, 0, 0));
	}

	private static long f(int x0, int y0, int x1, int y1, int p[], int q[], int maxX, int maxY, int maxXidx, int maxYidx) {
		if (x0 == x1) {
			long ret = 0;
			ret = sumY[y1] - sumY[y0];
			return ret;
		} else if (y0 == y1) {
			long ret = 0;
			ret = sumX[x1] - sumX[x0];
			return ret;
		}

		if (maxX == 0)
			for (int x=x0;x<x1;x++) {
				if (maxX < p[x]) {
					maxX = p[x];
					maxXidx = x;
				}
			}

		if (maxY == 0)
			for (int y=y0;y<y1;y++) {
				if (maxY < q[y]) {
					maxY = q[y];
					maxYidx = y;
				}
			}

		if (maxX > maxY) {
			long ret =
					f(x0, y0, maxXidx, y1, p, q, 0, maxY, 0, maxYidx) + 
					f(maxXidx+1, y0, x1, y1, p, q, 0, maxY, 0, maxYidx) + 
					maxX;
			return ret;
		} else {
			long ret =
					f(x0, y0, x1, maxYidx, p, q, maxX, 0, maxXidx, 0) + 
					f(x0, maxYidx+1, x1, y1, p, q, maxX, 0, maxXidx, 0) + 
					maxY;
			return ret;
		}
	}

	private static String next() {
		return sc.next();
	}

	private static int ni() {
		return sc.nextInt();
	}

	private static long nl() {
		return sc.nextLong();
	}

	private static int[] na(int n) {
		int[] a = new int[n];
		for(int i = 0;i < n;i++) a[i] = ni();
		return a;
	}

	private static long[] nal(int n) {
		long[] a = new long[n];
		for(int i = 0;i < n;i++) a[i] = ni();
		return a;
	}

    private static double nd() {
        return Double.parseDouble( next() );
    }
}

