			cs[i] = t;
		}
		for(int i=0;i<H;i++){
			long t = (long)ni();
			h.add(t);
			cs[i+W] = -t;
		}
		Arrays.sort(cs, new Comparator<Long>(){
			public int compare(Long o1, Long o2){
