			}
		});
//		debug(cs);
		long cost = 0;
		long wp = 0;
		long hp = 0;

		if(cs[0] >= 0){
			cost += (H + 1) * cs[0];
			wp++;
		}else{
			cost -= (W + 1) * cs[0];
			hp++;
		}
//		debug(cost);

