		X b[] = new X[p.length + q.length];

		for (int i = 0; i < p.length; ++i) {
			b[i] = new X(p[i], i, -1);
		}
		for (int i = 0; i < q.length; ++i) {
			b[p.length + i] = new X(q[i], -1, i);
		}
		Arrays.sort(b, (i, j) -> i.c - j.c);

		long res = 0;
		for (int i = 0, n = w + 1, m = h + 1; i < b.length; ++i) {
			if (b[i].x == -1) {
				res += b[i].c * n;
				--m;
			} else {
				res += b[i].c * m;
				--n;
			}
		}
		out.println(res);
	}

	class X {
		final int c, x, y;

		X(int c, int x, int y) {
			this.c = c;
			this.x = x;
			this.y = y;
		}
	}

