/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        CGrIdianMST solver = new CGrIdianMST();
        solver.solve(1, in, out);
        out.close();
    }

    static class CGrIdianMST {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int w = in.readInt();
            int h = in.readInt();
            long[] p = in.readLongArray(w);
            long[] q = in.readLongArray(h);
            List<LongIntPair> list = new ArrayList<>();
            for (long x : p) list.add(new LongIntPair(x, 0));
            for (long x : q) list.add(new LongIntPair(x, 1));
            list.sort(Comparator.naturalOrder());
            int[] l = {w + 1, h + 1};
            int[] cnt = new int[2];
            long ans = 0;
            for (LongIntPair li : list) {
                ans += li.first * (l[1 - li.second] - cnt[1 - li.second]);
                cnt[li.second]++;
            }
            out.printLine(ans);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public long[] readLongArray(int size) {
            long[] array = new long[size];
            for (int i = 0; i < size; i++) {
                array[i] = readLong();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long readLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(long i) {
            writer.println(i);
        }

    }

    static class LongIntPair implements Comparable<LongIntPair> {
        public final long first;
        public final int second;

        public LongIntPair(long first, int second) {
            this.first = first;
            this.second = second;
        }

        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (o == null || getClass() != o.getClass()) {
                return false;
            }

            LongIntPair pair = (LongIntPair) o;

            return first == pair.first && second == pair.second;
        }

        public int hashCode() {
            int result = Long.hashCode(first);
            result = 31 * result + Integer.hashCode(second);
            return result;
        }

        public String toString() {
            return "(" + first + "," + second + ")";
        }

        public int compareTo(LongIntPair o) {
            int value = Long.compare(first, o.first);
            if (value != 0) {
                return value;
            }
            return Integer.compare(second, o.second);
        }

    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Scanner;

public class Main {
  Scanner sc = new Scanner(System.in);

  public static void main(String[] args) {
    new Main().run();
  }

  class Edge {
    boolean x;
    int u;
    int v;
    int cost;
  }

  class UF {
    int[] arr;

    UF(int n) {
      arr = new int[n];
      for (int i = 0; i < n; ++i) {
        arr[i] = i;
      }
    }

    void unite(int a, int b) {
      int A = parent(a);
      int B = parent(b);
      arr[B] = A;
    }

    boolean isSame(int a, int b) {
      int A = parent(a);
      int B = parent(b);
      return A == B;
    }

    int parent(int a) {
      if (a == arr[a]) {
        return a;
      }
      return arr[a] = parent(arr[a]);
    }
  }

  void run() {
    int w = ni();
    int h = ni();
    int[] p = new int[w];
    int[] q = new int[h];
    ArrayList<Edge> list = new ArrayList<>();
    for (int i = 0; i < w; ++i) {
      p[i] = ni();
      Edge e = new Edge();
      e.x = true;
      e.u = i;
      e.v = i + 1;
      e.cost = p[i];
      list.add(e);
    }
    for (int i = 0; i < h; ++i) {
      q[i] = ni();
      Edge e = new Edge();
      e.x = false;
      e.u = i;
      e.v = i + 1;
      e.cost = q[i];
      list.add(e);
    }

    int P = h + 1;
    int Q = w + 1;
    Collections.sort(list, (a, b) -> a.cost - b.cost);
    long sum = 0;
    for (int i = 0; i < list.size(); ++i) {
      Edge e = list.get(i);
      if (e.x) {
        sum += (long) P * (long) e.cost;
        --Q;
      } else {
        sum += (long) Q * (long) e.cost;
        --P;
      }
    }
    System.out.println(sum);
  }

  int ni() {
    return Integer.parseInt(sc.next());
  }

  void debug(Object... os) {
    System.err.println(Arrays.deepToString(os));
  }
}

