	class Pair implements Comparable<Pair> {
		int type;
		int cost;

		Pair(int type, int cost) {
			this.type = type;
			this.cost = cost;
		}

		public int compareTo(Pair s) {
			return cost - s.cost;
		}

		public String toString() {
			return "(" + type + ", " + cost + ")";
		}
	}

	public void solve() {
		int W = in.nextInt(), H = in.nextInt();
		int[] p = in.nextIntArray(W);
		int[] q = in.nextIntArray(H);

		Pair[] ps = new Pair[W+H];
		for (int j = 0; j < W; j++) {
			ps[j] = new Pair(0, p[j]);
		}
		for (int i = 0; i < H; i++) {
			ps[W+i] = new Pair(1, q[i]);
		}

		Arrays.sort(ps);

		long res = 0;
		long hcnt = 0, vcnt = 0;
		for (Pair pair : ps) {
			if (pair.type == 0) {
				res += pair.cost * (H + 1 - vcnt);
				hcnt++;
			} else {
				res += pair.cost * (W + 1 - hcnt);
				vcnt++;
			}
		}
		System.out.println(res);
		out.close();
	}

