    static class UnionFindTree {
        private int[] par;
        private int[] rank;
        private int[] sizes;

        UnionFindTree(int n) {
            par = new int[n];
            rank = new int[n];
            sizes = new int[n];
            for (int i = 0; i < n; i++) {
                par[i] = i;
                sizes[i] = 1;
            }
        }

        int root(int x) {
            if (par[x] == x) return x;
            else return par[x] = root(par[x]);
        }

        void unite(int[] a, int[] b) {
            for (int i = 0; i < a.length; i++)
                unite(a[i], b[i]);
        }

        void unite(int x, int y) {
            int rx = root(x);
            int ry = root(y);

            if (rx == ry) return;
            if (rank[rx] < rank[ry]) {
                par[rx] = ry;
                sizes[ry] += sizes[rx];
            } else {
                par[ry] = rx;
                sizes[rx] += sizes[ry];
                if (rank[rx] == rank[ry]) rank[rx]++;
            }
        }

        boolean isSame(int x, int y) {
            return root(x) == root(y);
        }

        int size(int x) {
            return sizes[root(x)];
        }
    }


