	static class TaskX {

		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int W = in.nextInt(), H = in.nextInt();
			long[] w = in.nextLongArray(W);
			long[] h = in.nextLongArray(H);
			Arrays.sort(w);
			Arrays.sort(h);

			long ans = 0;
			ans += Arrays.stream(w).sum();
			ans += Arrays.stream(h).sum();

			for (int i = 0; i < W; i++) {
				int count = H -lowerBound(h, w[i]);
				ans += w[i] * count;
			}

			for (int i = 0; i < H; i++) {
				int count = W - upperBound(w, h[i]);
				ans += h[i] * count;
			}

			out.println(ans);
		}
	}

	public static int lowerBound(long[] a, long obj) {
		int l = 0, r = a.length - 1;
		while (r - l >= 0) {
			int c = (l + r) / 2;
			if (obj <= a[c]) {
				r = c - 1;
			} else {
				l = c + 1;
			}
		}
		return l;
	}

	public static int upperBound(long[] a, long obj) {
		int l = 0, r = a.length - 1;
		while (r - l >= 0) {
			int c = (l + r) / 2;
			if (a[c] <= obj) {
				l = c + 1;
			} else {
				r = c - 1;
			}
		}
		return l;
	}

