		int h = sc.nextInt();

		long total = 0;
		int[] p = new int[w];
		for (int x = 0; x < w; x++) {
			p[x] = sc.nextInt();
			total += p[x];
		}
		int[] q = new int[h];
		for (int y = 0; y < h; y++) {
			q[y] = sc.nextInt();
			total += q[y];
		}

		int[] pp = p.clone();
		int[] qq = q.clone();
		Arrays.sort(pp);
		Arrays.sort(qq);

		for (int y = 0; y < h; y++) {
			int index = Arrays.binarySearch(pp, q[y]);
			if (index < 0) index = -(index + 1);
			total += (w - index) * q[y];
		}

		for (int x = 0; x < w; x++) {
			int index = Arrays.binarySearch(qq, p[x]);
			if (index < 0) index = -(index + 1);
			else index++;
			total += (h - index) * p[x];
		}

		out.println(total);
		out.flush();
	}

