public class Main {
  private static class Task {
    long solver(long[] P, long[] Q) {
      int H = Q.length;
      int W = P.length;

      long sum = 0;
      long[] sumQ = new long[H + 1];
      for (int i = 0; i < H; i++) {
        sumQ[i + 1] = Q[i];
      }
      for (int i = 0; i < H - 1; i++) {
        sumQ[i + 1] += sumQ[i];
      }
      for (int i = 0; i < H; i++) {
        sum += Q[i];
      }
      for (int p = 0; p < W; p++) {
        int n = Arrays.binarySearch(Q, P[p]);
        if (n < 0) {
          n = ~n;
        }
        sum += (H + 1 - n) * P[p];
        sum += sumQ[n];
      }
      return sum;
    }

    void solve(FastScanner in, PrintWriter out) throws Exception {
      int W = in.nextInt();
      int H = in.nextInt();
      long[] P = new long[W];
      for (int i = 0; i < W; i++) {
        P[i] = in.nextInt();
      }
      Arrays.sort(P);
      long[] Q = new long[H];
      for (int i = 0; i < H; i++) {
        Q[i] = in.nextInt();
      }
      Arrays.sort(Q);
      out.println(Math.min(solver(P, Q), solver(Q, P)));
    }
  }

