    long[] q = sc.nextLongList(H);

    Arrays.sort(p);
    Arrays.sort(q);

    int pPtr = 0;
    int qPtr = 0;

    long cost = 0;
    while (W > pPtr || H > qPtr) {
      if (W == pPtr) {
        cost += q[qPtr ++];
      } else if (H == qPtr) {
        cost += p[pPtr ++];
      } else if (q[qPtr] <= p[pPtr]) {
        cost += (W - pPtr + 1) * q[qPtr ++];
      } else {
        cost += (H - qPtr + 1) * p[pPtr ++];
      }
    }
    System.out.println(cost);
  }
