        for(int i = 1;i <= w;i++){
            int a = Integer.parseInt(br.readLine());
            ans += a*1L*(h + 1);
            p[i] = a;
        }
        Arrays.sort(p);
        long var = 0;
        long temp[] = p.clone();
        for(int i = 1;i < p.length;i++)
            p[i] += p[i - 1];
        for(int i = 1;i <= h;i++){
            int a = Integer.parseInt(br.readLine());
            ans += a*1L*(w + 1);
            int pos = determine(temp,a);
            var += a*pos + p[p.length - 1] - p[pos];
