public class Main {
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new TaskAdapter(), "daltao", 1 << 27);
        thread.start();
        thread.join();
    }

    static class TaskAdapter implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            FastInput in = new FastInput(inputStream);
            PrintWriter out = new PrintWriter(outputStream);
            TaskC solver = new TaskC();
            solver.solve(1, in, out);
            out.close();
        }
    }
    static class TaskC {
        public void solve(int testNumber, FastInput in, PrintWriter out) {
            int w = in.readInt();
            int h = in.readInt();
            int[] rowCost = new int[h];
            int[] colCost = new int[w];

            for (int i = 0; i < w; i++) {
                colCost[i] = in.readInt();
            }

            for (int i = 0; i < h; i++) {
                rowCost[i] = in.readInt();
            }

            Randomized.randomizedArray(rowCost, 0, rowCost.length);
            Randomized.randomizedArray(colCost, 0, colCost.length);
            Arrays.sort(rowCost);
            Arrays.sort(colCost);

            int rIndex = 0;
            int cIndex = 0;

            long cost = 0;
            while (rIndex < h || cIndex < w) {
                if (rIndex < h && (cIndex >= w || rowCost[rIndex] <= colCost[cIndex])) {
                    long need = w + 1 - cIndex;
                    cost += need * rowCost[rIndex];
                    rIndex++;
                } else {
                    long need = h + 1 - rIndex;
                    cost += need * colCost[cIndex];
                    cIndex++;
                }
            }

            out.println(cost);
        }

    }
    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }
    static class Randomized {
        static Random random = new Random();

        public static void randomizedArray(int[] data, int from, int to) {
            to--;
            for (int i = from; i <= to; i++) {
                int s = nextInt(i, to);
                int tmp = data[i];
                data[i] = data[s];
                data[s] = tmp;
            }
        }

        public static int nextInt(int l, int r) {
            return random.nextInt(r - l + 1) + l;
        }

    }
}

using System;

class Program
{
    class Heap
    {
        private int[] hp = new int[150000];
        private int size = 0;
        private void Swap(int _x, int _y)
        {
            int tt;
            tt = hp[_x];
            hp[_x] = hp[_y];
            hp[_y] = tt;
        }
        private void Mtup(int _x)
        {
            if (_x == 1) return;
            if (hp[_x] < hp[_x / 2])
            {
                Swap(_x, _x / 2);
                Mtup(_x / 2);
            }
        }
        private void Mtdn(int _x)
        {
            int tt;
            if (_x * 2 > size) return;
            if (_x * 2 + 1 > size) tt = _x * 2;
            else if (hp[_x * 2] < hp[_x * 2 + 1]) tt = _x * 2;
            else tt = _x * 2 + 1;
            if (hp[_x] > hp[tt])
            {
                Swap(_x, tt);
                Mtdn(tt);
            }
        }
        public void Add(int _n)
        {
            size++;
            hp[size] = _n;
            Mtup(size);
        }
        public int Popup()
        {
            Swap(1, size);
            size--;
            Mtdn(1);
            return hp[size + 1];
        }
    }
    static void Main(string[] args)
    {
        Heap P = new Heap();
        Heap Q = new Heap();
        int[] _P = new int[150000];
        int[] _Q = new int[150000];
        long[] sumP = new long[150000];
        long[] sumQ = new long[150000];
        string[] str = Console.ReadLine().Split(' ');
        int w = int.Parse(str[0]);
        int h = int.Parse(str[1]);
        int i;
        long ans = 0;
        for (i = 0; i < w; i++) P.Add(int.Parse(Console.ReadLine()));
        for (i = 0; i < h; i++) Q.Add(int.Parse(Console.ReadLine()));
        for (i = 0; i < w; i++)
        {
            _P[i] = P.Popup();
            if (i == 0) sumP[i] = _P[i];
            else sumP[i] = sumP[i - 1] + _P[i];
        }
        for (i = 0; i < h; i++)
        {
            _Q[i] = Q.Popup();
            if (i == 0) sumQ[i] = _Q[i];
            else sumQ[i] = sumQ[i - 1] + _Q[i];
        }
        int _pw = w - 1;
        int _ph = h - 1;
        while ((_pw >= 0) && (_ph >= 0))
        {
            if (_P[_pw] > _Q[_ph])
            {
                ans = ans + sumQ[_ph] + _P[_pw];
                _pw--;
            }
            else
            {
                ans = ans + sumP[_pw] + _Q[_ph];
                _ph--;
            }
        }
        if (_pw == -1) ans = ans + sumQ[_ph];
        else ans = ans + sumP[_pw];
        Console.WriteLine(ans);
    }
}

