struct P
{
    public bool y;
    public long l;
    public P(bool y,long l)
    {
        this.y=y;
        this.l=l;
    }
}

class Program
{
    private int W,H;
    private P[] PQ;

    private void Scan()
    {
        var l=Console.ReadLine().Split(' ');
        W=int.Parse(l[0]);
        H=int.Parse(l[1]);
        PQ=new P[H+W];
        for(int i=0;i<W;i++)
        {
            PQ[i]=new P(false,int.Parse(Console.ReadLine()));
        }
        for(int i=0;i<H;i++)
        {
            PQ[i+W]=new P(true,int.Parse(Console.ReadLine()));
        }
    }

    private void Calc()
    {
        Array.Sort(PQ,(aa,bb)=>aa.l.CompareTo(bb.l));
        long ans=0;
        long a=W+1;
        long b=H+1;
        foreach(var p in PQ)
        {
            if(!p.y)
            {
                ans+=b*p.l;
                a--;
            }
            else
            {
                ans+=a*p.l;
                b--;
            }
        }
        Console.WriteLine(ans);
    }

    public void Solve()
    {
        Scan();
        Calc();
    } 

    static void Main()
    {
        new Program().Solve();
    }
}

