			ll[] p,q;
			rl(w,out p);
			rl(h,out q);

			P<ll,ll,ll>[] pq = new P<ll, ll, ll>[w+h];
			for (int i = 0; i < w; i++)
			{
				pq[i]=new P<ll, ll, ll>(1,i,p[i]);
			}
			for (int i = 0; i < h; i++)
			{
				pq[i+w]=new P<ll, ll, ll>(2,i,q[i]);
			}
			pq.sort(3);

			long ans = 0;
			ll wc = 0;
			ll hc = 0;
			foreach (var e in pq)
			{
				if(e.A==1){
					ans += (h-hc+1)*e.C;
					wc++;
				}else{
					ans += (w-wc+1)*e.C;
					hc++;
				}
			}


			Lib_IO.wm(ans);
		}
