class Solve{
    int W;
    int H;
    int[] p;
    int[] q;
    public Solve(){}
    public static int Main(){
        new Solve().Calc();
        return 0;
    }
    void Calc(){
        getinput();
        int[] a = new int[W+H];
        long count = 0;
        for(int i=0;i<W+H;i++){
            a[i] = i;
        }
        Array.Sort(a,(i,j) => compare(i,j));
        {
            int w = 0;
            int h = 0;
            for(int i=W+H-1;i>=0;i--){
                if(a[i] >= W){
                    count += (long)(w+1)*(long)q[a[i]-W];
                    h++;
                }
                else{
                    count += (long)(h+1)*(long)p[a[i]];
                    w++;
                }
            }
        }
        Console.WriteLine(count);
    }
    int compare(int i,int j){
        int a;
        int b;
        if(i >= W){
            a = q[i-W];
        }
        else{
            a = p[i];
        }
        if(j >= W){
            b = q[j-W];
        }
        else{
            b = p[j];
        }
        return a-b;
    }
