	class Problem : IDisposable
	{
		bool IsGCJ;
		int Repeat;
		Scanner sc;
		Printer pr;
		public Problem(bool isGCJ, Scanner scanner, Printer printer)
		{
			sc = scanner;
			pr = printer;
			IsGCJ = isGCJ;
			if (isGCJ) Repeat = sc.Get<int>();
			else Read();
		}
		public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
		public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
		public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
		public void Solve()
		{
			if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
			else SolveOne();
		}
		public void Dispose()
		{
			sc.Dispose();
			pr.Dispose();
		}
		public int Size { get { return 1; } }
		//public const long Mod = 1000000007;
		public const long Mod = 924844033;
		RandomSFMT rand = Program.rand;
		int X, Y;
		int[] p, q;
		void Read()
		{
			sc.Read(out X, out Y);
			p = sc.ReadManyLines<int>(X);
			q = sc.ReadManyLines<int>(Y);
		}
		RMQI mp, mq;
		void SolveOne()
		{
			var r = new List<int>(p);
			r.AddRange(q);
			r.Sort((x, y) => y.CompareTo(x));
			var sum = 0L;
			for (var i = 0; i < X + Y; i++) sum += r[i] * ((i + 3L) / 2);
			pr.WriteLine(sum);
			//mp = new RMQI(p);
			//mq = new RMQI(q);
			//pr.WriteLine(DFS(0, X, 0, Y));
		}
		long DFS(int left, int right, int bot, int top)
		{
			//Console.WriteLine($"{left} {right} {bot} {top}");
			if (left == right && top == bot + 1) return q[bot];
			else if (bot == top && right == left + 1) return p[left];
			else if (left >= right || bot >= top) return 0;
			var minp = mp.Min(left, right);
			var minq = mq.Min(bot, top);
			//Console.WriteLine($"{minp.Item1} {minq.Item1}");
			if (minp.Item1 <= minq.Item1)
			{
				var x = minp.Item2;
				//Console.WriteLine($"{minp.Item1} * {top - bot + 1}");
				return DFS(left, x, bot, top) + DFS(x + 1, right, bot, top) + (top - bot + 1L) * minp.Item1;
			}
			else
			{
				var y = minq.Item2;
				//Console.WriteLine($"{minq.Item1} * {left - right + 1}");
				return DFS(left, right, bot, y) + DFS(left, right, y + 1, top) + (right - left + 1L) * minq.Item1;
			}
		}
	}
