        int W, H;
        int[] p, q;
        void Solve() {
            io.i(out W, out H);
            io.ini(out p, W);
            io.ini(out q, H);

            var ks = new Kruskal();
            ks.Init((W+1) * (H+1));
            W.REP(i => {
                H.REP(j => {
                    ks.AddPath(i + (W+1) * j, i + 1 + (W+1) * j,p[i]);
