using System;

class Program
{
    static int[] P = new int[150000];
    static int[] Q = new int[150000];
    static int ans = 0;
    static void Calc(int _x, int _y, int _w, int _h)
    {
        int px = _x, py = _y;
        int ii;
        if (_w == 0)
        {
            for (ii = 0; ii < _h; ii++) ans = ans + Q[_y + ii];
            return;
        }
        if (_h == 0)
        {
            for (ii = 0; ii < _w; ii++) ans = ans + P[_x + ii];
            return;
        }
        for (ii = 0; ii < _w; ii++) if (P[_x + ii] > P[px]) px = _x + ii;
        for (ii = 0; ii < _h; ii++) if (Q[_y + ii] > Q[py]) py = _y + ii;
        if (P[px] > Q[py])
        {
            ans = ans + P[px];
            Calc(_x, _y, px - _x, _h);
            Calc(px + 1, _y, _w + _x - px - 1, _h);
        }
        else
        {
            ans = ans + Q[py];
            Calc(_x, _y, _w, py - _y);
            Calc(_x, py + 1, _w, _h + _y - py - 1);
        }
    }
    static void Main(string[] args)
    {
        string[] str = Console.ReadLine().Split(' ');
        int w = int.Parse(str[0]);
        int h = int.Parse(str[1]);
        int i;
        for (i = 0; i < w; i++) P[i] = int.Parse(Console.ReadLine());
        for (i = 0; i < h; i++) Q[i] = int.Parse(Console.ReadLine());
        Calc(0, 0, w, h);
        Console.WriteLine(ans);
    }
}

