namespace AtCoder
{
    class Node
    {
        private int m_height;
        private Node m_parent;
        public Node()
        {
            m_height = 0;
            m_parent = this;
        }
        public Node Find()
        {
            if (m_parent == this) { return this; }

            Node parent = m_parent.Find();
            m_parent = parent;
            return parent;
        }
        public static void Unite(Node a, Node b)
        {
            Node p = a.Find();
            Node q = b.Find();
            if (p.m_height < q.m_height)
            {
                p.m_parent = q;
                q.m_height = Math.Max(p.m_height + 1, q.m_height);
            }
            else
            {
                q.m_parent = p;
                p.m_height = Math.Max(q.m_height + 1, p.m_height);
            }
        }
    }

    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        struct Point
        {
            public int x;
            public int y;
        }

        struct Edge
        {
            public int cost;
            public Point from;
            public Point to;
        }

        static long Solve(int W, int H, int[] P, int[] Q)
        {
            var nodes = new Node[H + 1][];
            for (int y = 0; y <= H; ++y)
            {
                nodes[y] = new Node[W + 1];
                for (int x = 0; x <= W; ++x) { nodes[y][x] = new Node(); }
            }
            var edges = new List<Edge>();
            for (int y = 0; y <= H; ++y)
            {
                for (int x = 0; x <= W; ++x)
                {
                    var from = new Point { x = x, y = y };
                    var to1 = new Point { x = x + 1, y = y };
                    var to2 = new Point { x = x, y = y + 1 };
                    if (to1.x <= W) { edges.Add(new Edge { cost = P[x], from = from, to = to1 }); }
                    if (to2.y <= H) { edges.Add(new Edge { cost = Q[y], from = from, to = to2 }); }
                }
            }
            long sum = 0;
            foreach (var edge in edges.OrderBy(edge => edge.cost))
            {
                var from = edge.from;
                var to = edge.to;
                var a = nodes[from.y][from.x];
                var b = nodes[to.y][to.x];
                if (a.Find() != b.Find())
                {
                    Node.Unite(a, b);
                    sum += edge.cost;
                }
            }
            return sum;
        }

        static void Main(string[] args)
        {
            int[] V = ReadInts();
            int W = V[0], H = V[1];
            var P = new int[W];
            for (int i = 0; i < W; ++i) { P[i] = ReadInt(); }
            var Q = new int[H];
            for (int i = 0; i < H; ++i) { Q[i] = ReadInt(); }
            Console.WriteLine(Solve(W, H, P, Q));
        }
    }
}

