class mymath
{
    int Mod = 1000000007;
    public void setMod(int m) { Mod = m; }
    public bool isprime(long a)
    {
        if (a < 2) return false;
        for (long i = 2; i * i <= a; i++) if (a % i == 0) return false;
        return true;
    }
    public bool[] sieve(int n)
    {
        var isp = new bool[n + 1];
        for (int i = 2; i <= n; i++) isp[i] = true;
        for (int i = 2; i * i <= n; i++) if (isp[i]) for (int j = i * i; j <= n; j += i) isp[j] = false;
        return isp;
    }
    public List<int> getprimes(int n)
    {
        var prs = new List<int>();
        var isp = sieve(n);
        for (int i = 2; i <= n; i++) if (isp[i]) prs.Add(i);
        return prs;
    }
    public long[][] E(int n)
    {
        var ret = new long[n][];
        for (int i = 0; i < n; i++)
        {
            ret[i] = new long[n];
            ret[i][i] = 1;
        }
        return ret;
    }
    public long[][] powmat(long[][] A, long n)
    {
        if (n == 0) return E(A.Length);
        var t = powmat(A, n / 2);
        if ((n & 1) == 0) return mulmat(t, t);
        return mulmat(mulmat(t, t), A);
    }
    public long dot(long[] x, long[] y)
    {
        int n = x.Length;
        long ret = 0;
        for (int i = 0; i < n; i++) ret = (ret + x[i] * y[i]) % Mod;
        return ret;
    }
    public long[][] trans(long[][] A)
    {
        int n = A[0].Length, m = A.Length;
        var ret = new long[n][];
        for (int i = 0; i < n; i++)
        {
            ret[i] = new long[m];
            for (int j = 0; j < m; j++) ret[i][j] = A[j][i];
        }
        return ret;
    }
    public long[] mulmat(long[][] A, long[] x)
    {
        int n = A.Length;
        var ret = new long[n];
        for (int i = 0; i < n; i++) ret[i] = dot(x, A[i]);
        return ret;
    }
    public long[][] mulmat(long[][] A, long[][] B)
    {
        int n = A.Length;
        var Bt = trans(B);
        var ret = new long[n][];
        for (int i = 0; i < n; i++) ret[i] = mulmat(Bt, A[i]);
        return ret;
    }
    public long[] addmat(long[] x, long[] y)
    {
        int n = x.Length;
        var ret = new long[n];
        for (int i = 0; i < n; i++) ret[i] = (x[i] + y[i]) % Mod;
        return ret;
    }
    public long[][] addmat(long[][] A, long[][] B)
    {
        int n = A.Length;
        var ret = new long[n][];
        for (int i = 0; i < n; i++) ret[i] = addmat(A[i], B[i]);
        return ret;
    }
    public long powmod(long a, long b)
    {
        if (a >= Mod) return powmod(a % Mod, b);
        if (a == 0) return 0;
        if (b == 0) return 1;
        var t = powmod(a, b / 2);
        if ((b & 1) == 0) return t * t % Mod;
        return t * t % Mod * a % Mod;
    }
    public long inv(long a) { return powmod(a, Mod - 2); }
    public long gcd(long a, long b)
    {
        while (b > 0) { var t = a % b; a = b; b = t; }
        return a;
    }
    public long lcm(long a, long b) { return a * (b / gcd(a, b)); }
    public long comb(int n, int r)
    {
        if (n < 0 || r < 0 || r > n) return 0;
        if (n - r < r) r = n - r;
        if (r == 0) return 1;
        if (r == 1) return n;
        var numerator = new int[r];
        var denominator = new int[r];
        for (int k = 0; k < r; k++)
        {
            numerator[k] = n - r + k + 1;
            denominator[k] = k + 1;
        }
        for (int p = 2; p <= r; p++)
        {
            int pivot = denominator[p - 1];
            if (pivot > 1)
            {
                int offset = (n - r) % p;
                for (int k = p - 1; k < r; k += p)
                {
                    numerator[k - offset] /= pivot;
                    denominator[k] /= pivot;
                }
            }
        }
        long ret = 1;
        for (int k = 0; k < r; k++) if (numerator[k] > 1) ret = ret * numerator[k] % Mod;
        return ret;
    }
}
class Search
{
    // nより大きいの項のindexのうち最小のものを返す
    // n以下の項のindexのうち最大のもの+1を返す
    // そこに挿入
    public int UpperBound<T>(IList<T> a, T n) where T : IComparable<T>
    {
        if (a.Count == 0) return 0;
        int l = 0, r = a.Count - 1;
        while (l < r)
        {
            int m = (l + r) >> 1;
            if (a[m].CompareTo(n) <= 0)
            {
                if (a[m + 1].CompareTo(n) > 0) return m + 1;
                l = m + 1;
            }
            else r = m - 1;
        }
        if (a[l].CompareTo(n) <= 0) return l + 1;
        return l;
    }

    // n未満の項のindexのうち最大のもの+1を返す
    // n以上の項のindexのうち最小のものを返す
    // そこに挿入
    public int LowerBound<T>(IList<T> a, T n) where T : IComparable<T>
    {
        if (a.Count == 0) return 0;
        int l = 0, r = a.Count - 1;
        while (l < r)
        {
            int m = (l + r) >> 1;
            if (a[m].CompareTo(n) < 0)
            {
                if (a[m + 1].CompareTo(n) >= 0) return m + 1;
                l = m + 1;
            }
            else r = m - 1;
        }
        if (a[l].CompareTo(n) < 0) return l + 1;
        return l;
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
class Program
{
	static void Main()
	{
    long answer = 0;
		string[] input = Console.ReadLine().Split(' ');//Splitで区切り文字を指定して複数個受け取る。
		long w = long.Parse(input[0]);
		long h = long.Parse(input[1]);
    long wMemo = h+1;
    long hMemo = w+1;
    long[][] pathArray = new long[w+h][];
    for(long i = 0; i < w+h; i++)
    {
      pathArray[i] = new long[2];//0は横、1は縦
    }

    for(long i = 0; i < w; i++)
    {
      pathArray[i][0] = long.Parse(Console.ReadLine());
      pathArray[i][1] = 0;
    }

    for(long i = w; i < w+h; i++)
    {
      pathArray[w+i][0] = long.Parse(Console.ReadLine());
      pathArray[w+i][1] = 1;
    }

    Array.Sort(pathArray, (a, b) => a[0].CompareTo(b[0]));

    for(long i = 0; i < w+h; i++)
    {
      if(pathArray[i][1] == 0)
      {
        hMemo--;
        answer += pathArray[i][0] * wMemo;
      }else
      {
        wMemo--;
        answer += pathArray[i][0] * hMemo;
      }
    }  

		Console.WriteLine(answer);
	}
}

