using System;
using System.Collections.Generic;
class Solve{
    int W;
    int H;
    int[] p:
    int[] q;
    public Solve(){}
    public static int Main(){
        new Solve().Calc();
        return 0;
    }
    void Calc(){
        getinput();
        int[] a = new int[W+H];
        long count = 0;
        for(int i=0;i<W+H;i++){
            a[i] = i;
        }
        Array.Sort(a,(i,j) => compare(i,j));
        {
            int w = 0;
            int h = 0;
            for(int i=W+H-1;i>=0;i--){
                if(a[i] >= W){
                    count += (long)w*(long)q[i-W];
                    h++;
                }
                else{
                    count += (long)h*(long)p[i];
                    w++;
                }
            }
        }
        Console.WriteLine(count);
    }
    int compare(int i,int j){
        int a;
        int b;
        if(i >= W){
            a = q[i-W];
        }
        else{
            a = p[i];
        }
        if(j >= W){
            b = q[j-W];
        }
        else{
            b = p[j];
        }
        return a-b;
    }
    void getinput(){
        string[] str = Console.ReadLine().Split(' ');
        W = int.Parse(str[0]);
        H = int.Parse(str[1]);
        p = new int[W];
        q = new int[H];
        for(int i=0;i<W;i++){
            p[i] = int.Parse(Console.ReadLine());
        }
        for(int i=0;i<H;i++){
            q[i] = int.Parse(Console.ReadLine());
        }
    }    
}

