namespace Program
{
    public class Solver
    {
        public void Solve()
        {
            var w = sc.Integer();
            var h = sc.Integer();
            var A = new long[w + h];
            for (int i = 0; i < w + h; i++)
                A[i] = sc.Long() * 1000000 + i;
            var a = w; var b = h;
            Array.Sort(A);
            long ans = 0;
            foreach (var x in A)
            {
                var v = x / 1000000;
                var id = x % 1000000;
                if (id < w)
                {
                    ans += v * (b + 1);
                    a--;
                }
                else
                {
                    ans += v * (a + 1);
                    b--;
                }
            }
            IO.Printer.Out.WriteLine(ans);

        }
        public IO.StreamScanner sc = new IO.StreamScanner(Console.OpenStandardInput());
        static T[] Enumerate<T>(int n, Func<int, T> f) { var a = new T[n]; for (int i = 0; i < n; ++i) a[i] = f(i); return a; }
        static public void Swap<T>(ref T a, ref T b) { var tmp = a; a = b; b = tmp; }
    }
}
