func main() {
	fp := os.Stdin
	wfp := os.Stdout
	cnt := 0

	if os.Getenv("MASPY") == "ますピ" {
		fp, _ = os.Open(os.Getenv("BEET_THE_HARMONY_OF_PERFECT"))
		cnt = 1
	}
	if os.Getenv("MASPYPY") == "ますピッピ" {
		wfp, _ = os.Create(os.Getenv("NGTKANA_IS_GENIUS10"))
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)
	solve(scanner, writer)
	for i := 0; i < cnt; i++ {
		fmt.Fprintln(writer, "-----------------------------------")
		solve(scanner, writer)
	}
	writer.Flush()
}

func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	w := getNextInt(scanner)
	h := getNextInt(scanner)
	pp := make([]int, w)
	qq := make([]int, h)
	for i := 0; i < w; i++ {
		pp[i] = getNextInt(scanner)
	}

	sort.Ints(pp)
	for i := 0; i < h; i++ {
		qq[i] = getNextInt(scanner)
	}

	sort.Ints(qq)
	if pp[0] > qq[0] {
		pp, qq = qq, pp
		w, h = h, w
	}

	ss := make([]int64, h+1)
	for i := 0; i < h; i++ {
		ss[i+1] = ss[i] + int64(qq[i])
	}
	var ans int64
	ans = int64(h+1)*int64(pp[0]) + ss[h]
	for i := 1; i < w; i++ {
		l := -1
		r := h
		for l+1 < r {
			m := (l + r) >> 1
			if qq[m] < pp[i] {
				l = m
				continue
			}
			r = m
		}
		ans += int64(h-r+1)*int64(pp[i]) + ss[r]
	}
	fmt.Fprintln(writer, ans)
}

