type path struct {
	xy     rune
	num    int
	weight int
}

type paths []path

func (p paths) Len() int {
	return len(p)
}

func (p paths) Swap(i, j int) {
	p[i], p[j] = p[j], p[i]
}

func (p paths) Less(i, j int) bool {
	return p[i].weight < p[j].weight
}

func main() {
	sc = bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 0), 1000000001*3)
	sc.Split(bufio.ScanWords)
	w, h := nextInt(), nextInt()
	var paths paths = make([]path, w+h)
	for wi := 0; wi < w; wi++ {
		p := nextInt()
		paths[wi] = path{'y', wi, p}
	}
	for hi := 0; hi < h; hi++ {
		p := nextInt()
		paths[w+hi] = path{'x', hi, p}
	}
	sort.Sort(paths)

	ans := 0
	xRemain, yRemain := w+1, h+1
	for _, p := range paths {
		switch {
		case p.xy == 'x':
			ans += p.weight * xRemain
			yRemain--
		case p.xy == 'y':
			ans += p.weight * yRemain
			xRemain--
		}
	}
	fmt.Println(ans)
}

