import sys

def build_graph(W, H, p, q):
    vetex = W * H
    graph = [[sys.maxint]*vetex for _ in range(vetex)]
    for i in range(W):
        for j in range(H):
            x = j*W + i
            if i+1 < W:
                graph[x][x+1] = p[i]
            if j+1 < H:
                graph[x][x+W] = q[j]
    return graph
def prim(graph,n):  
    dis=[0]*n  
    pre=[0]*n  
    flag=[False]*n  
    flag[0]=True  
    k=0  
    for i in range(n):  
        dis[i]=graph[k][i]  
    for j in range(n-1):  
        mini=sys.maxint  
        for i in range(n):  
            if mini>dis[i] and not flag[i]:  
                mini=dis[i]  
                k=i  
        if k==0: 
            return  
        flag[k]=True  
        for i in range(n):  
            if dis[i]>graph[k][i] and not flag[i]:  
                dis[i]=graph[k][i]  
                pre[i]=k  
    return dis,pre

