def mst_prim(adj, n):
    pred = defaultdict(lambda: -1)
    key = defaultdict(lambda: float('inf'))
    key[0] = 0
    pq = [(key[v], v) for v in range(n)]
    heapify(pq)
    in_pq = array('B', (True for _ in range(n)))
    while pq:
        _,u = heappop(pq)
        in_pq[u] = False
        for v, v_cost in adj[u]:
            if in_pq[v]:
                weight = v_cost
                if weight < key[v]:
                    pred[v] = u
                    key[v] = weight
                    heappush(pq, (weight, v))
                    in_pq[v] = True
    return (pred, key)

