        self.x = x
        self.y = y
    def __repr__(self):
        return '({},{})'.format(self.x, self.y)

def dist(p1, p2, p, q):
    if (p1.x,p1.y) == (p2.x, p2.y):
        return float('inf')
    if p1.x == p2.x and abs(p1.y - p2.y) == 1:
        return q[min(p1.y, p2.y)]
    elif p1.y == p2.y and abs(p1.x - p2.x) == 1:
        return p[min(p1.x, p2.x)]
    return float('inf')

def mst(ps, p, q):
    m =  [[dist(ps[i], ps[j], p, q) for i in range(len(ps))] for j in range(len(ps))]

    X = set([0])
    Y = set(range(len(ps))[1:])
    cost = 0
    edges = []
    while len(Y) != 0:
        mcost = float('inf')
        edge = None
        for ex in X:
            for ey in Y:
                if mcost > m[ex][ey]:
                    mcost = m[ex][ey]
                    edge = [ex, ey]
        X.add(edge[1])
        Y.remove(edge[1])

        cost += mcost
        edges.append(edge)
    return cost, edges

