    P, Q = {}, [(0, None, s)]   
    while Q:
        _, p, u = heappop(Q)
        if u in P: 
            continue
        P[u] = p
        for v, w in G[u].items():
            heappush(Q, (w, u, v))
    return sum(G[x][y] for x,y in P.items() if y != None)

