def build_graph(W, H, p, q):
    graph = nx.Graph()
    for i in range(W):
        for j in range(H):
            x = j*W + i
            if i+1 < W:
                graph.add_edge(x, x+1, weight=p[i])
            if j+1 < H:
                graph.add_edge(x, x+W, weight=q[j])
    return graph


def prim(G, s):
    P, Q = {}, [(0, None, s)]   
    while Q:
        _, p, u = heappop(Q)
        if u in P: continue
        P[u] = p
        for v, w in G[u].items():
            heappush(Q, (w, u, v))
    return sum(G[key][P[key]]['weight'] for key in P if P[key] != None)

