// Input macro from https://qiita.com/tanakh/items/0ba42c7ca36cd29d0ac8
macro_rules! input {
  (source = $s:expr, $($r:tt)*) => {
    let mut iter = $s.split_whitespace();
    input_inner!{iter, $($r)*}
  };
  ($($r:tt)*) => {
    #[allow(unused_mut)]
    let mut s = {
      use std::io::Read;
      let mut s = String::new();
      std::io::stdin().read_to_string(&mut s).unwrap();
      s
    };
    let mut iter = s.split_whitespace();
    input_inner!{iter, $($r)*}
  };
}

macro_rules! input_inner {
  ($iter:expr) => {};
  ($iter:expr, ) => {};

  ($iter:expr, $var:ident : $t:tt $($r:tt)*) => {
    let $var = read_value!($iter, $t);
    input_inner!{$iter $($r)*}
  };
}

macro_rules! read_value {
  ($iter:expr, ( $($t:tt),* )) => {
    ( $(read_value!($iter, $t)),* )
  };

  ($iter:expr, [ $t:tt ; $len:expr ]) => {
    (0..$len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
  };

  ($iter:expr, chars) => {
    read_value!($iter, String).chars().collect::<Vec<char>>()
  };

  ($iter:expr, usize1) => {
    read_value!($iter, usize) - 1
  };

  ($iter:expr, $t:ty) => {
    $iter.next().unwrap().parse::<$t>().expect("Parse error")
  };
}

fn main() {
  input! {
    w: usize,
    h: usize,
    ps: [i64; w],
    qs: [i64; h],
  }
  let mut edges: Vec<_> = ps.into_iter().map(|p| (p, true)).chain(qs.into_iter().map(|q| (q, false))).collect();
  edges.sort_unstable();
  let mut total = 0;
  let mut we = w as i64 + 1;
  let mut he = h as i64 + 1;
  for &(c, horizontal) in edges.iter() {
    if horizontal {
      total += he * c;
      we -= 1;
    } else {
      total += we * c;
      he -= 1;
    }
  }

  println!("{}", total);
}

pub mod io {
    use std::io;

    pub fn read_line() -> String {
        let mut s = String::new();
        io::stdin().read_line(&mut s).unwrap();
        s.trim_right().to_owned()
    }

    pub trait Read {
        fn read(s: &str) -> Self;
    }

    macro_rules! def_read {
        ($t: ty) => {
            impl Read for $t {
                fn read(s: &str) -> $t {
                    s.parse().unwrap()
                }
            }
        }
    }

    def_read!(i32);
    def_read!(i64);
    def_read!(isize);
    def_read!(usize);
    def_read!(f64);

    impl<T: Read> Read for Vec<T> {
        fn read(s: &str) -> Self { s.split_whitespace().map(|w| T::read(w)).collect() }
    }

    macro_rules! def_read_tuple {
        ($($t: ident),*) => {
            impl<$($t : Read + Default),*> Read for ($($t),*) {
                fn read(s: &str) -> Self {
                    let ws = s.split_whitespace().collect::<Vec<_>>();
                    let mut i = 0;
                    ( $({i += 1; $t::read(ws[i - 1])}),* )
                }
            }
        };
    }

    def_read_tuple!(T0, T1);
    def_read_tuple!(T0, T1, T2);
    def_read_tuple!(T0, T1, T2, T3);
    def_read_tuple!(T0, T1, T2, T3, T4);

    pub fn readln<T: Read>() -> T { T::read(&read_line()) }
}

fn main() {
    let (w, h): (usize, usize) = io::readln();
    let ps: Vec<i64> = (0..w).map(|_|io::readln()).collect();
    let qs: Vec<i64> = (0..h).map(|_|io::readln()).collect();

    let mut ord: Vec<(i64, usize, usize)> =
        ps.iter().enumerate().map(|(i, &v)| (v, i, 0))
        .chain(qs.iter().enumerate().map(|(j, &v)| (v, j, 1)))
        .collect();
    ord.sort();

    let mut ans = 0;
    let mut xs = 0;
    let mut ys = 0;

    for (v, _, d) in ord {
        if d == 0 {
            ans += v * (h + 1 - ys) as i64;
            xs += 1;
        } else {
            ans += v * (w + 1 - xs) as i64;
            ys += 1;
        }
    }

    println!("{}", ans);
}

