fn solve() {
    let out = stdout();
    let mut out = BufWriter::new(out.lock());

    input!{
        w:usize,h:usize,
        p:[i64;w],
        q:[i64;h],
    }

    let mut n_verti = 0;
    let mut n_horiz = 0;

    let mut evt = vec![];
    for pi in p {
        evt.push((pi, 0));
    }
    for qi in q {
        evt.push((qi, 1));
    }
    evt.sort();
    evt.reverse();

    let mut ans = 0;
    while let Some((cost, dir)) = evt.pop() {
        if dir == 0 {
            ans += cost * (h+1-n_horiz) as i64;
            n_verti += 1;
        } else {
            ans += cost * (w+1-n_verti) as i64;
            n_horiz += 1;
        }
    }

    println!("{}", ans);
}

