type BoxResult<T> = Result<T, Box<std::error::Error>>;

fn main() {
    let mut scanner = Scanner::new(stdin());
    let params = scanner.read_vector::<usize>().unwrap();
    let (w, h) = (params[0], params[1]);
    let mut costs = vec![];
    for _ in 0..w {
        let c = scanner.read::<usize>().unwrap();
        costs.push((c, 1));
    }
    for _ in 0..h {
        let c = scanner.read::<usize>().unwrap();
        costs.push((c, 2));
    }
    costs.sort();
    let mut ans = 0;
    let (mut col, mut row) = (w + 1, h + 1);
    for (c, t) in costs {
        if t == 1 {
            ans += row * c;
            if col > 0 {
                col -= 1;
            }
        } else {
            ans += col * c;
            if row > 0 {
                row -= 1;
            }
        }
    }
    println!("{}", ans);
}

