    for _ in 0..w {
        let p: i64 = read();
        graph.push((p, 0));
    }
    for _ in 0..h {
        let q: i64 = read();
        graph.push((q, 1));
    }
    graph.sort();
    let mut a = (w + 1) as i64;
    let mut b = (h + 1) as i64;
    let mut ans: i64 = 0;
    for i in &graph {
        let (pq, po) = *i;
        if po == 0 {
