use std::io::prelude::*;
use std::io;
use std::cmp::*;

#[derive(PartialEq, Eq, Debug)]
enum Road {
    P(u64),
    Q(u64),
}

impl PartialOrd for Road {
    fn partial_cmp(&self, other: &Road) -> Option<Ordering> {
        let cs = match *self {
            P(c) | Q(c) => c,
        };
        let co = match *other {
            P(c) | Q(c) => c,
        };
        cs.partial_cmp(&co)
    }
}

impl Ord for Road {
    fn cmp(&self, other: &Road) -> Ordering {
        self.partial_cmp(other).unwrap()
    }
}

