    let mut pq: Vec<_> = p.iter()
        .map(|c| P(*c))
        .chain(q.iter()
            .map(|c| Q(*c)))
        .collect();
    pq.sort();
    let mut a = w as u64 + 1;
    let mut b = h as u64 + 1;
    pq.iter()
        .map({
            |e| match *e {
                P(c) => {
