fn main() {
    input! {
        W:usize,H:usize,pq:[i64;W+H]
    }
    let mut uf = UnionFind::new((W + 1) * (H + 1));
    let mut pq = pq.iter().enumerate().collect::<Vec<(usize, &i64)>>();
    pq.sort_by_key(|(i, val)| *val);

    // 点(i,j)の名前をi* (H+1) +j
    let mut a = W + 1;
    let mut b = H + 1;
    let mut ans = 0;
    for &(k, cost) in pq.iter() {
        if k < W {
            let i = k;
            // 横の辺
            for j in 0..H + 1 {
                if !uf.equiv(i * (H + 1) + j, (i + 1) * (H + 1) + j) {
                    uf.union(i * (H + 1) + j, (i + 1) * (H + 1) + j);
                    ans += cost;
                };
            }
            b -= 1;
        } else {
            // 縦の辺
            let j = k - W;
            for i in 0..W + 1 {
                if !uf.equiv(i * (H + 1) + j, i * (H + 1) + j + 1) {
                    uf.union(i * (H + 1) + j, i * (H + 1) + j + 1);
                    ans += cost;
                };
            }
            a -= 1;
        }
    }
    println!("{}", ans);
}

use std::io::{stdin, Read, StdinLock};
