fn main() {
    let cin = stdin();
    let mut scan = Scanner::new(cin.lock());
    let mut w = scan.read::<usize>();
    let mut h = scan.read::<usize>();
    let p = scan.readn::<i64>(w);
    let q = scan.readn::<i64>(h);
    let mut heap = BinaryHeap::new();
    for i in 0..w {
        heap.push((Rev(p[i]), true));
    }
    for i in 0..h {
        heap.push((Rev(q[i]), false));
    }
    w += 1;
    h += 1;
    let mut ret = 0;
    while let Some((Rev(t), b)) = heap.pop() {
        if b {
            ret += t * h as i64;
            w -= 1;
        } else {
            ret += t * w as i64;
            h -= 1;
        }
    }
    println!("{}", ret);
}

#[derive(Eq, PartialEq, Clone, Debug)]
pub struct Rev<T>(pub T);

impl<T: PartialOrd> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Rev<T>) -> Option<std::cmp::Ordering> {
        other.0.partial_cmp(&self.0)
    }
}

impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Rev<T>) -> std::cmp::Ordering {
        other.0.cmp(&self.0)
    }
}

