fn solve() {
    let (w,h) = get!(usize, usize);
    let p = get!(usize; w);
    let q = get!(usize; h);

    let mut vec = Vec::new();
    for e in p {
        vec.push((e, false));
    }
    for e in q {
        vec.push((e, true));
    }

    vec.sort();
    let mut wr = w+1;
    let mut hr = h+1;
    let mut res = 0usize;
    for (e, b) in vec {
        if b {
            res += e*wr;
            hr -= 1;
        } else {
            res += e*hr;
            wr -= 1;
        }
    }
    println!("{}", res);
}
